window.LOCALE_DATA={"copy":{"欢迎":{"zh-CN":"欢迎","zh-TW":"歡迎","en":"Welcome","ja":"ようこそ","th":"ยินดีต้อนรับ","ar":"مرحبًا"},"人类鉴别":{"zh-CN":"人类鉴别","zh-TW":"人類鑒別","en":"A human moment","ja":"人間らしさのひととき","th":"ช่วงเวลาแห่งความเป็นมนุษย์","ar":"لحظة إنسانية"},"此刻心情":{"zh-CN":"此刻心情","zh-TW":"此刻心情","en":"Your feeling","ja":"今の気持ち","th":"ความรู้สึกตอนนี้","ar":"شعورك الآن"},"与字相遇":{"zh-CN":"与字相遇","zh-TW":"與字相遇","en":"Meet your symbol","ja":"文字との出会い","th":"พบกับอักษรของคุณ","ar":"لقاء مع رمزك"},"一个字":{"zh-CN":"一个字","zh-TW":"一個字","en":"Your symbol","ja":"あなたの一文字","th":"อักษรของคุณ","ar":"رمزك"},"留下此刻":{"zh-CN":"留下此刻","zh-TW":"留下此刻","en":"Keep this moment","ja":"このひとときを残す","th":"เก็บช่วงเวลานี้ไว้","ar":"احتفظ بهذه اللحظة"},"一 字 · 一 刻":{"zh-CN":"一 字 · 一 刻","zh-TW":"一 字 · 一 刻","en":"ONE SYMBOL · ONE MOMENT","ja":"一文字・ひととき","th":"หนึ่งอักษร · หนึ่งช่วงเวลา","ar":"رمز واحد · لحظة واحدة"},"A LITTLE SPACE WITHIN":{"zh-CN":"A LITTLE SPACE WITHIN","zh-TW":"A LITTLE SPACE WITHIN","en":"A LITTLE SPACE WITHIN","ja":"心の中に、小さな余白を","th":"พื้นที่เล็ก ๆ ภายในใจ","ar":"مساحة صغيرة في داخلك"},"一个字，\n回应你的此刻。":{"zh-CN":"一个字，\n回应你的此刻。","zh-TW":"一個字，\n回應你的此刻。","en":"One symbol.\nFor this moment.","ja":"一文字が、\n今のあなたに応える。","th":"หนึ่งอักษร\nตอบรับความรู้สึกตอนนี้","ar":"رمز واحد،\nيستجيب للحظتك."},"不必急着找到答案，先听见自己。":{"zh-CN":"不必急着找到答案，先听见自己。","zh-TW":"不必急著找到答案，先聽見自己。","en":"No need to rush. First, listen to yourself.","ja":"答えを急がず、まず自分の声を聴いて。","th":"ไม่ต้องรีบหาคำตอบ ลองฟังตัวเองก่อน","ar":"لا تتعجل الإجابة. أصغِ إلى نفسك أولًا."},"轻触，开启你的片刻":{"zh-CN":"轻触，开启你的片刻","zh-TW":"輕觸，開啟你的片刻","en":"Touch to begin your moment","ja":"そっと触れて、ひとときを始める","th":"แตะเบา ๆ เพื่อเริ่มช่วงเวลาของคุณ","ar":"المس برفق لتبدأ لحظتك"},"这一小段时间，只属于你。":{"zh-CN":"这一小段时间，只属于你。","zh-TW":"這一小段時間，只屬于你。","en":"A few minutes, just for you.","ja":"この少しの時間は、あなただけのもの。","th":"เวลาสั้น ๆ นี้เป็นของคุณ","ar":"هذه الدقائق لك وحدك."},"感受":{"zh-CN":"感受","zh-TW":"感受","en":"Feel","ja":"感じる","th":"รับรู้","ar":"اشعر"},"相遇":{"zh-CN":"相遇","zh-TW":"相遇","en":"Discover","ja":"出会う","th":"พบเจอ","ar":"اكتشف"},"照见":{"zh-CN":"照见","zh-TW":"照見","en":"Reflect","ja":"見つめる","th":"มองเห็นใจ","ar":"تأمّل"},"在需要被支持的时刻，\n有一个可以随身携带的指尖绿洲。":{"zh-CN":"在需要被支持的时刻，\n有一个可以随身携带的指尖绿洲。","zh-TW":"在需要被支持的時刻，\n有一個可以隨身攜帶的指尖綠洲。","en":"A small place of calm,\nwherever you find yourself.","ja":"支えがほしいとき、\n指先に小さな安らぎの場所を。","th":"ในเวลาที่ต้องการกำลังใจ\nมีมุมสงบเล็ก ๆ อยู่ใกล้มือ","ar":"حين تحتاج إلى الدعم،\nتجد مساحة هادئة في متناول يدك."},"公益体验 · 还可体验 {n} 次":{"zh-CN":"公益体验 · 还可体验 {n} 次","zh-TW":"公益體驗 · 還可體驗 {n} 次","en":"Community experience · {n} remaining","ja":"無料体験・残り{n}回","th":"ประสบการณ์ฟรี · เหลือ {n} ครั้ง","ar":"تجربة مجانية · تبقّى {n}"},"七次相遇之后，愿陪伴继续。":{"zh-CN":"七次相遇之后，愿陪伴继续。","zh-TW":"七次相遇之后，愿陪伴繼續。","en":"After seven encounters, the journey can continue.","ja":"七つの出会いのあとも、寄り添いを。","th":"หลังการพบกันเจ็ดครั้ง ขอให้การดูแลนี้ดำเนินต่อไป","ar":"بعد سبعة لقاءات، نأمل أن تستمر هذه الرفقة."},"这个字，正在回应你":{"zh-CN":"这个字，正在回应你","zh-TW":"這個字，正在回應你","en":"What this symbol offers you","ja":"この文字が、あなたに伝えること","th":"สิ่งที่อักษรนี้อยากบอกคุณ","ar":"ما يقدّمه لك هذا الرمز"},"REFLECT":{"zh-CN":"REFLECT","zh-TW":"REFLECT","en":"REFLECT","ja":"見つめる","th":"มองเห็นใจ","ar":"تأمّل"},"把休息，留在手心":{"zh-CN":"把休息，留在手心","zh-TW":"把休息，留在手心","en":"A little rest to hold","ja":"休息を、手のひらに","th":"เก็บการพักไว้ในมือ","ar":"شيء من الراحة بين يديك"},"「休」字手作":{"zh-CN":"「休」字手作","zh-TW":"「休」字手作","en":"The Rest handcraft","ja":"「休」の手作り","th":"งานฝีมืออักษร「休」แห่งการพัก","ar":"عمل يدوي لرمز الراحة「休」"},"棉麻布上的休息表情，与甲骨文休字卡片的手作成品示意":{"zh-CN":"棉麻布上的休息表情，与甲骨文休字卡片的手作成品示意","zh-TW":"棉麻布上的休息表情，與甲骨文休字卡片的手作成品示意","en":"Rest embroidery on linen with an oracle character card","ja":"綿麻布の休息の表情と甲骨文字カードの作品例","th":"ตัวอย่างงานปักสีหน้าผ่อนคลายบนผ้าฝ้ายลินินกับการ์ดอักษรกระดองเต่า","ar":"نموذج تطريز لوجه مستريح على قماش كتاني مع بطاقة رمز قديم"},"从屏幕里的一个字，到可以亲手制作、轻轻握住的陪伴。":{"zh-CN":"从屏幕里的一个字，到可以亲手制作、轻轻握住的陪伴。","zh-TW":"從屏幕里的一個字，到可以親手制作、輕輕握住的陪伴。","en":"From a symbol on screen to something made by hand and held close.","ja":"画面の一文字から、自分の手で作り、そっと握れる存在へ。","th":"จากอักษรบนจอ สู่สิ่งที่ทำด้วยมือและจับไว้เป็นเพื่อนได้","ar":"من رمز على الشاشة إلى رفيق تصنعه بيديك وتحمله برفق."},"查看手作材料与成品":{"zh-CN":"查看手作材料与成品","zh-TW":"查看手作材料與成品","en":"See materials and finished example","ja":"材料と作品例を見る","th":"ดูวัสดุและตัวอย่างชิ้นงาน","ar":"شاهد المواد ونموذج العمل"},"手作概念展示 · 材料包筹备中，暂未开放购买":{"zh-CN":"手作概念展示 · 材料包筹备中，暂未开放购买","zh-TW":"手作概念展示 · 材料包籌備中，暫未開放購買","en":"Concept preview · Kit in preparation, not yet for sale","ja":"コンセプト展示・材料キット準備中、販売前","th":"ตัวอย่างแนวคิด · ชุดวัสดุกำลังเตรียม ยังไม่เปิดขาย","ar":"عرض للفكرة · حزمة المواد قيد الإعداد وليست للبيع بعد"},"累 → 休 · 手作体验":{"zh-CN":"累 → 休 · 手作体验","zh-TW":"累 → 休 · 手作體驗","en":"TIRED → REST · HANDCRAFT","ja":"疲れから休息へ・手作り体験","th":"จากเหนื่อยสู่พัก · งานฝีมือ","ar":"من التعب إلى الراحة · تجربة يدوية"},"从一根针开始，<br>重新休息。":{"zh-CN":"从一根针开始，<br>重新休息。","zh-TW":"從一根針開始，<br>重新休息。","en":"One stitch.<br>A little room to rest.","ja":"ひと針から、<br>休息を始める。","th":"เริ่มจากหนึ่งฝีเข็ม<br>กลับมาพักอีกครั้ง","ar":"غرزة واحدة،<br>ومساحة للراحة."},"把注意力，轻轻带回手中的一针一线。":{"zh-CN":"把注意力，轻轻带回手中的一针一线。","zh-TW":"把注意力，輕輕帶回手中的一針一線。","en":"Bring your attention gently to the thread in your hands.","ja":"手元のひと針、一本の糸へ、そっと意識を戻す。","th":"ค่อย ๆ พาความสนใจกลับมาที่เข็มและด้ายในมือ","ar":"أعد انتباهك برفق إلى الخيط والغرز بين يديك."},"休字手作成品：棉麻布、休息表情与字卡":{"zh-CN":"休字手作成品：棉麻布、休息表情与字卡","zh-TW":"休字手作成品：棉麻布、休息表情與字卡","en":"Rest handcraft example with an embroidered face and character card","ja":"綿麻布の休息の表情と文字カードの作品例","th":"ตัวอย่างงานฝีมือพักใจ ผ้าฝ้ายลินิน สีหน้าผ่อนคลาย และการ์ดอักษร","ar":"نموذج يدوي بقماش كتاني ووجه مستريح وبطاقة رمز"},"创始人提供的手作成品示意":{"zh-CN":"创始人提供的手作成品示意","zh-TW":"創始人提供的手作成品示意","en":"Handcraft example shared by the founder","ja":"創始者による作品サンプル","th":"ตัวอย่างชิ้นงานจากผู้ก่อตั้ง","ar":"نموذج عمل يدوي قدّمه المؤسس"},"从感受到回应":{"zh-CN":"从感受到回应","zh-TW":"從感受到回應","en":"From feeling to response","ja":"気持ちから、応えへ","th":"จากความรู้สึกสู่การตอบรับ","ar":"من الشعور إلى الاستجابة"},"累，是此刻。休，是回应。":{"zh-CN":"累，是此刻。休，是回应。","zh-TW":"累，是此刻。休，是回應。","en":"Tired is the feeling. Rest is the response.","ja":"今は疲れている。その応えは、休むこと。","th":"ตอนนี้รู้สึกเหนื่อย การพักคือคำตอบ","ar":"التعب شعور اللحظة، والراحة استجابة له."},"不要求自己立刻改变心情。用“休”的表情和古老字形，把允许暂停的提醒放进生活里。":{"zh-CN":"不要求自己立刻改变心情。用“休”的表情和古老字形，把允许暂停的提醒放进生活里。","zh-TW":"不要求自己立刻改變心情。用“休”的表情和古老字形，把允許暫停的提醒放進生活里。","en":"There is no need to change your feelings immediately. The resting face and ancient character remind you that you may pause.","ja":"すぐに気持ちを変えなくて大丈夫。「休」の表情と古い字形を、立ち止まってもよいという日々の目印に。","th":"ไม่ต้องบังคับให้เปลี่ยนความรู้สึกทันที ใช้สีหน้าพักผ่อนและอักษรโบราณเป็นสิ่งเตือนว่าเราหยุดพักได้","ar":"لا حاجة لتغيير مشاعرك فورًا. دع الوجه المستريح وشكل الرمز القديم يذكّرانك بأن التوقف مسموح."},"示意材料：棉麻布、填充棉、线与薰衣草":{"zh-CN":"示意材料：棉麻布、填充棉、线与薰衣草","zh-TW":"示意材料：棉麻布、填充棉、線與薰衣草","en":"Sample materials: linen, cotton filling, thread and lavender","ja":"材料例：綿麻布、綿、糸、ラベンダー","th":"วัสดุตัวอย่าง ผ้าฝ้ายลินิน ใยฝ้าย ด้าย และลาเวนเดอร์","ar":"مواد نموذجية: قماش كتاني وحشو قطني وخيط وخزامى"},"示意材料 · 棉麻布、填充棉、线与薰衣草":{"zh-CN":"示意材料 · 棉麻布、填充棉、线与薰衣草","zh-TW":"示意材料 · 棉麻布、填充棉、線與薰衣草","en":"Sample materials · Linen, cotton filling, thread and lavender","ja":"材料例・綿麻布、綿、糸、ラベンダー","th":"วัสดุตัวอย่าง · ผ้าฝ้ายลินิน ใยฝ้าย ด้าย และลาเวนเดอร์","ar":"مواد نموذجية · كتان وحشو قطني وخيط وخزامى"},"亲手参与":{"zh-CN":"亲手参与","zh-TW":"親手參與","en":"Made by hand","ja":"自分の手で","th":"ลงมือทำด้วยตัวเอง","ar":"بيديك"},"让一个字，变得可以触摸。":{"zh-CN":"让一个字，变得可以触摸。","zh-TW":"讓一個字，變得可以觸摸。","en":"A symbol you can touch.","ja":"一文字を、手で触れられるものに。","th":"ให้อักษรกลายเป็นสิ่งที่สัมผัสได้","ar":"رمز تستطيع لمسه."},"手作设想是把“休”的表情缝在棉麻布上，配合填充材料制作成小物，再与甲骨文“休”字卡一起留下。关注布料的触感、线条的走向和自己的节奏，不以完成速度或是否漂亮来衡量。":{"zh-CN":"手作设想是把“休”的表情缝在棉麻布上，配合填充材料制作成小物，再与甲骨文“休”字卡一起留下。关注布料的触感、线条的走向和自己的节奏，不以完成速度或是否漂亮来衡量。","zh-TW":"手作設想是把“休”的表情縫在棉麻布上，配合填充材料制作成小物，再與甲骨文“休”字卡一起留下。關注布料的觸感、線條的走向和自己的節奏，不以完成速度或是否漂亮來衡量。","en":"The concept combines a resting face stitched onto linen, a softly filled object and an oracle card for rest. Notice the fabric, thread and your pace, without measuring speed or perfection.","ja":"綿麻布に「休」の表情を縫い、綿を入れた小物にして、甲骨文字のカードと一緒に残す構想です。速さや上手さを測らず、布の感触、糸の流れ、自分のペースを感じてください。","th":"แนวคิดคือปักสีหน้าพักผ่อนบนผ้าฝ้ายลินิน เติมใยให้นุ่ม แล้วเก็บคู่กับการ์ดอักษร「休」 สังเกตสัมผัสผ้า แนวด้าย และจังหวะของตัวเอง โดยไม่วัดกันที่ความเร็วหรือความสวย","ar":"تقوم الفكرة على تطريز وجه مستريح على قماش كتاني وصنع قطعة محشوة ناعمة، مع بطاقة للرمز القديم. لاحظ ملمس القماش ومسار الخيط وإيقاعك، دون الحكم على السرعة أو الجمال."},"图片展示的是创始人提供的概念样品。材料配置与制作说明仍在完善；薰衣草是否使用可按个人喜好选择。":{"zh-CN":"图片展示的是创始人提供的概念样品。材料配置与制作说明仍在完善；薰衣草是否使用可按个人喜好选择。","zh-TW":"圖片展示的是創始人提供的概念樣品。材料配置與制作說明仍在完善；薰衣草是否使用可按個人喜好選擇。","en":"The images show the founder’s concept samples. Kit contents and instructions are still in development; lavender is optional.","ja":"写真は創始者による試作品です。材料と作り方は準備中です。ラベンダーは好みに応じて選べます。","th":"ภาพเป็นตัวอย่างแนวคิดจากผู้ก่อตั้ง รายการวัสดุและวิธีทำยังอยู่ระหว่างพัฒนา จะใช้ลาเวนเดอร์หรือไม่เลือกได้ตามชอบ","ar":"تعرض الصور نماذج أولية من المؤسس. لا تزال المواد والتعليمات قيد التطوير، واستخدام الخزامى اختياري."},"材料包筹备中。价格、供应和发货安排尚未公布，当前仅供了解手作方向，暂未开放购买。":{"zh-CN":"材料包筹备中。价格、供应和发货安排尚未公布，当前仅供了解手作方向，暂未开放购买。","zh-TW":"材料包籌備中。價格、供應和發貨安排尚未公布，當前僅供了解手作方向，暫未開放購買。","en":"The kit is in preparation. Price, availability and delivery are not yet announced. This is a concept preview; purchasing is not available.","ja":"材料キットは準備中です。価格、供給、発送時期は未定です。現在はコンセプト紹介のみで、購入はできません。","th":"ชุดวัสดุกำลังเตรียม ยังไม่ประกาศราคา สต็อก หรือการจัดส่ง หน้านี้แสดงแนวคิดเท่านั้น ยังไม่เปิดซื้อ","ar":"حزمة المواد قيد الإعداد. لم تُعلن الأسعار أو التوفر أو الشحن. الصفحة لعرض الفكرة فقط، والشراء غير متاح بعد."},"回到字的体验":{"zh-CN":"回到字的体验","zh-TW":"回到字的體驗","en":"Return to the symbol experience","ja":"文字の体験に戻る","th":"กลับสู่ประสบการณ์อักษร","ar":"العودة إلى تجربة الرمز"},"你的感受，有一个回应":{"zh-CN":"你的感受，有一个回应","zh-TW":"你的感受，有一個回應","en":"A response to your feeling","ja":"あなたの気持ちに、ひとつの応えを","th":"ความรู้สึกของคุณมีคำตอบรับ","ar":"استجابة لشعورك"},"累了，先允许自己休息。":{"zh-CN":"累了，先允许自己休息。","zh-TW":"累了，先允許自己休息。","en":"Feeling tired? Make room for rest.","ja":"疲れたら、まず休むことを許して。","th":"เหนื่อยแล้ว ให้ตัวเองพักก่อนได้","ar":"حين تتعب، اسمح لنفسك بالراحة."},"累的情绪表情":{"zh-CN":"累的情绪表情","zh-TW":"累的情緒表情","en":"Tired feeling","ja":"疲れた表情","th":"สีหน้าของความเหนื่อย","ar":"وجه يعبّر عن التعب"},"此刻的你":{"zh-CN":"此刻的你","zh-TW":"此刻的你","en":"Your feeling","ja":"今のあなた","th":"คุณในตอนนี้","ar":"شعورك الآن"},"累":{"zh-CN":"累","zh-TW":"累","en":"Tired","ja":"疲れ","th":"เหนื่อย","ar":"متعب"},"休的回应表情，一个人安静地躺着休息":{"zh-CN":"休的回应表情，一个人安静地躺着休息","zh-TW":"休的回應表情，一個人安靜地躺著休息","en":"Rest response: a person lying peacefully","ja":"静かに横になって休む人の表情","th":"คำตอบรับแห่งการพัก คนที่นอนพักอย่างสงบ","ar":"استجابة الراحة: شخص يستلقي بهدوء"},"给你的回应":{"zh-CN":"给你的回应","zh-TW":"給你的回應","en":"Your response","ja":"あなたへの応え","th":"คำตอบรับถึงคุณ","ar":"الاستجابة لك"},"休":{"zh-CN":"休","zh-TW":"休","en":"Rest","ja":"休息","th":"พัก","ar":"راحة"},"不必马上振作，也不必急着向前。<br>先给自己一个可以停靠的片刻。":{"zh-CN":"不必马上振作，也不必急着向前。<br>先给自己一个可以停靠的片刻。","zh-TW":"不必馬上振作，也不必急著向前。<br>先給自己一個可以停靠的片刻。","en":"You do not have to rally or hurry ahead.<br>Give yourself a moment to be supported.","ja":"すぐに元気にならなくても、先を急がなくても大丈夫。<br>まず、安心して身を預けるひとときを。","th":"ไม่ต้องรีบเข้มแข็งหรือรีบก้าวต่อ<br>ให้ตัวเองมีที่พักสักครู่ก่อน","ar":"لا يلزم أن تستعيد نشاطك فورًا أو تسرع إلى الأمام.<br>امنح نفسك لحظة تستند فيها إلى ما يدعمك."},"从一个小练习开始":{"zh-CN":"从一个小练习开始","zh-TW":"從一個小練習開始","en":"Begin with a small practice","ja":"小さな練習から","th":"เริ่มจากการฝึกเล็ก ๆ","ar":"ابدأ بتمرين صغير"},"这十秒，先不做什么。":{"zh-CN":"这十秒，先不做什么。","zh-TW":"這十秒，先不做什么。","en":"For ten seconds, simply rest.","ja":"この十秒は、何もしなくていい。","th":"สิบวินาทีนี้ ไม่ต้องทำอะไรก่อน","ar":"لعشر ثوانٍ، استرح فحسب."},"靠在椅背上，自然呼吸。<br>感受身体被支撑，按舒服的节奏来。":{"zh-CN":"靠在椅背上，自然呼吸。<br>感受身体被支撑，按舒服的节奏来。","zh-TW":"靠在椅背上，自然呼吸。<br>感受身體被支撐，按舒服的節奏來。","en":"Lean against your chair and breathe naturally.<br>Notice its support, at a comfortable pace.","ja":"椅子の背にもたれ、自然に呼吸を。<br>支えられる体を感じ、心地よいペースで。","th":"เอนพิงพนักเก้าอี้ หายใจตามธรรมชาติ<br>รับรู้ว่าร่างกายมีที่รองรับ ตามจังหวะที่สบาย","ar":"اتكئ على ظهر الكرسي وتنفس بصورة طبيعية.<br>لاحظ ما يسند جسدك وبالإيقاع المريح لك."},"给此刻，留一句话":{"zh-CN":"给此刻，留一句话","zh-TW":"給此刻，留一句話","en":"A note to this moment","ja":"今の自分に、ひと言を","th":"ฝากข้อความถึงช่วงเวลานี้","ar":"كلمة لهذه اللحظة"},"保存，留下这个字":{"zh-CN":"保存，留下这个字","zh-TW":"保存，留下這個字","en":"Save this moment","ja":"保存して、この一文字を残す","th":"บันทึกอักษรของช่วงเวลานี้","ar":"احفظ هذه اللحظة"},"A MOMENT TO KEEP":{"zh-CN":"A MOMENT TO KEEP","zh-TW":"A MOMENT TO KEEP","en":"A MOMENT TO KEEP","ja":"残しておきたいひととき","th":"ช่วงเวลาที่อยากเก็บไว้","ar":"لحظة تستحق الاحتفاظ"},"这一刻，值得留下。":{"zh-CN":"这一刻，值得留下。","zh-TW":"這一刻，值得留下。","en":"A moment worth keeping.","ja":"このひとときを、残しておこう。","th":"ช่วงเวลานี้มีค่าพอที่จะเก็บไว้","ar":"هذه اللحظة تستحق أن تبقى."},"我的今日开运字符":{"zh-CN":"我的今日开运字符","zh-TW":"我的今日開運字符","en":"My symbol today","ja":"今日の私の一文字","th":"อักษรของฉันวันนี้","ar":"رمزي لهذا اليوم"},"今日相遇":{"zh-CN":"今日相遇","zh-TW":"今日相遇","en":"Today’s encounter","ja":"今日の出会い","th":"การพบกันวันนี้","ar":"لقاء اليوم"},"一个字，回应你的此刻。":{"zh-CN":"一个字，回应你的此刻。","zh-TW":"一個字，回應你的此刻。","en":"One symbol. For this moment.","ja":"一文字が、今のあなたに応える。","th":"หนึ่งอักษร ตอบรับความรู้สึกตอนนี้","ar":"رمز واحد يستجيب للحظتك."},"生成纪念字卡":{"zh-CN":"生成纪念字卡","zh-TW":"生成紀念字卡","en":"Create a keepsake card","ja":"記念カードを作る","th":"สร้างการ์ดเก็บความทรงจำ","ar":"أنشئ بطاقة تذكارية"},"把体验传递给朋友":{"zh-CN":"把体验传递给朋友","zh-TW":"把體驗傳遞給朋友","en":"Pass this experience on","ja":"友だちに体験を届ける","th":"ส่งต่อประสบการณ์ให้เพื่อน","ar":"شارك التجربة مع صديق"},"建立字册，收藏自己的片刻":{"zh-CN":"建立字册，收藏自己的片刻","zh-TW":"建立字冊，收藏自己的片刻","en":"Create a journal for your moments","ja":"自分のひとときを集める手帳を","th":"สร้างสมุดเก็บช่วงเวลาของตัวเอง","ar":"أنشئ دفترًا للحظاتك"},"愿意时，再回来看看自己走过的路。":{"zh-CN":"愿意时，再回来看看自己走过的路。","zh-TW":"愿意時，再回來看看自己走過的路。","en":"Return whenever you wish.","ja":"また見たいときに、自分の歩みを振り返って。","th":"กลับมามองเส้นทางที่ผ่านได้เมื่อคุณพร้อม","ar":"عد متى شئت لتتأمل طريقك."},"PASS ON A LITTLE CALM":{"zh-CN":"PASS ON A LITTLE CALM","zh-TW":"PASS ON A LITTLE CALM","en":"PASS ON A LITTLE CALM","ja":"小さな安らぎを届ける","th":"ส่งต่อความสงบเล็ก ๆ","ar":"شارك قليلًا من الهدوء"},"把字的体验，\n传递给需要它的人。":{"zh-CN":"把字的体验，\n传递给需要它的人。","zh-TW":"把字的體驗，\n傳遞給需要它的人。","en":"Pass a moment of calm\nto someone who needs it.","ja":"この文字の体験を、\n必要としている人へ。","th":"ส่งต่อประสบการณ์อักษร\nให้คนที่ต้องการมัน","ar":"شارك تجربة الرمز\nمع من يحتاج إليها."},"不必替对方找到答案。\n留一个入口，就很好。":{"zh-CN":"不必替对方找到答案。\n留一个入口，就很好。","zh-TW":"不必替對方找到答案。\n留一個入口，就很好。","en":"You do not need to find their answer.\nAn open door is enough.","ja":"相手の答えを見つけなくても大丈夫。\n入口をひとつ届けるだけで。","th":"ไม่ต้องหาคำตอบแทนเขา\nเพียงเปิดประตูไว้ก็พอ","ar":"لست مضطرًا لإيجاد إجابته.\nيكفي أن تفتح له بابًا."},"分享给朋友":{"zh-CN":"分享给朋友","zh-TW":"分享給朋友","en":"Share with a friend","ja":"友だちに共有","th":"แชร์ให้เพื่อน","ar":"شارك مع صديق"},"复制体验链接":{"zh-CN":"复制体验链接","zh-TW":"復制體驗鏈接","en":"Copy experience link","ja":"体験リンクをコピー","th":"คัดลอกลิงก์ประสบการณ์","ar":"انسخ رابط التجربة"},"体验链接":{"zh-CN":"体验链接","zh-TW":"體驗鏈接","en":"Experience link","ja":"体験リンク","th":"ลิงก์ประสบการณ์","ar":"رابط التجربة"},"朋友打开即到欢迎页。分享不包含你的情绪或留言。":{"zh-CN":"朋友打开即到欢迎页。分享不包含你的情绪或留言。","zh-TW":"朋友打開即到歡迎頁。分享不包含你的情緒或留言。","en":"The link opens the welcome page. Your feelings and notes stay private.","ja":"リンクはようこそページを開きます。気持ちやメモは共有されません。","th":"ลิงก์จะเปิดหน้าต้อนรับ ไม่แชร์อารมณ์หรือข้อความของคุณ","ar":"يفتح الرابط صفحة الترحيب. لا تُشارك مشاعرك أو ملاحظاتك."},"LET THE MOMENTS CONTINUE":{"zh-CN":"LET THE MOMENTS CONTINUE","zh-TW":"LET THE MOMENTS CONTINUE","en":"LET THE MOMENTS CONTINUE","ja":"これからも、ひとときを","th":"ให้ช่วงเวลาดี ๆ ดำเนินต่อ","ar":"لتستمر هذه اللحظات"},"七次相遇，\n谢谢你愿意停留。":{"zh-CN":"七次相遇，\n谢谢你愿意停留。","zh-TW":"七次相遇，\n謝謝你愿意停留。","en":"Seven moments.\nThank you for being here.","ja":"七つの出会い。\nここで過ごしてくれて、ありがとう。","th":"การพบกันเจ็ดครั้ง\nขอบคุณที่ให้เวลาที่นี่","ar":"سبع لحظات،\nشكرًا لبقائك معنا."},"前 7 次一个字体验为公益体验。\n从第 8 次起，我们希望以一份小小的支持，\n让这份陪伴继续。":{"zh-CN":"前 7 次一个字体验为公益体验。\n从第 8 次起，我们希望以一份小小的支持，\n让这份陪伴继续。","zh-TW":"前 7 次一個字體驗為公益體驗。\n從第 8 次起，我們希望以一份小小的支持，\n讓這份陪伴繼續。","en":"The first seven experiences are free.\nFrom the eighth, a small contribution\nwill help this space continue.","ja":"最初の7回は無料体験です。\n8回目からは、小さな応援で\nこの寄り添いを続けていきたいと考えています。","th":"เจ็ดครั้งแรกเป็นประสบการณ์ฟรี\nตั้งแต่ครั้งที่แปด เราหวังให้การสนับสนุนเล็ก ๆ\nช่วยให้พื้นที่นี้ดำเนินต่อไป","ar":"التجارب السبع الأولى مجانية.\nابتداءً من الثامنة، نأمل أن يساعد دعم بسيط\nعلى استمرار هذه المساحة."},"单次体验支持":{"zh-CN":"单次体验支持","zh-TW":"單次體驗支持","en":"Support an experience","ja":"一回の体験を応援","th":"สนับสนุนประสบการณ์หนึ่งครั้ง","ar":"ادعم تجربة واحدة"},"金额待公布":{"zh-CN":"金额待公布","zh-TW":"金額待公布","en":"Price to be announced","ja":"金額は後日ご案内","th":"จะประกาศราคาในภายหลัง","ar":"سيُعلن المبلغ لاحقًا"},"当前为样品演示，不会扣款。":{"zh-CN":"当前为样品演示，不会扣款。","zh-TW":"當前為樣品演示，不會扣款。","en":"Prototype only. No charge will be made.","ja":"試作のデモです。課金はありません。","th":"เป็นตัวอย่างสาธิต ไม่มีการเรียกเก็บเงินจริง","ar":"عرض تجريبي فقط. لن يُخصم أي مبلغ."},"模拟支持，继续体验":{"zh-CN":"模拟支持，继续体验","zh-TW":"模擬支持，繼續體驗","en":"Try the support flow","ja":"応援の流れを試して続ける","th":"จำลองการสนับสนุนแล้วไปต่อ","ar":"جرّب الدعم وتابع التجربة"},"了解线上体验课":{"zh-CN":"了解线上体验课","zh-TW":"了解線上體驗課","en":"Explore online courses","ja":"オンライン講座を見る","th":"ดูคอร์สออนไลน์","ar":"تعرّف على الدورات عبر الإنترنت"},"回看已经留下的字":{"zh-CN":"回看已经留下的字","zh-TW":"回看已經留下的字","en":"Revisit your saved moments","ja":"保存した文字を振り返る","th":"ย้อนดูอักษรที่บันทึกไว้","ar":"راجع رموزك المحفوظة"},"认识线上课":{"zh-CN":"认识线上课","zh-TW":"認識線上課","en":"Explore courses","ja":"オンライン講座を知る","th":"ทำความรู้จักคอร์สออนไลน์","ar":"تعرّف على الدورات"},"邀请朋友体验":{"zh-CN":"邀请朋友体验","zh-TW":"邀請朋友體驗","en":"Invite a friend","ja":"友だちを招待","th":"ชวนเพื่อนมาลอง","ar":"ادعُ صديقًا للتجربة"},"我的线上课":{"zh-CN":"我的线上课","zh-TW":"我的線上課","en":"Online courses","ja":"私のオンライン講座","th":"คอร์สออนไลน์ของฉัน","ar":"دوراتي عبر الإنترنت"},"继续向内":{"zh-CN":"继续向内","zh-TW":"繼續向內","en":"Continue inward","ja":"心の内へ、もう一歩","th":"เดินทางเข้าสู่ใจต่อ","ar":"واصل إلى الداخل"},"我的报名意向草稿":{"zh-CN":"我的报名意向草稿","zh-TW":"我的報名意向草稿","en":"My course enquiry draft","ja":"受講相談の下書き","th":"ร่างแสดงความสนใจของฉัน","ar":"مسودة اهتمامي بالدورة"},"请使用下方复制链接分享。":{"zh-CN":"请使用下方复制链接分享。","zh-TW":"請使用下方復制鏈接分享。","en":"Use Copy link below.","ja":"下のリンクをコピーして共有してください。","th":"ใช้ปุ่มคัดลอกลิงก์ด้านล่างเพื่อแชร์","ar":"استخدم زر نسخ الرابط أدناه."},"体验链接已复制":{"zh-CN":"体验链接已复制","zh-TW":"體驗鏈接已復制","en":"Experience link copied","ja":"体験リンクをコピーしました","th":"คัดลอกลิงก์แล้ว","ar":"نُسخ رابط التجربة"},"请长按或手动复制下方链接":{"zh-CN":"请长按或手动复制下方链接","zh-TW":"請長按或手動復制下方鏈接","en":"Please copy the selected link","ja":"下のリンクを長押しするか、手動でコピーしてください","th":"กดค้างหรือคัดลอกลิงก์ด้านล่างด้วยตัวเอง","ar":"اضغط مطولًا أو انسخ الرابط أدناه يدويًا"},"碳基 / 硅基 · 一场关于感受的小探索":{"zh-CN":"碳基 / 硅基 · 一场关于感受的小探索","zh-TW":"碳基 / 硅基 · 一場關于感受的小探索","en":"Carbon / silicon · A playful exploration","ja":"炭素系・シリコン系・気持ちを探る小さな遊び","th":"คาร์บอน / ซิลิคอน · สำรวจความรู้สึกแบบสนุก ๆ","ar":"كربون / سيليكون · استكشاف مرح للمشاعر"},"没有对错，选最接近此刻的那一个。":{"zh-CN":"没有对错，选最接近此刻的那一个。","zh-TW":"沒有對錯，選最接近此刻的那一個。","en":"No right answer. Choose what feels closest.","ja":"正解はありません。今の自分に一番近いものを。","th":"ไม่มีถูกผิด เลือกสิ่งที่ใกล้ความรู้สึกตอนนี้ที่สุด","ar":"لا صواب ولا خطأ. اختر الأقرب إلى شعورك الآن."},"用身体，保存这个字":{"zh-CN":"用身体，保存这个字","zh-TW":"用身體，保存這個字","en":"Let your body keep this symbol","ja":"体で、この一文字を感じる","th":"เก็บอักษรนี้ไว้ผ่านร่างกาย","ar":"دع جسدك يحتفظ بهذا الرمز"},"03 · 体验":{"zh-CN":"03 · 体验","zh-TW":"03 · 體驗","en":"03 · PRACTICE","ja":"03・体験","th":"03 · ฝึกสัมผัส","ar":"03 · الممارسة"},"如何证明，\n你是人类？":{"zh-CN":"如何证明，\n你是人类？","zh-TW":"如何證明，\n你是人類？","en":"What makes you\nhuman?","ja":"あなたの人間らしさは、\nどこにある？","th":"อะไรบอกว่า\nคุณเป็นมนุษย์","ar":"ما الذي يجعلك\nإنسانًا؟"},"三道小题，看看此刻的你。":{"zh-CN":"三道小题，看看此刻的你。","zh-TW":"三道小題，看看此刻的你。","en":"Three small questions about this moment.","ja":"三つの小さな質問で、今の自分を。","th":"คำถามเล็ก ๆ สามข้อเพื่อมองตัวเองตอนนี้","ar":"ثلاثة أسئلة صغيرة عن لحظتك الحالية."},"没有标准答案。\n直觉的回应，就很好。":{"zh-CN":"没有标准答案。\n直觉的回应，就很好。","zh-TW":"沒有標準答案。\n直覺的回應，就很好。","en":"There is no right answer.\nTrust your first response.","ja":"決まった正解はありません。\n直感のままに答えてください。","th":"ไม่มีคำตอบมาตรฐาน\nตอบตามความรู้สึกแรกได้เลย","ar":"لا توجد إجابة نموذجية.\nثق باستجابتك الأولى."},"趣味体验，不作真实身份或心理判断。":{"zh-CN":"趣味体验，不作真实身份或心理判断。","zh-TW":"趣味體驗，不作真實身份或心理判斷。","en":"A playful experience, not an identity or psychological assessment.","ja":"遊びとしての体験です。実際の本人確認や心理判定ではありません。","th":"เป็นประสบการณ์เพื่อความสนุก ไม่ใช่การตรวจตัวตนหรือประเมินจิตใจ","ar":"تجربة مرحة، وليست تحققًا من الهوية أو تقييمًا نفسيًا."},"字有答案，是一个可以随身携带的指尖绿洲。\n\n我们借古文字的形与意，邀请你停一停，看见情绪、感受身体，也发现自己内在的资源。\n\n一个字，一次小小的体验。在需要被支持的时刻，给自己一个温柔的入口。":{"zh-CN":"字有答案，是一个可以随身携带的指尖绿洲。\n\n我们借古文字的形与意，邀请你停一停，看见情绪、感受身体，也发现自己内在的资源。\n\n一个字，一次小小的体验。在需要被支持的时刻，给自己一个温柔的入口。","zh-TW":"字有答案，是一個可以隨身攜帶的指尖綠洲。\n\n我們借古文字的形與意，邀請你停一停，看見情緒、感受身體，也發現自己內在的資源。\n\n一個字，一次小小的體驗。在需要被支持的時刻，給自己一個溫柔的入口。","en":"Daily Symbol is a small space of calm you can carry with you.\n\nThrough ancient character forms and meanings, pause, notice emotions, feel your body and rediscover your own resources.\n\nOne symbol, one small experience: a gentle doorway whenever you need support.","ja":"字有答案は、指先に持ち歩ける小さな安らぎの場所です。\n\n古文字の形と意味を通して、立ち止まり、感情に気づき、体を感じ、自分の中にある力を見つけます。\n\n一文字、一つの小さな体験。支えがほしいとき、自分に優しい入口を。","th":"Daily Symbol คือมุมสงบเล็ก ๆ ที่พกติดตัวได้\n\nผ่านรูปทรงและความหมายของอักษรโบราณ เราชวนคุณหยุด รับรู้อารมณ์ สัมผัสร่างกาย และค้นพบทรัพยากรในตัวเอง\n\nหนึ่งอักษร หนึ่งประสบการณ์เล็ก ๆ เป็นประตูอ่อนโยนในวันที่ต้องการการรองรับ","ar":"جواب في حرف مساحة هادئة صغيرة ترافقك.\n\nعبر أشكال الحروف القديمة ومعانيها، ندعوك إلى التوقف وملاحظة مشاعرك والإحساس بجسدك واكتشاف مواردك الداخلية.\n\nرمز واحد وتجربة صغيرة؛ مدخل لطيف كلما احتجت إلى الدعم."},"线上课":{"zh-CN":"线上课","zh-TW":"線上課","en":"Courses","ja":"オンライン講座","th":"คอร์สออนไลน์","ar":"الدورات"},"安己书":{"zh-CN":"安己书","zh-TW":"安己書","en":"Book of Inner Ease","ja":"自分を安らげる書","th":"หนังสือแห่งการดูแลใจ","ar":"كتاب السكينة الذاتية"},"见人书":{"zh-CN":"见人书","zh-TW":"見人書","en":"Book of Relationships","ja":"人と出会う書","th":"หนังสือแห่งความสัมพันธ์","ar":"كتاب العلاقات"},"名字书":{"zh-CN":"名字书","zh-TW":"名字書","en":"Book of Your Name","ja":"名前の書","th":"หนังสือแห่งชื่อของคุณ","ar":"كتاب اسمك"},"向内 · 安住自己":{"zh-CN":"向内 · 安住自己","zh-TW":"向內 · 安住自己","en":"Inward · Feel at home in yourself","ja":"内へ・自分の中に安らぐ","th":"มองเข้าใน · วางใจในตัวเอง","ar":"إلى الداخل · استقر في ذاتك"},"向外 · 看见关系":{"zh-CN":"向外 · 看见关系","zh-TW":"向外 · 看見關系","en":"Outward · Understand relationships","ja":"外へ・関係を見つめる","th":"มองออกไป · เข้าใจความสัมพันธ์","ar":"إلى الخارج · افهم العلاقات"},"回归 · 认领自己":{"zh-CN":"回归 · 认领自己","zh-TW":"回歸 · 認領自己","en":"Return · Reclaim yourself","ja":"戻る・自分を受けとめる","th":"กลับคืน · ยอมรับตัวตน","ar":"العودة · تقبّل ذاتك"},"7 课 · 共 14 小时":{"zh-CN":"7 课 · 共 14 小时","zh-TW":"7 課 · 共 14 小時","en":"7 classes · 14 hours total","ja":"全7回・合計14時間","th":"7 บทเรียน · รวม 14 ชั่วโมง","ar":"7 دروس · 14 ساعة إجمالًا"},"线上小班 · 每班 20 人":{"zh-CN":"线上小班 · 每班 20 人","zh-TW":"線上小班 · 每班 20 人","en":"Small online group · 20 per class","ja":"オンライン少人数講座・各クラス20名","th":"กลุ่มออนไลน์ขนาดเล็ก · กลุ่มละ 20 คน","ar":"مجموعة صغيرة عبر الإنترنت · 20 مشاركًا"},"7 次一对一 · 每次 75 分钟":{"zh-CN":"7 次一对一 · 每次 75 分钟","zh-TW":"7 次一對一 · 每次 75 分鐘","en":"7 individual sessions · 75 minutes each","ja":"個人セッション全7回・各75分","th":"ตัวต่อตัว 7 ครั้ง · ครั้งละ 75 นาที","ar":"7 جلسات فردية · 75 دقيقة لكل جلسة"},"定制陪伴 · 每期规划 8 席":{"zh-CN":"定制陪伴 · 每期规划 8 席","zh-TW":"定制陪伴 · 每期規劃 8 席","en":"Personal guidance · 8 places planned per cohort","ja":"個別の伴走・各期8名を予定","th":"ดูแลเฉพาะบุคคล · วางแผนรุ่นละ 8 ที่","ar":"مرافقة شخصية · 8 أماكن مخطط لها في كل دفعة"},"先不急着处理关系。用七个字，慢慢找回照顾自己的能力。":{"zh-CN":"先不急着处理关系。用七个字，慢慢找回照顾自己的能力。","zh-TW":"先不急著處理關系。用七個字，慢慢找回照顧自己的能力。","en":"Before rushing to resolve relationships, use seven symbols to rediscover how to care for yourself.","ja":"関係を整えようと急ぐ前に。七つの文字を通して、自分をいたわる力を少しずつ取り戻します。","th":"ก่อนรีบแก้ความสัมพันธ์ ใช้อักษรเจ็ดตัวค่อย ๆ ค้นพบความสามารถในการดูแลตัวเองอีกครั้ง","ar":"قبل الإسراع لحل العلاقات، استعد عبر سبعة رموز قدرتك على الاعتناء بنفسك."},"把注意力带回身体，找到可随时回来的安心之处。":{"zh-CN":"把注意力带回身体，找到可随时回来的安心之处。","zh-TW":"把注意力帶回身體，找到可隨時回來的安心之處。","en":"Return attention to your body and find a place of ease you can revisit.","ja":"体に意識を戻し、いつでも帰れる安らぎを見つけます。","th":"พาความสนใจกลับมาที่ร่างกาย หาที่สงบซึ่งกลับมาได้เสมอ","ar":"أعد انتباهك إلى جسدك واعثر على مساحة أمان تعود إليها."},"练习温柔而坚定的边界，允许自己的感受存在。":{"zh-CN":"练习温柔而坚定的边界，允许自己的感受存在。","zh-TW":"練習溫柔而堅定的邊界，允許自己的感受存在。","en":"Practise gentle, firm boundaries and make room for your feelings.","ja":"優しく確かな境界線を練習し、自分の気持ちがあることを認めます。","th":"ฝึกขอบเขตที่อ่อนโยนแต่มั่นคง และยอมให้ความรู้สึกของตัวเองมีพื้นที่","ar":"تدرّب على حدود لطيفة وواضحة وافسح المجال لمشاعرك."},"带走日常可用的自我关照练习。":{"zh-CN":"带走日常可用的自我关照练习。","zh-TW":"帶走日常可用的自我關照練習。","en":"Take self-care practices into everyday life.","ja":"日常に持ち帰れるセルフケアの練習を。","th":"นำแบบฝึกดูแลใจไปใช้ในชีวิตประจำวัน","ar":"خذ معك تمارين للعناية بالنفس في حياتك اليومية."},"心慌的时候，有一个可以回去的地方":{"zh-CN":"心慌的时候，有一个可以回去的地方","zh-TW":"心慌的時候，有一個可以回去的地方","en":"A place to return to when you feel unsettled","ja":"心がざわつくとき、帰れる場所を","th":"เมื่อใจสั่นไหว มีที่ให้กลับไป","ar":"مكان تعود إليه حين يقلق قلبك"},"自我关怀 · 从摇摆，到落定":{"zh-CN":"自我关怀 · 从摇摆，到落定","zh-TW":"自我關懷 · 從搖擺，到落定","en":"Self-care · From uncertainty to grounding","ja":"セルフケア・揺れから落ち着きへ","th":"ดูแลตัวเอง · จากไหวหวั่นสู่มั่นคง","ar":"رعاية الذات · من التردد إلى الثبات"},"身体扫描、呼吸锚点、制作「我的安心按钮」。":{"zh-CN":"身体扫描、呼吸锚点、制作「我的安心按钮」。","zh-TW":"身體掃描、呼吸錨點、制作「我的安心按鈕」。","en":"Body scan, breath anchoring and creating your own calming cue.","ja":"ボディスキャン、呼吸のよりどころ、自分の「安心ボタン」作り。","th":"สำรวจร่างกาย ใช้ลมหายใจเป็นจุดยึด และสร้างสัญญาณสงบใจของตัวเอง","ar":"مسح الجسد، واتخاذ التنفس مرساة، وصنع إشارة شخصية للطمأنينة."},"别人的一句话，不再决定你的一整天":{"zh-CN":"别人的一句话，不再决定你的一整天","zh-TW":"別人的一句話，不再決定你的一整天","en":"One remark need not decide your whole day","ja":"誰かのひと言に、一日を委ねない","th":"คำพูดหนึ่งคำของคนอื่นไม่ต้องกำหนดทั้งวันของคุณ","ar":"كلمة من شخص آخر لا تحدّد يومك كله"},"安住当下 · 从黏着，到如实":{"zh-CN":"安住当下 · 从黏着，到如实","zh-TW":"安住當下 · 從黏著，到如實","en":"Being present · From clinging to seeing clearly","ja":"今にとどまる・執着からありのままへ","th":"อยู่กับปัจจุบัน · จากยึดติดสู่เห็นตามจริง","ar":"الحضور · من التعلّق إلى رؤية الواقع"},"STOP 练习、觉察顺应反射、三分钟呼吸空间。":{"zh-CN":"STOP 练习、觉察顺应反射、三分钟呼吸空间。","zh-TW":"STOP 練習、覺察順應反射、三分鐘呼吸空間。","en":"STOP practice, noticing automatic accommodation, and a three-minute breathing space.","ja":"STOPの練習、反射的に合わせる癖への気づき、3分間の呼吸空間。","th":"ฝึก STOP สังเกตการยอมตามโดยอัตโนมัติ และพื้นที่หายใจสามนาที","ar":"تمرين STOP، وملاحظة الاستجابة التلقائية بالموافقة، وثلاث دقائق للتنفس."},"把那个被丢在半路上的小女孩，接回来":{"zh-CN":"把那个被丢在半路上的小女孩，接回来","zh-TW":"把那個被丟在半路上的小女孩，接回來","en":"Welcome back the younger girl you left behind","ja":"置き去りにした小さな自分を迎える","th":"ต้อนรับเด็กหญิงในใจที่เคยถูกทิ้งไว้กลางทาง","ar":"استقبلي الطفلة التي تركتِها خلفك"},"找回生命力 · 从懂事，到鲜活":{"zh-CN":"找回生命力 · 从懂事，到鲜活","zh-TW":"找回生命力 · 從懂事，到鮮活","en":"Recover vitality · From pleasing to living fully","ja":"生命力を取り戻す・いい子から生き生きと","th":"คืนพลังชีวิต · จากการเป็นเด็กดีสู่ความสดใส","ar":"استعادة الحيوية · من إرضاء الآخرين إلى الحياة"},"内在小孩对话、正念行走、写下十件只为好玩的事。":{"zh-CN":"内在小孩对话、正念行走、写下十件只为好玩的事。","zh-TW":"內在小孩對話、正念行走、寫下十件只為好玩的事。","en":"Inner-child dialogue, mindful walking and ten things to do just for fun.","ja":"内なる子どもとの対話、歩く瞑想、楽しむためだけのことを10個書く。","th":"สนทนากับเด็กในใจ เดินอย่างมีสติ และเขียนสิบสิ่งที่ทำเพียงเพื่อความสนุก","ar":"حوار مع الطفل الداخلي، ومشي واعٍ، وكتابة عشرة أشياء للمتعة وحدها."},"找回你说「我来」时的那股力量":{"zh-CN":"找回你说「我来」时的那股力量","zh-TW":"找回你說「我來」時的那股力量","en":"Rediscover the strength to say “I will”","ja":"「私がやる」と言える力を取り戻す","th":"ค้นคืนพลังเวลาพูดว่า “ฉันทำเอง”","ar":"استعد قوتك حين تقول «سأتولى الأمر»"},"女性的力量 · 从退让，到站定":{"zh-CN":"女性的力量 · 从退让，到站定","zh-TW":"女性的力量 · 從退讓，到站定","en":"Women’s strength · From retreating to standing firm","ja":"女性の力・譲り続けることから立つことへ","th":"พลังของผู้หญิง · จากถอยให้สู่ยืนมั่น","ar":"قوة المرأة · من التراجع إلى الثبات"},"山式站姿、声音与气场练习、绘制力量图谱。":{"zh-CN":"山式站姿、声音与气场练习、绘制力量图谱。","zh-TW":"山式站姿、聲音與氣場練習、繪制力量圖譜。","en":"Mountain posture, voice and presence practice, and mapping your strengths.","ja":"山のポーズ、声と存在感の練習、力の地図作り。","th":"ท่ายืนภูเขา ฝึกเสียงและการปรากฏตัว และวาดแผนที่จุดแข็ง","ar":"وقفة الجبل، وتمارين الصوت والحضور، ورسم خريطة القوة."},"把「不」字，温柔而坚定地说出口":{"zh-CN":"把「不」字，温柔而坚定地说出口","zh-TW":"把「不」字，溫柔而堅定地說出口","en":"Say “no” with kindness and firmness","ja":"優しく、確かに「いいえ」を伝える","th":"พูด “ไม่” อย่างอ่อนโยนและมั่นคง","ar":"قل «لا» بلطف وثبات"},"边界与表达 · 从隐忍，到清晰":{"zh-CN":"边界与表达 · 从隐忍，到清晰","zh-TW":"邊界與表達 · 從隱忍，到清晰","en":"Boundaries and expression · From silence to clarity","ja":"境界線と表現・我慢から明確さへ","th":"ขอบเขตและการสื่อสาร · จากอดกลั้นสู่ชัดเจน","ar":"الحدود والتعبير · من الكتمان إلى الوضوح"},"拒绝脚本演练、愤怒的正念容纳、关系边界地图。":{"zh-CN":"拒绝脚本演练、愤怒的正念容纳、关系边界地图。","zh-TW":"拒絕腳本演練、憤怒的正念容納、關系邊界地圖。","en":"Rehearse refusals, make mindful room for anger, and map relationship boundaries.","ja":"断り方の練習、怒りをマインドフルに受けとめること、関係の境界線マップ。","th":"ซ้อมการปฏิเสธ เปิดพื้นที่ให้ความโกรธอย่างมีสติ และทำแผนที่ขอบเขตความสัมพันธ์","ar":"تدريب على الرفض، واحتواء الغضب بوعي، ورسم حدود العلاقات."},"让经历，慢慢长成你的骨头":{"zh-CN":"让经历，慢慢长成你的骨头","zh-TW":"讓經歷，慢慢長成你的骨頭","en":"Let experience become your inner strength","ja":"経験を、ゆっくり自分の芯にする","th":"ให้ประสบการณ์ค่อย ๆ กลายเป็นแกนที่มั่นคง","ar":"دع الخبرات تصبح سندك الداخلي"},"心理韧性 · 从对抗，到承接":{"zh-CN":"心理韧性 · 从对抗，到承接","zh-TW":"心理韌性 · 從對抗，到承接","en":"Resilience · From resisting to holding experience","ja":"心のしなやかさ・対抗から受けとめへ","th":"ความยืดหยุ่นทางใจ · จากต่อต้านสู่รองรับ","ar":"المرونة النفسية · من المقاومة إلى الاحتواء"},"RAIN 练习、生命事件盘点、重新书写自己的经历。":{"zh-CN":"RAIN 练习、生命事件盘点、重新书写自己的经历。","zh-TW":"RAIN 練習、生命事件盤點、重新書寫自己的經歷。","en":"RAIN practice, reviewing life events and rewriting your experience.","ja":"RAINの練習、人生の出来事の振り返り、自分の経験を書き直す。","th":"ฝึก RAIN ทบทวนเหตุการณ์ชีวิต และเขียนประสบการณ์ของตัวเองใหม่","ar":"تمرين RAIN، ومراجعة أحداث الحياة، وإعادة كتابة تجربتك."},"为自己留一门手艺，把称赞还给自己":{"zh-CN":"为自己留一门手艺，把称赞还给自己","zh-TW":"為自己留一門手藝，把稱贊還給自己","en":"Keep a craft for yourself and offer yourself appreciation","ja":"自分のための手仕事と、自分への称賛を","th":"มีงานฝีมือเพื่อตัวเอง และคืนคำชมให้ตัวเอง","ar":"احتفظ بحرفة لنفسك وامنحها التقدير"},"自我欣赏 · 从评判，到欣赏":{"zh-CN":"自我欣赏 · 从评判，到欣赏","zh-TW":"自我欣賞 · 從評判，到欣賞","en":"Self-appreciation · From judgment to recognition","ja":"自分を認める・評価から感謝へ","th":"ชื่นชมตัวเอง · จากตัดสินสู่เห็นคุณค่า","ar":"تقدير الذات · من الحكم إلى الامتنان"},"滋养清单、成就存款练习、对自己说一句真心的好话。":{"zh-CN":"滋养清单、成就存款练习、对自己说一句真心的好话。","zh-TW":"滋養清單、成就存款練習、對自己說一句真心的好話。","en":"Make a nourishment list, collect achievements and offer yourself sincere kind words.","ja":"自分を満たすリスト、できたことの貯金、自分への心からの優しい言葉。","th":"ทำรายการสิ่งหล่อเลี้ยงใจ สะสมความสำเร็จ และพูดสิ่งดี ๆ กับตัวเองอย่างจริงใจ","ar":"قائمة بما يغذّيك، وجمع الإنجازات، وكلمة طيبة صادقة لنفسك."},"当自己逐渐安定，再看见关系里反复出现的模式。理解他人，也认出自己。":{"zh-CN":"当自己逐渐安定，再看见关系里反复出现的模式。理解他人，也认出自己。","zh-TW":"當自己逐漸安定，再看見關系里反復出現的模式。理解他人，也認出自己。","en":"As you settle within, notice recurring patterns in relationships. Understand others while recognising yourself.","ja":"自分が落ち着いたら、関係の中で繰り返すパターンへ。他者を理解し、自分にも気づきます。","th":"เมื่อใจเริ่มมั่นคง ค่อยสังเกตรูปแบบที่ซ้ำในความสัมพันธ์ เข้าใจผู้อื่นและรู้จักตัวเองด้วย","ar":"حين تستقر في داخلك، لاحظ الأنماط المتكررة في العلاقات. افهم الآخرين وتعرّف إلى نفسك أيضًا."},"观察伴侣、亲子、代际和职场中的互动模式。":{"zh-CN":"观察伴侣、亲子、代际和职场中的互动模式。","zh-TW":"觀察伴侶、親子、代際和職場中的互動模式。","en":"Observe patterns with partners, children, generations and colleagues.","ja":"パートナー、親子、世代、職場での関わり方を見つめます。","th":"สังเกตรูปแบบกับคู่ชีวิต ลูก ต่างรุ่น และเพื่อนร่วมงาน","ar":"لاحظ أنماط التفاعل مع الشريك والأبناء والأجيال وفي العمل."},"从指责与重复，走向更清晰的表达。":{"zh-CN":"从指责与重复，走向更清晰的表达。","zh-TW":"從指責與重復，走向更清晰的表達。","en":"Move from blame and repetition toward clearer expression.","ja":"責め合いや繰り返しから、より明確な表現へ。","th":"จากการโทษกันและวนซ้ำ ไปสู่การสื่อสารที่ชัดเจนขึ้น","ar":"انتقل من اللوم والتكرار إلى تعبير أوضح."},"为关系找到一个小而可行的改变。":{"zh-CN":"为关系找到一个小而可行的改变。","zh-TW":"為關系找到一個小而可行的改變。","en":"Find a small, practical change for a relationship.","ja":"関係のために、小さく実行できる変化を見つけます。","th":"หาการเปลี่ยนแปลงเล็ก ๆ ที่ทำได้จริงในความสัมพันธ์","ar":"اعثر على تغيير صغير وممكن في العلاقة."},"为什么有些人一出现，你就不像自己":{"zh-CN":"为什么有些人一出现，你就不像自己","zh-TW":"為什么有些人一出現，你就不像自己","en":"Why do you feel unlike yourself around certain people?","ja":"あの人の前で、自分らしくいられないのはなぜ？","th":"ทำไมอยู่ใกล้บางคนแล้วไม่เป็นตัวเอง","ar":"لماذا لا تشعر بأنك نفسك مع بعض الناس؟"},"自我与阴影 · 从外指，到回看":{"zh-CN":"自我与阴影 · 从外指，到回看","zh-TW":"自我與陰影 · 從外指，到回看","en":"Self and shadow · From blaming outward to looking inward","ja":"自己と影・外を責めることから振り返りへ","th":"ตัวตนและเงา · จากชี้ออกไปสู่ย้อนมอง","ar":"الذات والظل · من الإشارة للخارج إلى التأمل الداخلي"},"阴影清单、投射练习、正念自我对话。":{"zh-CN":"阴影清单、投射练习、正念自我对话。","zh-TW":"陰影清單、投射練習、正念自我對話。","en":"Shadow inventory, projection practice and mindful self-dialogue.","ja":"影のリスト、投影の練習、マインドフルな自分との対話。","th":"สำรวจเงาในใจ ฝึกสังเกตการฉายภาพ และสนทนากับตัวเองอย่างมีสติ","ar":"جرد الظل، وتمرين الإسقاط، وحوار واعٍ مع الذات."},"为什么付出越多，彼此却越远":{"zh-CN":"为什么付出越多，彼此却越远","zh-TW":"為什么付出越多，彼此卻越遠","en":"Why can giving more leave you further apart?","ja":"尽くすほど、離れてしまうのはなぜ？","th":"ทำไมยิ่งให้มาก กลับยิ่งห่างกัน","ar":"لماذا تبتعدان رغم زيادة العطاء؟"},"伴侣关系 · 从追逃，到同频":{"zh-CN":"伴侣关系 · 从追逃，到同频","zh-TW":"伴侶關系 · 從追逃，到同頻","en":"Partnership · From pursuit and withdrawal to connection","ja":"パートナー関係・追う逃げるから共鳴へ","th":"คู่ชีวิต · จากไล่ตามและหลบหนีสู่จังหวะเดียวกัน","ar":"الشراكة · من الملاحقة والانسحاب إلى الانسجام"},"追逃模式识别、依恋类型观察、正念沟通四步。":{"zh-CN":"追逃模式识别、依恋类型观察、正念沟通四步。","zh-TW":"追逃模式識別、依戀類型觀察、正念溝通四步。","en":"Recognise pursuit-withdrawal patterns, observe attachment styles and practise four mindful communication steps.","ja":"追跡と回避のパターン、愛着傾向の観察、対話の4ステップ。","th":"รู้ทันวงจรไล่ตามและถอยห่าง สังเกตรูปแบบความผูกพัน และสื่อสารอย่างมีสติสี่ขั้น","ar":"التعرّف إلى نمط الملاحقة والانسحاب، وملاحظة التعلّق، وأربع خطوات للتواصل الواعي."},"说着「我为你好」，孩子却越来越远":{"zh-CN":"说着「我为你好」，孩子却越来越远","zh-TW":"說著「我為你好」，孩子卻越來越遠","en":"Why does “for your own good” push a child away?","ja":"「あなたのため」が、子どもを遠ざけるのはなぜ？","th":"พูดว่า “ทำเพื่อลูก” แต่ลูกกลับยิ่งห่าง","ar":"لماذا يبتعد الطفل حين تقول «لمصلحتك»؟"},"亲子关系 · 从投射，到目送":{"zh-CN":"亲子关系 · 从投射，到目送","zh-TW":"親子關系 · 從投射，到目送","en":"Parenting · From projection to letting a child grow","ja":"親子関係・投影から見守りへ","th":"พ่อแม่และลูก · จากฉายความคาดหวังสู่มองดูเขาเติบโต","ar":"العلاقة بالأبناء · من الإسقاط إلى إتاحة النمو"},"期待归还练习、正念倾听、界限与祝福。":{"zh-CN":"期待归还练习、正念倾听、界限与祝福。","zh-TW":"期待歸還練習、正念傾聽、界限與祝福。","en":"Release misplaced expectations, listen mindfully, and explore boundaries and goodwill.","ja":"期待を返す練習、マインドフルな傾聴、境界線と祝福。","th":"คืนความคาดหวัง ฟังอย่างมีสติ และเรียนรู้ขอบเขตกับความปรารถนาดี","ar":"تمرين إعادة التوقعات، والإصغاء الواعي، والحدود والتمنيات الطيبة."},"替上一代扛的那些，什么时候能放下":{"zh-CN":"替上一代扛的那些，什么时候能放下","zh-TW":"替上一代扛的那些，什么時候能放下","en":"When can you put down what you carry for earlier generations?","ja":"前の世代の重荷を、いつ下ろせるだろう？","th":"เมื่อไรจะวางภาระที่แบกแทนคนรุ่นก่อนได้","ar":"متى تضع الأعباء التي تحملها عن الأجيال السابقة؟"},"代际关系 · 从背负，到承接":{"zh-CN":"代际关系 · 从背负，到承接","zh-TW":"代際關系 · 從背負，到承接","en":"Generations · From carrying burdens to mindful inheritance","ja":"世代間の関係・背負うことから受け継ぐことへ","th":"ความสัมพันธ์ต่างรุ่น · จากแบกรับสู่รับช่วงอย่างรู้ตัว","ar":"العلاقات بين الأجيال · من الحمل إلى التلقّي الواعي"},"家谱图初绘、代际信念盘点、正念告别仪式。":{"zh-CN":"家谱图初绘、代际信念盘点、正念告别仪式。","zh-TW":"家譜圖初繪、代際信念盤點、正念告別儀式。","en":"Sketch a family map, review inherited beliefs and practise a mindful farewell ritual.","ja":"家族図、受け継いだ信念の振り返り、マインドフルな別れの儀式。","th":"ร่างแผนผังครอบครัว ทบทวนความเชื่อที่ส่งต่อ และพิธีอำลาอย่างมีสติ","ar":"رسم خريطة أولية للعائلة، ومراجعة المعتقدات الموروثة، وطقس وداع واعٍ."},"面对领导和规则，为什么会自动变小":{"zh-CN":"面对领导和规则，为什么会自动变小","zh-TW":"面對領導和規則，為什么會自動變小","en":"Why do you shrink before authority and rules?","ja":"上司や規則の前で、小さくなるのはなぜ？","th":"ทำไมรู้สึกตัวเล็กลงเมื่อเจอหัวหน้าหรือกฎ","ar":"لماذا تنكمش أمام السلطة والقواعد؟"},"权威关系 · 从服从，到对话":{"zh-CN":"权威关系 · 从服从，到对话","zh-TW":"權威關系 · 從服從，到對話","en":"Authority · From obedience to dialogue","ja":"権威との関係・服従から対話へ","th":"อำนาจ · จากเชื่อฟังสู่สนทนา","ar":"العلاقة بالسلطة · من الطاعة إلى الحوار"},"权威雕塑练习、内在评判者对话、边界重设。":{"zh-CN":"权威雕塑练习、内在评判者对话、边界重设。","zh-TW":"權威雕塑練習、內在評判者對話、邊界重設。","en":"Authority-sculpture exercise, dialogue with the inner critic and resetting boundaries.","ja":"権威の彫刻ワーク、内なる批判者との対話、境界線の見直し。","th":"ฝึกจำลองภาพอำนาจ คุยกับเสียงวิจารณ์ในใจ และตั้งขอบเขตใหม่","ar":"تمرين تجسيد السلطة، وحوار مع الناقد الداخلي، وإعادة ضبط الحدود."},"明明不缺，为何仍觉得匮乏与不安":{"zh-CN":"明明不缺，为何仍觉得匮乏与不安","zh-TW":"明明不缺，為何仍覺得匱乏與不安","en":"Why does scarcity linger even when you have enough?","ja":"足りているのに、不足や不安を感じるのはなぜ？","th":"ทั้งที่มีพอ ทำไมยังรู้สึกขาดแคลนและไม่มั่นคง","ar":"لماذا تشعر بالنقص والقلق رغم الكفاية؟"},"金钱关系 · 从恐惧，到丰盈":{"zh-CN":"金钱关系 · 从恐惧，到丰盈","zh-TW":"金錢關系 · 從恐懼，到豐盈","en":"Money · From fear to a sense of enough","ja":"お金との関係・恐れから豊かさへ","th":"เงิน · จากกลัวสู่รู้สึกเพียงพอ","ar":"العلاقة بالمال · من الخوف إلى الشعور بالكفاية"},"金钱叙事访谈、觉察匮乏感在身体的位置、丰盈冥想。":{"zh-CN":"金钱叙事访谈、觉察匮乏感在身体的位置、丰盈冥想。","zh-TW":"金錢敘事訪談、覺察匱乏感在身體的位置、豐盈冥想。","en":"Explore your money story, notice scarcity in the body and practise abundance meditation.","ja":"お金の物語を語る、体の不足感への気づき、豊かさの瞑想。","th":"สำรวจเรื่องเล่าเกี่ยวกับเงิน สังเกตความขาดแคลนในร่างกาย และภาวนาถึงความพอเพียง","ar":"استكشاف قصة المال، وملاحظة موضع شعور النقص في الجسد، وتأمل الوفرة."},"知道很多道理，关系还是原地打转":{"zh-CN":"知道很多道理，关系还是原地打转","zh-TW":"知道很多道理，關系還是原地打轉","en":"Why do relationships repeat despite all you understand?","ja":"わかっているのに、関係が変わらないのはなぜ？","th":"เข้าใจหลายอย่าง แต่ความสัมพันธ์ยังวนที่เดิม","ar":"لماذا تتكرر العلاقات رغم كل ما تعرفه؟"},"整合与行动 · 从重复，到转机":{"zh-CN":"整合与行动 · 从重复，到转机","zh-TW":"整合與行動 · 從重復，到轉機","en":"Integration and action · From repetition to change","ja":"統合と行動・繰り返しから転機へ","th":"เชื่อมโยงและลงมือ · จากวนซ้ำสู่เปลี่ยนแปลง","ar":"التكامل والعمل · من التكرار إلى التحوّل"},"卡点与契机对照、一分钟关系正念、转机行动书。":{"zh-CN":"卡点与契机对照、一分钟关系正念、转机行动书。","zh-TW":"卡點與契機對照、一分鐘關系正念、轉機行動書。","en":"Map obstacles and openings, practise one-minute relationship awareness and write an action plan.","ja":"行き詰まりと機会の対照、1分間の関係への気づき、転機の行動プラン。","th":"เทียบจุดติดขัดกับโอกาส ฝึกสติในความสัมพันธ์หนึ่งนาที และเขียนแผนลงมือ","ar":"مقارنة العوائق بالفرص، ودقيقة وعي بالعلاقة، وخطة عمل للتغيير."},"以自己的姓名为入口，从古文字意象、家族期待走向自我认领，写下只属于你的名字书。":{"zh-CN":"以自己的姓名为入口，从古文字意象、家族期待走向自我认领，写下只属于你的名字书。","zh-TW":"以自己的姓名為入口，從古文字意象、家族期待走向自我認領，寫下只屬于你的名字書。","en":"Begin with your name. Explore ancient character imagery and family expectations, then write a personal book of self-recognition.","ja":"名前を入口に、古文字のイメージや家族の期待から、自分を受けとめることへ。自分だけの名前の書を綴ります。","th":"เริ่มจากชื่อของคุณ สำรวจภาพอักษรโบราณและความคาดหวังครอบครัว สู่การยอมรับตัวตน แล้วเขียนหนังสือชื่อที่เป็นของคุณ","ar":"ابدأ باسمك، ومن صور الحروف القديمة وتوقعات العائلة انتقل إلى تقبّل نفسك، واكتب كتاب اسمك الخاص."},"逐字探索姓名的字源与象形意象。":{"zh-CN":"逐字探索姓名的字源与象形意象。","zh-TW":"逐字探索姓名的字源與象形意象。","en":"Explore the origins and imagery of each character in your name.","ja":"名前の一文字ずつ、その成り立ちと象形のイメージを探ります。","th":"สำรวจที่มาและภาพสัญลักษณ์ของแต่ละอักษรในชื่อ","ar":"استكشف أصول كل حرف في اسمك وصوره الرمزية."},"在一对一正念深谈中，觉察名字承载的期待。":{"zh-CN":"在一对一正念深谈中，觉察名字承载的期待。","zh-TW":"在一對一正念深談中，覺察名字承載的期待。","en":"Notice the expectations your name carries through individual mindful conversations.","ja":"個人のマインドフルな対話で、名前が担う期待に気づきます。","th":"รับรู้ความคาดหวังที่ชื่อแบกไว้ผ่านบทสนทนาอย่างมีสติตัวต่อตัว","ar":"لاحظ التوقعات التي يحملها اسمك عبر حوارات فردية واعية."},"在七次会面后，整理自己的《名字疗愈书》。":{"zh-CN":"在七次会面后，整理自己的《名字疗愈书》。","zh-TW":"在七次會面后，整理自己的《名字療愈書》。","en":"After seven meetings, assemble your personal Book of Name Healing.","ja":"7回の対話を終え、自分の「名前の癒やしの書」をまとめます。","th":"หลังพบกันเจ็ดครั้ง รวบรวมเป็นหนังสือเยียวยาผ่านชื่อของคุณ","ar":"بعد سبعة لقاءات، اجمع «كتاب التعافي عبر الاسم» الخاص بك."},"继续向内 · ONLINE PRACTICE":{"zh-CN":"继续向内 · ONLINE PRACTICE","zh-TW":"繼續向內 · ONLINE PRACTICE","en":"CONTINUE INWARD · ONLINE PRACTICE","ja":"心の内へ・オンラインの実践","th":"เดินทางเข้าสู่ใจ · ฝึกออนไลน์","ar":"إلى الداخل · ممارسة عبر الإنترنت"},"你不是一个人，":{"zh-CN":"你不是一个人，","zh-TW":"你不是一個人，","en":"You are not alone.","ja":"あなたは、ひとりではありません。","th":"คุณไม่ได้อยู่คนเดียว","ar":"لست وحدك،"},"欢迎你的所有心情。":{"zh-CN":"欢迎你的所有心情。","zh-TW":"歡迎你的所有心情。","en":"All your feelings are welcome.","ja":"どんな気持ちも、ここへ。","th":"ทุกความรู้สึกของคุณได้รับการต้อนรับ","ar":"كل مشاعرك مرحّب بها."},"从一个字的片刻，走向有人陪伴的练习。":{"zh-CN":"从一个字的片刻，走向有人陪伴的练习。","zh-TW":"從一個字的片刻，走向有人陪伴的練習。","en":"From a moment with a symbol to practice with companionship.","ja":"一文字とのひとときから、仲間と歩む実践へ。","th":"จากช่วงเวลากับหนึ่งอักษร สู่การฝึกที่มีเพื่อนร่วมทาง","ar":"من لحظة مع رمز إلى ممارسة برفقة الآخرين."},"字之三阶 · 线上正念体验":{"zh-CN":"字之三阶 · 线上正念体验","zh-TW":"字之三階 · 線上正念體驗","en":"THREE STAGES · ONLINE MINDFULNESS","ja":"文字の三段階・オンラインのマインドフルネス","th":"สามขั้นของอักษร · ประสบการณ์สติออนไลน์","ar":"ثلاث مراحل · تجربة يقظة عبر الإنترنت"},"向内行走，":{"zh-CN":"向内行走，","zh-TW":"向內行走，","en":"Journey inward,","ja":"心の内へ歩き、","th":"เดินเข้าสู่ภายใน","ar":"سر إلى داخلك،"},"再走向世界。":{"zh-CN":"再走向世界。","zh-TW":"再走向世界。","en":"then toward the world.","ja":"そして世界へ。","th":"แล้วค่อยเดินสู่โลก","ar":"ثم إلى العالم."},"你不是一个人，欢迎你的所有心情。":{"zh-CN":"你不是一个人，欢迎你的所有心情。","zh-TW":"你不是一個人，歡迎你的所有心情。","en":"You are not alone. All your feelings are welcome.","ja":"あなたはひとりではありません。どんな気持ちも歓迎します。","th":"คุณไม่ได้อยู่คนเดียว ทุกความรู้สึกได้รับการต้อนรับ","ar":"لست وحدك. كل مشاعرك مرحّب بها."},"从照顾自己，到理解他人":{"zh-CN":"从照顾自己，到理解他人","zh-TW":"從照顧自己，到理解他人","en":"From caring for yourself to understanding others","ja":"自分をいたわることから、他者の理解へ","th":"จากดูแลตัวเองสู่เข้าใจผู้อื่น","ar":"من العناية بالنفس إلى فهم الآخرين"},"三阶 · 一条向内的路":{"zh-CN":"三阶 · 一条向内的路","zh-TW":"三階 · 一條向內的路","en":"Three stages · One inward path","ja":"三段階・心の内への道","th":"สามขั้น · หนึ่งเส้นทางสู่ใจ","ar":"ثلاث مراحل · طريق إلى الداخل"},"找到适合此刻的起点":{"zh-CN":"找到适合此刻的起点","zh-TW":"找到適合此刻的起點","en":"Find a starting point for this moment","ja":"今の自分に合う始まりを","th":"หาจุดเริ่มที่เหมาะกับตอนนี้","ar":"اعثر على بداية تناسب لحظتك"},"第一期面向中年女性。以字为引，以体验为核心，给自己一段被认真陪伴的时间。":{"zh-CN":"第一期面向中年女性。以字为引，以体验为核心，给自己一段被认真陪伴的时间。","zh-TW":"第一期面向中年女性。以字為引，以體驗為核心，給自己一段被認真陪伴的時間。","en":"The first cohort is for midlife women. Guided by characters and lived experience, make time to be thoughtfully supported.","ja":"第1期はミドルエイジの女性が対象です。文字を導きに、体験を中心に、丁寧に伴走してもらう時間を自分へ。","th":"รุ่นแรกสำหรับผู้หญิงวัยกลางคน ใช้อักษรนำทางและประสบการณ์เป็นหลัก ให้เวลากับการได้รับการดูแลอย่างใส่ใจ","ar":"الدفعة الأولى للنساء في منتصف العمر. بالرموز دليلًا والتجربة محورًا، امنحي نفسك وقتًا لمرافقة مهتمة."},"STAGE":{"zh-CN":"STAGE","zh-TW":"STAGE","en":"STAGE","ja":"段階","th":"ขั้น","ar":"المرحلة"},"HOW WE PRACTICE":{"zh-CN":"HOW WE PRACTICE","zh-TW":"HOW WE PRACTICE","en":"HOW WE PRACTICE","ja":"練習の流れ","th":"วิธีฝึกของเรา","ar":"كيف نمارس"},"每一课，都有安定的节奏":{"zh-CN":"每一课，都有安定的节奏","zh-TW":"每一課，都有安定的節奏","en":"A steady rhythm in every class","ja":"一回ごとに、落ち着いたリズムを","th":"ทุกบทเรียนมีจังหวะที่มั่นคง","ar":"إيقاع مطمئن في كل درس"},"抽字 · 观形":{"zh-CN":"抽字 · 观形","zh-TW":"抽字 · 觀形","en":"Draw · Observe the form","ja":"文字を引く・形を見る","th":"จับอักษร · ดูรูปทรง","ar":"اختر رمزًا · تأمّل شكله"},"从一个字的形，留意自己的感受。":{"zh-CN":"从一个字的形，留意自己的感受。","zh-TW":"從一個字的形，留意自己的感受。","en":"Notice your feelings as you look at a character’s form.","ja":"文字の形を見ながら、自分の気持ちに気づきます。","th":"สังเกตความรู้สึกเมื่อมองรูปทรงของอักษร","ar":"لاحظ مشاعرك وأنت تتأمل شكل الرمز."},"解字 · 溯源":{"zh-CN":"解字 · 溯源","zh-TW":"解字 · 溯源","en":"Interpret · Trace the roots","ja":"文字を解く・源をたどる","th":"เข้าใจอักษร · ย้อนสู่ที่มา","ar":"افهم الرمز · تتبّع جذوره"},"借古文字意象，打开理解的入口。":{"zh-CN":"借古文字意象，打开理解的入口。","zh-TW":"借古文字意象，打開理解的入口。","en":"Let ancient imagery open a way to understanding.","ja":"古文字のイメージから、理解の入口を開きます。","th":"ใช้ภาพอักษรโบราณเปิดประตูสู่ความเข้าใจ","ar":"افتح باب الفهم عبر صور الحروف القديمة."},"照见 · 投射":{"zh-CN":"照见 · 投射","zh-TW":"照見 · 投射","en":"Reflect · Connect","ja":"見つめる・映し出す","th":"มองเห็น · เชื่อมโยง","ar":"تأمّل · اربط بحياتك"},"把字与生活连接，不评判地观察。":{"zh-CN":"把字与生活连接，不评判地观察。","zh-TW":"把字與生活連接，不評判地觀察。","en":"Connect the character with life and observe without judgment.","ja":"文字を暮らしにつなぎ、判断せずに観察します。","th":"เชื่อมอักษรกับชีวิตและสังเกตโดยไม่ตัดสิน","ar":"اربط الرمز بحياتك ولاحظ دون أحكام."},"正念 · 落实":{"zh-CN":"正念 · 落实","zh-TW":"正念 · 落實","en":"Mindfulness · Put into practice","ja":"マインドフルネス・日常へ","th":"สติ · นำไปใช้","ar":"اليقظة · التطبيق"},"回到呼吸与身体，把体验带进日常。":{"zh-CN":"回到呼吸与身体，把体验带进日常。","zh-TW":"回到呼吸與身體，把體驗帶進日常。","en":"Return to breath and body, and carry the experience into daily life.","ja":"呼吸と体に戻り、体験を日常へ持ち帰ります。","th":"กลับสู่ลมหายใจและร่างกาย แล้วนำประสบการณ์ไปใช้ในชีวิต","ar":"عد إلى التنفس والجسد وانقل التجربة إلى يومك."},"先有片刻，再有同行":{"zh-CN":"先有片刻，再有同行","zh-TW":"先有片刻，再有同行","en":"A moment first, then companionship","ja":"ひとときから、共に歩むことへ","th":"เริ่มจากช่วงเวลา แล้วมีเพื่อนร่วมทาง","ar":"لحظة أولًا، ثم رفقة"},"一个字体验 → 线上体验课 → 旅居静心营":{"zh-CN":"一个字体验 → 线上体验课 → 旅居静心营","zh-TW":"一個字體驗 → 線上體驗課 → 旅居靜心營","en":"Symbol experience → Online course → Mindfulness retreat","ja":"文字の体験 → オンライン講座 → 滞在型リトリート","th":"ประสบการณ์อักษร → คอร์สออนไลน์ → ค่ายพักใจ","ar":"تجربة الرمز ← دورة عبر الإنترنت ← خلوة تأمل"},"旅居静心营筹备中，时间与地点另行公布。":{"zh-CN":"旅居静心营筹备中，时间与地点另行公布。","zh-TW":"旅居靜心營籌備中，時間與地點另行公布。","en":"The retreat is in preparation. Dates and location will be announced.","ja":"滞在型リトリートは準備中です。日程と場所は後日ご案内します。","th":"ค่ายพักใจกำลังเตรียม วันและสถานที่จะประกาศภายหลัง","ar":"الخلوة قيد الإعداد. سيُعلن الموعد والمكان لاحقًا."},"看看第一阶 · 安己书 →":{"zh-CN":"看看第一阶 · 安己书 →","zh-TW":"看看第一階 · 安己書 →","en":"Explore stage one · Inner Ease →","ja":"第一段階・自分を安らげる書を見る →","th":"ดูขั้นแรก · หนังสือแห่งการดูแลใจ →","ar":"استكشف المرحلة الأولى · السكينة الذاتية ←"},"课程安排":{"zh-CN":"课程安排","zh-TW":"課程安排","en":"Schedule","ja":"受講構成","th":"การจัดคอร์ส","ar":"البرنامج"},"共修方式":{"zh-CN":"共修方式","zh-TW":"共修方式","en":"Practice format","ja":"参加形式","th":"รูปแบบการฝึก","ar":"طريقة الممارسة"},"开课日期":{"zh-CN":"开课日期","zh-TW":"開課日期","en":"Start date","ja":"開講日","th":"วันเริ่มคอร์ส","ar":"موعد البداية"},"班期待公布":{"zh-CN":"班期待公布","zh-TW":"班期待公布","en":"Dates to be announced","ja":"日程は後日ご案内","th":"จะประกาศรุ่นเรียนภายหลัง","ar":"ستُعلن المواعيد لاحقًا"},"课程费用":{"zh-CN":"课程费用","zh-TW":"課程費用","en":"Course fee","ja":"受講料","th":"ค่าเรียน","ar":"رسوم الدورة"},"待公布":{"zh-CN":"待公布","zh-TW":"待公布","en":"To be announced","ja":"後日ご案内","th":"จะประกาศภายหลัง","ar":"سيُعلن لاحقًا"},"TAKE WITH YOU":{"zh-CN":"TAKE WITH YOU","zh-TW":"TAKE WITH YOU","en":"TAKE WITH YOU","ja":"持ち帰るもの","th":"สิ่งที่จะได้รับ","ar":"ما تأخذه معك"},"这一程，带走什么":{"zh-CN":"这一程，带走什么","zh-TW":"這一程，帶走什么","en":"What you take from this journey","ja":"この道のりから、持ち帰るもの","th":"สิ่งที่จะนำกลับจากเส้นทางนี้","ar":"ما تحمله من هذه الرحلة"},"THE 7 CHAPTERS":{"zh-CN":"THE 7 CHAPTERS","zh-TW":"THE 7 CHAPTERS","en":"THE 7 CHAPTERS","ja":"七つの章","th":"เจ็ดบทเรียน","ar":"الفصول السبعة"},"七个字，七次练习":{"zh-CN":"七个字，七次练习","zh-TW":"七個字，七次練習","en":"Seven symbols, seven practices","ja":"七文字、七つの実践","th":"เจ็ดอักษร เจ็ดการฝึก","ar":"سبعة رموز، سبع ممارسات"},"七次会面，一本自己的书":{"zh-CN":"七次会面，一本自己的书","zh-TW":"七次會面，一本自己的書","en":"Seven meetings, a book of your own","ja":"七回の出会い、自分だけの一冊","th":"เจ็ดครั้งที่พบ หนังสือหนึ่งเล่มของคุณ","ar":"سبعة لقاءات وكتاب يخصّك"},"从名字到家族期待，从家族期待到自我认领。每一次会面的内容，会在了解你的期待后共同安排。":{"zh-CN":"从名字到家族期待，从家族期待到自我认领。每一次会面的内容，会在了解你的期待后共同安排。","zh-TW":"從名字到家族期待，從家族期待到自我認領。每一次會面的內容，會在了解你的期待后共同安排。","en":"From your name to family expectations, and onward to self-recognition. We plan each meeting together after understanding your hopes.","ja":"名前から家族の期待へ、そして自分を受けとめることへ。ご希望を伺いながら、毎回の内容を一緒に決めます。","th":"จากชื่อสู่ความคาดหวังครอบครัว แล้วสู่การยอมรับตัวตน เราจะวางแผนแต่ละครั้งร่วมกันหลังเข้าใจความหวังของคุณ","ar":"من الاسم إلى توقعات العائلة ثم تقبّل الذات. نخطط لكل لقاء معًا بعد فهم ما ترجوه."},"这门课适合此刻的我吗？":{"zh-CN":"这门课适合此刻的我吗？","zh-TW":"這門課適合此刻的我嗎？","en":"Is this course right for me now?","ja":"今の私に、この講座は合いますか？","th":"คอร์สนี้เหมาะกับฉันตอนนี้ไหม","ar":"هل تناسبني هذه الدورة الآن؟"},"如果你长期照顾别人，也想留一点时间照顾自己；愿意在小组中真诚表达、倾听，或希望借古文字探索内在，这里可以是一个起点。":{"zh-CN":"如果你长期照顾别人，也想留一点时间照顾自己；愿意在小组中真诚表达、倾听，或希望借古文字探索内在，这里可以是一个起点。","zh-TW":"如果你長期照顧別人，也想留一點時間照顧自己；愿意在小組中真誠表達、傾聽，或希望借古文字探索內在，這里可以是一個起點。","en":"If you often care for others and want time for yourself, are open to honest group sharing and listening, or wish to explore within through ancient characters, this can be a starting point.","ja":"人を支えることが多く、自分のための時間もほしい方。小さなグループで率直に語り、聴きたい方。古文字を通して内面を探りたい方にとって、ここは入口になります。","th":"หากคุณดูแลคนอื่นมานานและอยากมีเวลาให้ตัวเอง พร้อมแบ่งปันและฟังอย่างจริงใจในกลุ่ม หรืออยากสำรวจใจผ่านอักษรโบราณ ที่นี่อาจเป็นจุดเริ่มต้น","ar":"إذا كنت تعتني بالآخرين وتريد وقتًا لنفسك، أو ترغب في المشاركة والإصغاء بصدق أو استكشاف داخلك عبر الحروف القديمة، فقد تكون هذه بداية مناسبة."},"这是一门正念体验课，不提供速成方法，也不替代专业心理或医疗支持。":{"zh-CN":"这是一门正念体验课，不提供速成方法，也不替代专业心理或医疗支持。","zh-TW":"這是一門正念體驗課，不提供速成方法，也不替代專業心理或醫療支持。","en":"This is an experiential mindfulness course, not a quick fix or a substitute for professional psychological or medical care.","ja":"体験型のマインドフルネス講座です。即効の方法を提供するものではなく、心理・医療の専門的支援に代わるものでもありません。","th":"นี่คือคอร์สประสบการณ์สติ ไม่ใช่วิธีลัด และไม่ทดแทนการดูแลทางจิตวิทยาหรือการแพทย์","ar":"هذه دورة يقظة تجريبية، وليست حلًا سريعًا ولا بديلًا عن الدعم النفسي أو الطبي المتخصص."},"第二阶建议先完成安己书；如希望单独报名，可在报名意向中说明已有练习经历。":{"zh-CN":"第二阶建议先完成安己书；如希望单独报名，可在报名意向中说明已有练习经历。","zh-TW":"第二階建議先完成安己書；如希望單獨報名，可在報名意向中說明已有練習經歷。","en":"We suggest completing Inner Ease before stage two. For direct entry, describe your prior practice in the enquiry form.","ja":"第二段階は「自分を安らげる書」の修了をおすすめします。単独受講をご希望なら、相談フォームに経験をご記入ください。","th":"แนะนำให้จบขั้นดูแลใจก่อนขั้นสอง หากต้องการสมัครแยก โปรดอธิบายประสบการณ์ฝึกในแบบฟอร์ม","ar":"نقترح إتمام المرحلة الأولى قبل الثانية. للتسجيل المباشر، اذكر خبرتك السابقة في نموذج الاهتمام."},"下一步 · 相互认识":{"zh-CN":"下一步 · 相互认识","zh-TW":"下一步 · 相互認識","en":"NEXT · GET TO KNOW EACH OTHER","ja":"次の一歩・お互いを知る","th":"ขั้นต่อไป · ทำความรู้จักกัน","ar":"الخطوة التالية · نتعارف"},"把一段时间，留给自己。":{"zh-CN":"把一段时间，留给自己。","zh-TW":"把一段時間，留給自己。","en":"Set aside some time for yourself.","ja":"自分のために、ひとつの時間を。","th":"เก็บเวลาช่วงหนึ่งไว้ให้ตัวเอง","ar":"خصّص وقتًا لنفسك."},"填写意向 → 了解期待 → 确认班期与费用 → 入班":{"zh-CN":"填写意向 → 了解期待 → 确认班期与费用 → 入班","zh-TW":"填寫意向 → 了解期待 → 確認班期與費用 → 入班","en":"Enquire → Discuss hopes → Confirm dates and fee → Join","ja":"相談を記入 → 希望を共有 → 日程・料金を確認 → 参加","th":"แจ้งความสนใจ → พูดคุยความหวัง → ยืนยันรุ่นและราคา → เข้าเรียน","ar":"أبدِ اهتمامك ← نناقش توقعاتك ← نؤكد الموعد والرسوم ← تنضم"},"填写{course}报名意向 →":{"zh-CN":"填写{course}报名意向 →","zh-TW":"填寫{course}報名意向 →","en":"Enquire about {course} →","ja":"{course}の受講相談 →","th":"แจ้งความสนใจ {course} →","ar":"أبدِ اهتمامك بدورة {course} ←"},"填写后可通过邮件联系课程团队，暂不收款或占位。":{"zh-CN":"填写后可通过邮件联系课程团队，暂不收款或占位。","zh-TW":"填寫后可通過郵件聯系課程團隊，暫不收款或占位。","en":"Contact the course team by email after filling this in. No payment or place reservation is made here.","ja":"記入後、メールでチームに連絡できます。ここでは支払いも席の確保も行いません。","th":"กรอกแล้วติดต่อทีมทางอีเมลได้ ยังไม่มีการเก็บเงินหรือจองที่","ar":"يمكنك مراسلة فريق الدورة بعد التعبئة. لا يتم الدفع أو حجز مكان هنا."},"选填":{"zh-CN":"选填","zh-TW":"選填","en":"Optional","ja":"任意","th":"ไม่บังคับ","ar":"اختياري"},"一起开始 ·":{"zh-CN":"一起开始 ·","zh-TW":"一起開始 ·","en":"BEGIN TOGETHER ·","ja":"一緒に始める・","th":"เริ่มด้วยกัน ·","ar":"نبدأ معًا ·"},"先认识你。":{"zh-CN":"先认识你。","zh-TW":"先認識你。","en":"Let’s get to know you.","ja":"まず、あなたのことを。","th":"มาทำความรู้จักคุณก่อน","ar":"لنتعرّف إليك."},"也听听，你希望这一程带来什么。":{"zh-CN":"也听听，你希望这一程带来什么。","zh-TW":"也聽聽，你希望這一程帶來什么。","en":"Tell us what you hope this journey will bring.","ja":"この道のりに、どんなことを願っていますか。","th":"เล่าให้ฟังว่าคุณหวังให้เส้นทางนี้นำอะไรมา","ar":"أخبرنا بما تأمل أن تحمله لك هذه الرحلة."},"填写后先保存本机草稿，再由你打开邮件确认发送至 oracleanswered@gmail.com；保存不会自动提交或预订名额。":{"zh-CN":"填写后先保存本机草稿，再由你打开邮件确认发送至 oracleanswered@gmail.com；保存不会自动提交或预订名额。","zh-TW":"填寫后先保存本機草稿，再由你打開郵件確認發送至 oracleanswered@gmail.com；保存不會自動提交或預訂名額。","en":"Save a draft on this device, then open your email app to review and send it to oracleanswered@gmail.com. Saving does not submit it or reserve a place.","ja":"まず端末に下書きを保存し、メールアプリで確認して oracleanswered@gmail.com へ送信します。保存だけでは送信も予約もされません。","th":"บันทึกร่างในเครื่องก่อน แล้วเปิดแอปอีเมลเพื่อตรวจและส่งไป oracleanswered@gmail.com การบันทึกไม่ใช่การส่งหรือจองที่","ar":"احفظ مسودة على الجهاز، ثم راجعها وأرسلها من تطبيق بريدك إلى oracleanswered@gmail.com. الحفظ لا يرسلها ولا يحجز مكانًا."},"意向课程":{"zh-CN":"意向课程","zh-TW":"意向課程","en":"Course of interest","ja":"希望の講座","th":"คอร์สที่สนใจ","ar":"الدورة المطلوبة"},"姓名":{"zh-CN":"姓名","zh-TW":"姓名","en":"Name","ja":"氏名","th":"ชื่อ","ar":"الاسم"},"国家":{"zh-CN":"国家","zh-TW":"國家","en":"Country","ja":"国","th":"ประเทศ","ar":"الدولة"},"地区 / 城市":{"zh-CN":"地区 / 城市","zh-TW":"地區 / 城市","en":"Region / city","ja":"地域・都市","th":"ภูมิภาค / เมือง","ar":"المنطقة / المدينة"},"地区":{"zh-CN":"地区","zh-TW":"地區","en":"Region","ja":"地域","th":"ภูมิภาค","ar":"المنطقة"},"性别":{"zh-CN":"性别","zh-TW":"性別","en":"Gender","ja":"性別","th":"เพศ","ar":"النوع"},"年龄":{"zh-CN":"年龄","zh-TW":"年齡","en":"Age","ja":"年齢","th":"อายุ","ar":"العمر"},"邮箱":{"zh-CN":"邮箱","zh-TW":"郵箱","en":"Email","ja":"メールアドレス","th":"อีเมล","ar":"البريد الإلكتروني"},"电话（含国家区号）":{"zh-CN":"电话（含国家区号）","zh-TW":"電話（含國家區號）","en":"Phone, including country code","ja":"電話番号（国番号を含む）","th":"โทรศัพท์พร้อมรหัสประเทศ","ar":"الهاتف مع رمز الدولة"},"电话":{"zh-CN":"电话","zh-TW":"電話","en":"Phone","ja":"電話番号","th":"โทรศัพท์","ar":"الهاتف"},"暂不填写":{"zh-CN":"暂不填写","zh-TW":"暫不填寫","en":"Leave blank","ja":"未記入","th":"ยังไม่ระบุ","ar":"اتركه فارغًا"},"女":{"zh-CN":"女","zh-TW":"女","en":"Woman","ja":"女性","th":"หญิง","ar":"امرأة"},"男":{"zh-CN":"男","zh-TW":"男","en":"Man","ja":"男性","th":"ชาย","ar":"رجل"},"自我描述 / 其他":{"zh-CN":"自我描述 / 其他","zh-TW":"自我描述 / 其他","en":"Self-described / other","ja":"自己記述・その他","th":"อธิบายเอง / อื่น ๆ","ar":"وصف ذاتي / آخر"},"不愿透露":{"zh-CN":"不愿透露","zh-TW":"不愿透露","en":"Prefer not to say","ja":"回答しない","th":"ไม่ประสงค์ระบุ","ar":"أفضل عدم الإفصاح"},"为什么想来？":{"zh-CN":"为什么想来？","zh-TW":"為什么想來？","en":"What brings you here?","ja":"参加したい理由は？","th":"อะไรทำให้คุณอยากเข้าร่วม","ar":"ما الذي يدفعك للمشاركة؟"},"选填 · 500 字以内":{"zh-CN":"选填 · 500 字以内","zh-TW":"選填 · 500 字以內","en":"Optional · Up to 500 characters","ja":"任意・500文字以内","th":"ไม่บังคับ · ไม่เกิน 500 ตัวอักษร","ar":"اختياري · حتى 500 حرف"},"此刻你最想照顾的，是生活的哪一部分？":{"zh-CN":"此刻你最想照顾的，是生活的哪一部分？","zh-TW":"此刻你最想照顧的，是生活的哪一部分？","en":"Which part of your life most needs care right now?","ja":"今、暮らしのどの部分を大切にしたいですか？","th":"ตอนนี้อยากดูแลส่วนไหนของชีวิตมากที่สุด","ar":"أي جانب من حياتك يحتاج إلى العناية الآن؟"},"我同意把以上资料保存在此浏览器中，知道保存不等于发送；后续可自行通过邮件联系课程团队，也可随时删除草稿。":{"zh-CN":"我同意把以上资料保存在此浏览器中，知道保存不等于发送；后续可自行通过邮件联系课程团队，也可随时删除草稿。","zh-TW":"我同意把以上資料保存在此瀏覽器中，知道保存不等于發送；后續可自行通過郵件聯系課程團隊，也可隨時刪除草稿。","en":"I agree to save these details in this browser and understand this does not send them. I can email the course team myself or delete the draft at any time.","ja":"このブラウザーへの情報保存に同意し、保存は送信ではないことを理解しました。自分でチームにメールでき、下書きはいつでも削除できます。","th":"ฉันยินยอมให้เก็บข้อมูลในเบราว์เซอร์นี้ และเข้าใจว่าการบันทึกไม่ใช่การส่ง ฉันส่งอีเมลถึงทีมเองหรือลบร่างได้ทุกเมื่อ","ar":"أوافق على حفظ البيانات في هذا المتصفح وأفهم أن الحفظ لا يعني الإرسال. يمكنني مراسلة الفريق بنفسي أو حذف المسودة في أي وقت."},"保存报名意向草稿 →":{"zh-CN":"保存报名意向草稿 →","zh-TW":"保存報名意向草稿 →","en":"Save enquiry draft →","ja":"受講相談の下書きを保存 →","th":"บันทึกร่างความสนใจ →","ar":"احفظ مسودة الاهتمام ←"},"已保存于本机":{"zh-CN":"已保存于本机","zh-TW":"已保存于本機","en":"SAVED ON THIS DEVICE","ja":"この端末に保存済み","th":"บันทึกในเครื่องแล้ว","ar":"محفوظ على هذا الجهاز"},"意向已记下。":{"zh-CN":"意向已记下。","zh-TW":"意向已記下。","en":"Your interest is noted.","ja":"ご希望を保存しました。","th":"บันทึกความสนใจแล้ว","ar":"سُجّل اهتمامك."},"，你为自己留出了一小步。":{"zh-CN":"，你为自己留出了一小步。","zh-TW":"，你為自己留出了一小步。","en":", you have taken a small step for yourself.","ja":"さん、自分のための小さな一歩ですね。","th":" คุณได้ก้าวเล็ก ๆ เพื่อตัวเองแล้ว","ar":"، لقد خطوت خطوة صغيرة لنفسك."},"班期与费用待公布":{"zh-CN":"班期与费用待公布","zh-TW":"班期與費用待公布","en":"Dates and fee to be announced","ja":"日程と料金は後日ご案内","th":"จะประกาศรุ่นและค่าเรียนภายหลัง","ar":"ستُعلن المواعيد والرسوم لاحقًا"},"保存不会自动发送。点击下方按钮，在自己的邮件应用中确认收件人与内容，再发送给课程团队。班期与费用以团队回复为准。":{"zh-CN":"保存不会自动发送。点击下方按钮，在自己的邮件应用中确认收件人与内容，再发送给课程团队。班期与费用以团队回复为准。","zh-TW":"保存不會自動發送。點擊下方按鈕，在自己的郵件應用中確認收件人與內容，再發送給課程團隊。班期與費用以團隊回復為準。","en":"Saving does not send the enquiry. Use the button below, check the recipient and contents in your email app, then send. Dates and fees are confirmed by the team’s reply.","ja":"保存だけでは送信されません。下のボタンでメールアプリを開き、宛先と内容を確認して送信してください。日程と料金はチームの返信で確定します。","th":"บันทึกแล้วจะยังไม่ส่ง กดปุ่มด้านล่าง ตรวจผู้รับและเนื้อหาในแอปอีเมล แล้วส่งถึงทีม วันและค่าเรียนยึดตามคำตอบจากทีม","ar":"الحفظ لا يرسل الطلب. افتح بريدك بالزر أدناه وراجع المستلم والمحتوى ثم أرسل. تُعتمد المواعيد والرسوم وفق رد الفريق."},"打开邮件发送报名 ↗":{"zh-CN":"打开邮件发送报名 ↗","zh-TW":"打開郵件發送報名 ↗","en":"Open email to send enquiry ↗","ja":"メールを開いて相談を送信 ↗","th":"เปิดอีเมลเพื่อส่งความสนใจ ↗","ar":"افتح البريد لإرسال الاستفسار ↗"},"收件人：":{"zh-CN":"收件人：","zh-TW":"收件人：","en":"Recipient:","ja":"宛先：","th":"ผู้รับ:","ar":"المستلم:"},"若没有邮件应用，可下载资料后手动发到此邮箱。":{"zh-CN":"若没有邮件应用，可下载资料后手动发到此邮箱。","zh-TW":"若沒有郵件應用，可下載資料后手動發到此郵箱。","en":"Without an email app, download your details and send them to this address manually.","ja":"メールアプリがない場合は、資料をダウンロードしてこの宛先へ送ってください。","th":"หากไม่มีแอปอีเมล ดาวน์โหลดข้อมูลแล้วส่งไปที่อีเมลนี้ด้วยตัวเองได้","ar":"إذا لم يكن لديك تطبيق بريد، نزّل البيانات وأرسلها يدويًا إلى هذا العنوان."},"下载我的意向资料 ↓":{"zh-CN":"下载我的意向资料 ↓","zh-TW":"下載我的意向資料 ↓","en":"Download my enquiry ↓","ja":"相談内容をダウンロード ↓","th":"ดาวน์โหลดข้อมูลความสนใจ ↓","ar":"نزّل بيانات اهتمامي ↓"},"继续编辑":{"zh-CN":"继续编辑","zh-TW":"繼續編輯","en":"Continue editing","ja":"編集を続ける","th":"แก้ไขต่อ","ar":"تابع التحرير"},"删除本机意向资料":{"zh-CN":"删除本机意向资料","zh-TW":"刪除本機意向資料","en":"Delete enquiry from this device","ja":"この端末の相談データを削除","th":"ลบข้อมูลความสนใจในเครื่อง","ar":"احذف بيانات الاهتمام من الجهاز"},"请填写姓名、国家、地区和电话。":{"zh-CN":"请填写姓名、国家、地区和电话。","zh-TW":"請填寫姓名、國家、地區和電話。","en":"Please enter your name, country, region and phone.","ja":"氏名、国、地域、電話番号をご記入ください。","th":"กรุณากรอกชื่อ ประเทศ ภูมิภาค และโทรศัพท์","ar":"يرجى إدخال الاسم والدولة والمنطقة والهاتف."},"保存未成功，请检查浏览器是否允许本地存储。":{"zh-CN":"保存未成功，请检查浏览器是否允许本地存储。","zh-TW":"保存未成功，請檢查瀏覽器是否允許本地存儲。","en":"Could not save. Check whether your browser allows local storage.","ja":"保存できませんでした。ブラウザーのローカル保存設定をご確認ください。","th":"บันทึกไม่สำเร็จ โปรดตรวจว่าเบราว์เซอร์อนุญาตการเก็บข้อมูลในเครื่อง","ar":"تعذّر الحفظ. تحقق من سماح المتصفح بالتخزين المحلي."},"删除未成功，请重试。":{"zh-CN":"删除未成功，请重试。","zh-TW":"刪除未成功，請重試。","en":"Could not delete. Please try again.","ja":"削除できませんでした。もう一度お試しください。","th":"ลบไม่สำเร็จ โปรดลองอีกครั้ง","ar":"تعذّر الحذف. حاول مجددًا."},"本机意向资料已删除":{"zh-CN":"本机意向资料已删除","zh-TW":"本機意向資料已刪除","en":"Local enquiry deleted","ja":"この端末の相談データを削除しました","th":"ลบข้อมูลในเครื่องแล้ว","ar":"حُذفت بيانات الاهتمام المحلية"},"本机草稿，未提交给课程团队":{"zh-CN":"本机草稿，未提交给课程团队","zh-TW":"本機草稿，未提交給課程團隊","en":"Local draft, not submitted to the course team","ja":"端末内の下書きです。チームには未送信です","th":"ร่างในเครื่อง ยังไม่ได้ส่งให้ทีมคอร์ส","ar":"مسودة محلية لم تُرسل إلى فريق الدورة"},"报名原因":{"zh-CN":"报名原因","zh-TW":"報名原因","en":"Reason for joining","ja":"参加理由","th":"เหตุผลที่สนใจ","ar":"سبب المشاركة"},"未填写":{"zh-CN":"未填写","zh-TW":"未填寫","en":"Not provided","ja":"未記入","th":"ไม่ได้ระบุ","ar":"غير مذكور"},"您好，我想了解「{course}」的班期与费用。":{"zh-CN":"您好，我想了解「{course}」的班期与费用。","zh-TW":"您好，我想了解「{course}」的班期與費用。","en":"Hello, I would like to ask about dates and fees for {course}.","ja":"こんにちは。{course}の日程と受講料について知りたいです。","th":"สวัสดีค่ะ/ครับ ฉันต้องการทราบรุ่นเรียนและค่าใช้จ่ายของ {course}","ar":"مرحبًا، أود الاستفسار عن مواعيد ورسوم {course}."},"请与我联系，确认课程安排。":{"zh-CN":"请与我联系，确认课程安排。","zh-TW":"請與我聯系，確認課程安排。","en":"Please contact me to confirm the course arrangements.","ja":"講座の予定についてご連絡ください。","th":"โปรดติดต่อฉันเพื่อยืนยันรายละเอียดคอร์ส","ar":"يرجى التواصل معي لتأكيد ترتيبات الدورة."},"字有答案线上课报名意向 ·":{"zh-CN":"字有答案线上课报名意向 ·","zh-TW":"字有答案線上課報名意向 ·","en":"Daily Symbol course enquiry ·","ja":"字有答案・オンライン講座の相談・","th":"สนใจคอร์สออนไลน์ Daily Symbol ·","ar":"استفسار عن دورة رموز اليوم ·"}},"readings":{"1":{"zh-CN":"看到“启”，在你的心里已找到了一扇窗，你只是还没决定什么时候推。 那种“卡在门口”想开始又怕不够好的担忧，并非障碍，而是身体在说：“我在乎结果”。这份在乎，会让你开始之后走得更稳，而不是更慢。亲手打开窗，光就有机会进来，对话才能发生。你不是没有行动力，只是在用“迟迟不动”保护自己不被评判。窗在那里，手在你的身上，你已经有“推开”的一切条件。","zh-TW":"看到“啟”，在你的心里已找到了一扇窗，你只是還沒決定什么時候推。 那種“卡在門口”想開始又怕不夠好的擔憂，并非障礙，而是身體在說：“我在乎結果”。這份在乎，會讓你開始之后走得更穩，而不是更慢。親手打開窗，光就有機會進來，對話才能發生。你不是沒有行動力，只是在用“遲遲不動”保護自己不被評判。窗在那里，手在你的身上，你已經有“推開”的一切條件。","en":"You have already found a window within; you are deciding when to open it. Hesitating at the threshold does not mean you lack the ability to act. It may mean you care about the outcome and want protection from judgment. That care can steady your first steps. You do not have to prove you are ready before beginning. The window is there, and your hand can reach it. A small opening lets light and conversation enter.","ja":"心の中の窓は、もう見つかっています。今は開ける時を選んでいるところ。始めたいのに不安になるのは、行動力がないからではなく、結果を大切にし、評価から自分を守ろうとしているからかもしれません。その思いは、最初の一歩を支える力にもなります。準備が完璧である証明はいりません。窓はそこにあり、手も届きます。少し開ければ、光と対話が入る余地が生まれます。","th":"คุณพบหน้าต่างในใจแล้ว เพียงกำลังเลือกว่าจะเปิดเมื่อไร ความลังเลไม่ได้แปลว่าลงมือไม่ได้ แต่อาจเพราะคุณใส่ใจผลลัพธ์และอยากปกป้องตัวเองจากคำตัดสิน ความใส่ใจนี้ช่วยให้ก้าวแรกมั่นคงได้ ไม่ต้องพิสูจน์ว่าพร้อมสมบูรณ์ก่อนเริ่ม หน้าต่างอยู่ตรงนั้นและมือเอื้อมถึง แง้มเพียงนิด แสงและบทสนทนาก็มีทางเข้ามา","ar":"لقد وجدت نافذة في داخلك، وتختار متى تفتحها. التردد عند العتبة لا يعني افتقاد القدرة؛ ربما يعني أنك تهتم بالنتيجة وتحمي نفسك من الأحكام. يمكن لهذا الاهتمام أن يثبّت خطواتك الأولى. لا تحتاج إلى إثبات جاهزيتك الكاملة. النافذة موجودة ويدك تصل إليها؛ فتحة صغيرة تتيح للضوء والحوار الدخول."},"2":{"zh-CN":"“伫”意味着心里那个珍视的东西你没有丢掉它，也没有急着打开它。你只是选择了先放好。这本身就是一种智慧。那种想拿出来又怕，想往前走又被什么拽着的顾虑，并不是为了停在原地责怪自己，而是允许自己“暂时不动”。不是所有的停顿都是逃避，停顿带来对的时机。\n\n重要之物存放在一个四方的盒子里，盒子没有锁，盖子也没有封死。\n\n伫，不是“永远不放出来”，而是现在先放好，暂时被妥善保管。\n\n对自己的不耐烦，不是你该消灭的敌人，恰恰说明你在乎，它是你心里那股“想动又不能动”的能量在说话，这份在乎，不是问题，是燃料。你不是被困住了，你是主动选择“先放好”的。“伫”给你的自由是：你可以选择什么时候动，也可以选择不动。","zh-TW":"“佇”意味著心里那個珍視的東西你沒有丟掉它，也沒有急著打開它。你只是選擇了先放好。這本身就是一種智慧。那種想拿出來又怕，想往前走又被什么拽著的顧慮，并不是為了停在原地責怪自己，而是允許自己“暫時不動”。不是所有的停頓都是逃避，停頓帶來對的時機。\n\n重要之物存放在一個四方的盒子里，盒子沒有鎖，蓋子也沒有封死。\n\n佇，不是“永遠不放出來”，而是現在先放好，暫時被妥善保管。\n\n對自己的不耐煩，不是你該消滅的敵人，恰恰說明你在乎，它是你心里那股“想動又不能動”的能量在說話，這份在乎，不是問題，是燃料。你不是被困住了，你是主動選擇“先放好”的。“佇”給你的自由是：你可以選擇什么時候動，也可以選擇不動。","en":"What matters to you has not been lost. You have chosen to keep it safe for now, like something held in an unlocked box. A pause is not always avoidance; it can protect the right timing. Impatience shows that the wish to move is still alive. You need not turn that energy against yourself. You can decide when to lift the lid, and you can also choose to wait. Keeping something safe is different from abandoning it.","ja":"大切なものを失ったのではありません。鍵のない箱に、今はそっと収めているのです。立ち止まることは、いつも逃避とは限りません。よい時を待つ知恵でもあります。焦りは、動きたい力がまだあるしるし。その力で自分を責めなくて大丈夫です。蓋を開ける時も、もう少し待つことも、自分で選べます。大切に置いておくことと、諦めることは違います。","th":"สิ่งสำคัญไม่ได้หายไป คุณเพียงเลือกเก็บไว้อย่างปลอดภัยเหมือนของในกล่องที่ไม่ได้ล็อก การหยุดไม่ใช่การหนีเสมอไป บางครั้งคือการรอเวลาที่เหมาะ ความกระสับกระส่ายบอกว่าความอยากก้าวต่อยังอยู่ ไม่ต้องใช้พลังนั้นตำหนิตัวเอง คุณเลือกได้ว่าจะเปิดกล่องเมื่อไร หรือจะรอก่อน การเก็บรักษาไม่เหมือนการทอดทิ้ง","ar":"لم تفقد ما يهمك؛ اخترت أن تحفظه الآن، كشيء في صندوق غير مقفل. التوقف ليس هروبًا دائمًا، وقد يتيح التوقيت المناسب. نفاد الصبر يدل على أن الرغبة في الحركة ما زالت حية. لا توجّه هذه الطاقة ضد نفسك. يمكنك اختيار وقت رفع الغطاء، كما يمكنك الانتظار. الحفظ ليس تخلّيًا."},"3":{"zh-CN":"“谢”意味着你心里有一份“想要表达”的温柔，哪怕还没说出口，这份愿意本身，就已经是谢的开始。当接受到别人的好，并非是欠的开始，迟迟未谢并不是冷漠，忧思是你对关系的在意，在意“谢得够不够好”，这是你心里珍贵的柔软的善意。不需要华美和昂贵，只要让对方感受到双手呈递出的那一份走心的敬意。这个姿势里，没有“交换”，没有“偿还”。你不是欠了谁，你只是恰好被关照过。谢，不是你还回去，也不是结束，而是递出去之后空了的手，已经完成了一次让美好流经你，再呈递出去，对下一份美好的成全与流转。","zh-TW":"“謝”意味著你心里有一份“想要表達”的溫柔，哪怕還沒說出口，這份愿意本身，就已經是謝的開始。當接受到別人的好，并非是欠的開始，遲遲未謝并不是冷漠，憂思是你對關系的在意，在意“謝得夠不夠好”，這是你心里珍貴的柔軟的善意。不需要華美和昂貴，只要讓對方感受到雙手呈遞出的那一份走心的敬意。這個姿勢里，沒有“交換”，沒有“償還”。你不是欠了誰，你只是恰好被關照過。謝，不是你還回去，也不是結束，而是遞出去之后空了的手，已經完成了一次讓美好流經你，再呈遞出去，對下一份美好的成全與流轉。","en":"The wish to express gratitude is already a beginning. Receiving kindness does not place you in debt, and searching for the right words does not make you indifferent. You care about the relationship. Thanks need not be expensive or elaborate; a sincere gesture is enough. Imagine offering it with both hands, without bargaining or repayment. Something good has passed through your life. Letting it flow onward can complete the gesture without closing the relationship.","ja":"感謝を伝えたいと思うことから、もう始まっています。親切を受けたからといって借りができるわけではなく、言葉を探す時間も冷たさではありません。関係を大切にしているのです。高価な物や立派な言葉より、両手で差し出すような誠実さを。交換や返済ではなく、自分を通った温かさを次へ届ける。その一つの動きで十分です。","th":"ความอยากขอบคุณคือจุดเริ่มต้นแล้ว การรับน้ำใจไม่ได้ทำให้คุณเป็นหนี้ และการหาคำพูดไม่เจอก็ไม่ใช่ความเฉยชา คุณกำลังใส่ใจความสัมพันธ์ คำขอบคุณไม่ต้องแพงหรือสวยหรู แค่จริงใจเหมือนยื่นให้ด้วยสองมือ โดยไม่ต่อรองหรือชดใช้ ความดีได้ผ่านเข้ามาในชีวิต การส่งต่อก็ทำให้ท่าทีนั้นสมบูรณ์ได้","ar":"الرغبة في الشكر بداية بحد ذاتها. تلقّي اللطف لا يجعلك مدينًا، والبحث عن الكلمات لا يعني اللامبالاة؛ أنت تهتم بالعلاقة. لا يحتاج الامتنان إلى كلفة أو تكلّف. تخيّل تقديمه بكلتا يديك، بلا مقايضة أو سداد. مرّ شيء جميل بحياتك، ويمكنك أن تدعه ينتقل عبرك إلى غيرك."},"4":{"zh-CN":"“念”意味着心里有话，也许很久没说了，也许不知道该对谁说。你愿意低下头听，这已经是善待自己了。念头反复、散乱、停不下来时，请放下对自己“想太多”的评判，多是你有着丰富内心的养分。\n\n念，是你愿意把飘着的想法，往内留出一个通道，不论说什么，心都在下方承接着。因为在意，所以思量。念头不是你，你是那个低下头看见游离的念头，却不被念头带走的人才是不变的你。","zh-TW":"“念”意味著心里有話，也許很久沒說了，也許不知道該對誰說。你愿意低下頭聽，這已經是善待自己了。念頭反復、散亂、停不下來時，請放下對自己“想太多”的評判，多是你有著豐富內心的養分。\n\n念，是你愿意把飄著的想法，往內留出一個通道，不論說什么，心都在下方承接著。因為在意，所以思量。念頭不是你，你是那個低下頭看見游離的念頭，卻不被念頭帶走的人才是不變的你。","en":"There may be words within you that have waited a long time to be heard. Turning inward to listen is already an act of care. When thoughts scatter or repeat, try not to make “thinking too much” another accusation. Your inner life has richness. Give wandering thoughts a passage toward the heart that can hold them. You can notice a thought without having to follow it. You are also the person who sees it arrive and pass.","ja":"心の中に、長く聴かれずにいた言葉があるのかもしれません。耳を傾けること自体が、自分へのいたわりです。考えが散らばったり繰り返したりしても、「考えすぎ」と責めなくて大丈夫。豊かな内面の動きでもあります。思いが心へ降りてくる道を作ってください。考えに気づくことと、その考えに従うことは別です。訪れては去る思いを見ている自分も、ここにいます。","th":"อาจมีคำในใจที่รอให้ใครฟังมานาน การหันมาฟังก็เป็นการดูแลตัวเองแล้ว เมื่อความคิดกระจัดกระจายหรือวนซ้ำ อย่าเพิ่มคำตำหนิว่า “คิดมาก” ชีวิตข้างในของคุณมีความอุดมสมบูรณ์ เปิดทางให้ความคิดลอยลงสู่ใจที่รองรับมัน คุณสังเกตความคิดได้โดยไม่ต้องตามไป คุณยังเป็นคนที่มองเห็นมันมาและผ่านไปด้วย","ar":"ربما تحمل كلمات انتظرت طويلًا أن تُسمع. الإصغاء إلى داخلك رعاية بحد ذاته. حين تتشتت الأفكار أو تتكرر، لا تجعل «التفكير الزائد» اتهامًا آخر. في داخلك غنى. امنح الأفكار ممرًا نحو قلب يحتضنها. يمكنك ملاحظة الفكرة دون اتباعها؛ أنت أيضًا من يراها تأتي وتمضي."},"5":{"zh-CN":"“语”意味着心里装了许多许多的话，不知从何开始，也许不知道该对谁倾诉。你愿意让它们出来，这已经是对自己的慷慨。想说不敢说，说了没人听，听了不被懂，这份小心翼翼的“堵”，并不是责怪自己“表达能力差”的素材，而是提醒你对说出来后结果的担心。话语被表达出来，你就已经做的很好了，就像蒲公英积蓄了种子，离开枝干的时候，就已经完成了最圆满的表达，而落在哪会带来什么样的结果交由风和土。心里那团乱的、多的、说不清的千言万语，愿意打开一条缝，让它们一个一个出来。怕说错、怕被误解，这份对关系的在意和想要说好的意愿，就已经是对关系最有温度的诚意。你不是要说得多漂亮，只需要让话真实地讲出来，像水从杯口自然地溢出，就够了。","zh-TW":"“語”意味著心里裝了許多許多的話，不知從何開始，也許不知道該對誰傾訴。你愿意讓它們出來，這已經是對自己的慷慨。想說不敢說，說了沒人聽，聽了不被懂，這份小心翼翼的“堵”，并不是責怪自己“表達能力差”的素材，而是提醒你對說出來后結果的擔心。話語被表達出來，你就已經做的很好了，就像蒲公英積蓄了種子，離開枝干的時候，就已經完成了最圓滿的表達，而落在哪會帶來什么樣的結果交由風和土。心里那團亂的、多的、說不清的千言萬語，愿意打開一條縫，讓它們一個一個出來。怕說錯、怕被誤解，這份對關系的在意和想要說好的意愿，就已經是對關系最有溫度的誠意。你不是要說得多漂亮，只需要讓話真實地講出來，像水從杯口自然地溢出，就夠了。","en":"So much may be waiting to be said that you do not know where to begin. Fear of misunderstanding shows that speaking and connection matter to you; it does not prove you are bad at expression. Open a small gap and let one honest sentence emerge. Like seeds leaving a dandelion, words cannot control where they land. You can offer them sincerely without controlling every response. Truthfulness matters more than a flawless performance.","ja":"言いたいことが多すぎて、どこから話せばよいかわからないのかもしれません。誤解への不安は、表現やつながりを大切にしているしるしです。話し方が下手という証明ではありません。小さな隙間を作り、正直なひと言から。タンポポの種が風に渡るように、言葉の着地点はすべて管理できません。完璧に話すより、誠実に差し出すことを大切にしてください。","th":"อาจมีคำมากมายจนไม่รู้จะเริ่มตรงไหน กลัวคนเข้าใจผิดแปลว่าการสื่อสารและความสัมพันธ์สำคัญกับคุณ ไม่ได้พิสูจน์ว่าคุณพูดไม่เก่ง เปิดช่องเล็ก ๆ ให้ประโยคจริงใจออกมาก่อน เหมือนเมล็ดดอกไม้ที่ปลิวไป คำพูดควบคุมจุดตกไม่ได้ คุณส่งมันอย่างจริงใจได้โดยไม่ต้องกำกับทุกคำตอบ ความจริงสำคัญกว่าการพูดอย่างไร้ที่ติ","ar":"قد تتزاحم الكلمات حتى لا تعرف من أين تبدأ. الخوف من سوء الفهم يدل على اهتمامك بالتعبير والعلاقة، لا على ضعفك فيهما. افتح مساحة صغيرة لجملة صادقة. مثل بذور الهندباء، لا تتحكم الكلمات في موضع هبوطها. قدّمها بإخلاص دون محاولة إدارة كل رد؛ الصدق أهم من الأداء المثالي."},"6":{"zh-CN":"“并”字，意味着有一段珍视的关系，一份合作，一种“我要我们在们一起”的念头。当下还在寻找那个“独立又不孤单”的平衡点。如若太近，会担心没了自己，要么太远，怕断了联系。这份在意，不是负担，是你还有能力看见“我们”。越想处理好关系，越容易在平静的外表下把内在的自己弄累了。并，不需要你丢掉自己，也不需要你扛起对方。两个人在现有的距离中，找到一个共同的方向，当共赴一致方向的时候，一前一后、谁大谁小的内部拉扯便会升华到更广阔的视野之上。并，不是亲密无间的连体，你不需要一个人扛起一段关系。并，是你知道旁边有人，但你依然也可以在走自己的路。并是同站在一片广袤的土地，你是独立的，也允许对方独立，心里知道“我们在一起”。","zh-TW":"“并”字，意味著有一段珍視的關系，一份合作，一種“我要我們在們一起”的念頭。當下還在尋找那個“獨立又不孤單”的平衡點。如若太近，會擔心沒了自己，要么太遠，怕斷了聯系。這份在意，不是負擔，是你還有能力看見“我們”。越想處理好關系，越容易在平靜的外表下把內在的自己弄累了。并，不需要你丟掉自己，也不需要你扛起對方。兩個人在現有的距離中，找到一個共同的方向，當共赴一致方向的時候，一前一后、誰大誰小的內部拉扯便會升華到更廣闊的視野之上。并，不是親密無間的連體，你不需要一個人扛起一段關系。并，是你知道旁邊有人，但你依然也可以在走自己的路。并是同站在一片廣袤的土地，你是獨立的，也允許對方獨立，心里知道“我們在一起”。","en":"You may be seeking a balance between independence and closeness. Too near can feel like losing yourself; too far can feel like losing the bond. Caring about “us” does not mean carrying the relationship alone. Stand beside each other and look for a shared direction. You can remain yourself and let the other person remain themselves. Togetherness need not erase the space between you. Knowing someone is beside you can support you as you walk your own path.","ja":"自立と親しさの間で、ちょうどよい距離を探しているのかもしれません。近すぎれば自分がなくなり、遠すぎればつながりが切れそう。「私たち」を大切にしても、ひとりで関係を背負う必要はありません。並んで立ち、共通の方向を見つけること。自分も相手も、それぞれのままでいてよいのです。間に余白があっても、共に歩くことはできます。","th":"คุณอาจกำลังหาสมดุลระหว่างเป็นตัวเองกับใกล้ชิด ใกล้เกินไปกลัวเสียตัวตน ไกลเกินไปกลัวเสียสายสัมพันธ์ การใส่ใจคำว่า “เรา” ไม่ได้หมายถึงต้องแบกความสัมพันธ์คนเดียว ลองยืนข้างกันแล้วมองทิศทางร่วม คุณยังเป็นตัวเองและให้อีกคนเป็นเขาได้ ความใกล้ชิดไม่ต้องลบช่องว่างทั้งหมด แค่รู้ว่ามีคนอยู่ข้าง ๆ ก็ช่วยให้เดินเส้นทางตัวเองได้","ar":"قد تبحث عن توازن بين الاستقلال والقرب. قرب شديد قد يشعرك بفقدان نفسك، وبعد شديد بفقدان الرابط. الاهتمام بـ«نحن» لا يعني حمل العلاقة وحدك. قفا جنبًا إلى جنب وابحثا عن اتجاه مشترك. يمكنك البقاء نفسك وترك الآخر على طبيعته. لا يلزم أن يمحو اللقاء المسافة بينكما؛ وجود رفيق قد يسند طريقك الخاص."},"7":{"zh-CN":"“播”，意味着内在萌动的想法、计划、愿望，你并有没丢掉这些珍贵，你只是在找合适的地方，把放下去。对结果的在意，代表着你对它的看重。担心也往往在自于太想等来一个期望的结果，至少能够说明“没有白做”。而当你开始筛选种子的时候，价值创造就已经开始了。没有白做的瞬间，所有的经历都组成了今天丰盛的你。播，不是乱撒，是基于分类的有意识地培养——这颗放这里，那颗放那里。播，不是越多越好。播，是你愿意先整理、再筛选、然后种下。急于收成的心，是对未来仍然有着希望的生机，请无需评判自己的这份急切。将这份急切置换成耐心的浇水，不去控制每一颗种子怎么长，只需要把对的种子放进对的格子。做你能做的，允许结果不按你的时间表来。","zh-TW":"“播”，意味著內在萌動的想法、計劃、愿望，你并有沒丟掉這些珍貴，你只是在找合適的地方，把放下去。對結果的在意，代表著你對它的看重。擔心也往往在自于太想等來一個期望的結果，至少能夠說明“沒有白做”。而當你開始篩選種子的時候，價值創造就已經開始了。沒有白做的瞬間，所有的經歷都組成了今天豐盛的你。播，不是亂撒，是基于分類的有意識地培養——這顆放這里，那顆放那里。播，不是越多越好。播，是你愿意先整理、再篩選、然后種下。急于收成的心，是對未來仍然有著希望的生機，請無需評判自己的這份急切。將這份急切置換成耐心的澆水，不去控制每一顆種子怎么長，只需要把對的種子放進對的格子。做你能做的，允許結果不按你的時間表來。","en":"Your ideas and hopes are still alive; they need somewhere suitable to take root. Sowing is not scattering everything everywhere. It begins with sorting seeds and choosing where each belongs. Wanting a harvest shows that you care about the future, so you need not judge your impatience. Turn some of it into patient watering. Choose what you can plant and tend, while allowing growth to follow a timetable beyond your control.","ja":"アイデアや願いはまだ生きています。根を下ろす場所を探しているのです。種まきは、何でも散らすことではありません。種を選び、それぞれに合う場所を見つけることから始まります。収穫を急ぎたいのも、未来への期待があるから。焦りを責めず、その力を水やりの辛抱強さへ。できることを手入れし、育つ速さには余地を残してください。","th":"ความคิดและความหวังยังมีชีวิต เพียงต้องการที่เหมาะให้หยั่งราก การหว่านไม่ใช่โยนทุกอย่างไปทั่ว แต่เริ่มจากคัดเมล็ดและเลือกที่ให้แต่ละเมล็ด อยากเห็นผลแปลว่าคุณยังใส่ใจอนาคต ไม่ต้องตัดสินความใจร้อน ลองเปลี่ยนบางส่วนเป็นการรดน้ำอย่างอดทน ปลูกและดูแลสิ่งที่ทำได้ พร้อมยอมให้การเติบโตมีเวลาของมัน","ar":"أفكارك وآمالك حية وتحتاج أرضًا مناسبة. البذر ليس نثر كل شيء في كل مكان؛ يبدأ بفرز البذور واختيار موضعها. الرغبة في الحصاد تعني اهتمامك بالمستقبل، فلا تحاكم استعجالك. حوّل بعضه إلى سقي صبور. ازرع ما تستطيع رعايته، واترك للنمو وقتًا لا تتحكم فيه بالكامل."},"8":{"zh-CN":"愿意承认“我现在看不清”，比假装一切清楚，更具勇气。勇气是你此刻宝贵的内在资源。越想离开，越受滞缓，越想看清，越加迷茫，行动越多，越感混乱。现状的这份“不想要”并非逃离恐惧，而是你在找到一个确定的方向。看不清的时候，停下来，比乱跑更需要智慧。没有永久的尘埃，混乱终有其时。尘是“经过”留下的痕迹，不是“存在”本身。恐惧是你的雷达，不会成为困住你的牢笼。它在提醒你，事缓则圆。这不是迷失，你只是进入了一段能见度低的路段，这不是你的错，只是环境变了。你不一定要对混乱做点什么，慢下来关照自己的身心，便是尘最好的回应。你只需要知道：尘会落，路还在。你能认出这是尘，就已经站在了尘的外面。","zh-TW":"愿意承認“我現在看不清”，比假裝一切清楚，更具勇氣。勇氣是你此刻寶貴的內在資源。越想離開，越受滯緩，越想看清，越加迷茫，行動越多，越感混亂。現狀的這份“不想要”并非逃離恐懼，而是你在找到一個確定的方向。看不清的時候，停下來，比亂跑更需要智慧。沒有永久的塵埃，混亂終有其時。塵是“經過”留下的痕跡，不是“存在”本身。恐懼是你的雷達，不會成為困住你的牢籠。它在提醒你，事緩則圓。這不是迷失，你只是進入了一段能見度低的路段，這不是你的錯，只是環境變了。你不一定要對混亂做點什么，慢下來關照自己的身心，便是塵最好的回應。你只需要知道：塵會落，路還在。你能認出這是塵，就已經站在了塵的外面。","en":"Admitting that you cannot see clearly takes courage. In a cloud of dust, moving faster may only make the path harder to read. This is a stretch of low visibility, not proof that you have lost your way. Fear can remind you to slow down and care for body and mind. You do not have to settle every confusion at once. Dust is something passing through the scene. It can settle while the road remains.","ja":"「今はよく見えない」と認めるのは、勇気です。砂ぼこりの中では、急ぐほど道が読みにくくなることもあります。見通しの悪い区間にいるだけで、道を失った証明ではありません。不安は、速度を落として心身をいたわる合図にもなります。すべての混乱を今すぐ解かなくて大丈夫。ほこりは通り過ぎるもの。落ち着いたあとにも、道は残っています。","th":"ยอมรับว่าตอนนี้มองไม่ชัดต้องใช้ความกล้า ในฝุ่นฟุ้ง ยิ่งรีบอาจยิ่งเห็นทางยาก นี่เป็นช่วงทัศนวิสัยต่ำ ไม่ใช่หลักฐานว่าคุณหลงทาง ความกลัวอาจเตือนให้ช้าลงและดูแลกายใจ ไม่ต้องคลี่คลายทุกความสับสนพร้อมกัน ฝุ่นเป็นสิ่งที่ผ่านเข้ามา มันตกลงได้ ขณะที่ทางยังอยู่","ar":"الاعتراف بأن الرؤية غير واضحة يحتاج شجاعة. وسط الغبار، قد يزيد الإسراع صعوبة قراءة الطريق. إنها مرحلة ضعف رؤية، لا دليل على ضياعك. يمكن للخوف أن يذكّرك بالتمهّل والعناية بالجسد والعقل. لا يلزم حل كل ارتباك الآن؛ الغبار عابر، ويمكنه أن يستقر فيما يبقى الطريق."},"9":{"zh-CN":"“净”意味着某一块地方不是你所期待的现状。你渴望着恢复被清理后的秩序和简单。不是完全摒弃它，只是想要它更清亮。这份愿意，已经是在善待身处其中的人和物了。\n\n堆积带来失序，一成不变也会制造着新的拥堵。忙碌会忘记及时的清理，时间一久的动手，又担心污渍比想象的多。放下“一次清净”对自己的完美要求，以及“越弄越糟”的顾虑，这份谨慎是你的珍贵的责任心使然。告诉自己，罗马不是一天建成的，允许自己跟随心情的节奏，从想动的时候完成擦拭一块砖开始，只清洁这一件。当你动了想要恢复清净的念头时，便已经将自己置身事内。洁净的每一处光亮里，有你亲手参与的善意。而你始终在过程中，不厌弃脏，而是看见脏，清洁脏，并祝福它恢复原有的“净”。就像擦拭一个脏的杯子，不因它曾经装过什么而心生情绪波澜，而是陪伴它恢复初始的干净，继续装下一个美好的东西。不是要把容器变成“没有过去”的人，你只是把那些不再服务于你的污渍送走。净，是你愿意躬身清理，并带着祝福。","zh-TW":"“凈”意味著某一塊地方不是你所期待的現狀。你渴望著恢復被清理后的秩序和簡單。不是完全摒棄它，只是想要它更清亮。這份愿意，已經是在善待身處其中的人和物了。\n\n堆積帶來失序，一成不變也會制造著新的擁堵。忙碌會忘記及時的清理，時間一久的動手，又擔心污漬比想象的多。放下“一次清凈”對自己的完美要求，以及“越弄越糟”的顧慮，這份謹慎是你的珍貴的責任心使然。告訴自己，羅馬不是一天建成的，允許自己跟隨心情的節奏，從想動的時候完成擦拭一塊磚開始，只清潔這一件。當你動了想要恢復清凈的念頭時，便已經將自己置身事內。潔凈的每一處光亮里，有你親手參與的善意。而你始終在過程中，不厭棄臟，而是看見臟，清潔臟，并祝福它恢復原有的“凈”。就像擦拭一個臟的杯子，不因它曾經裝過什么而心生情緒波瀾，而是陪伴它恢復初始的干凈，繼續裝下一個美好的東西。不是要把容器變成“沒有過去”的人，你只是把那些不再服務于你的污漬送走。凈，是你愿意躬身清理，并帶著祝福。","en":"Wanting things clearer is already a form of care. You need not erase the past or clean everything perfectly in one attempt. Begin with one cup, one tile, one small place. The aim is not to hate what has become dirty, but to help it serve life again. Like washing a cup without judging what it once held, let go of what no longer helps you. A small act of clearing can carry goodwill rather than self-reproach.","ja":"整えたいと思うことは、もういたわりです。過去を消す必要も、一度ですべてを完璧にきれいにする必要もありません。コップひとつ、タイル一枚、小さな場所から。汚れを嫌うより、また暮らしを支えられるように手をかけること。何が入っていたかを責めずに器を洗うように、今の自分に役立たないものを手放して。小さな掃除を、自責ではなく善意で。","th":"อยากให้สิ่งต่าง ๆ สะอาดชัดเจนขึ้นก็เป็นการดูแลแล้ว ไม่ต้องลบอดีตหรือทำให้สมบูรณ์ในครั้งเดียว เริ่มจากถ้วยใบเดียว กระเบื้องแผ่นเดียว หรือมุมเล็ก ๆ เป้าหมายไม่ใช่รังเกียจความสกปรก แต่ช่วยให้สิ่งนั้นรองรับชีวิตได้อีก เหมือนล้างถ้วยโดยไม่ตัดสินว่าเคยใส่อะไร ค่อยปล่อยสิ่งที่ไม่ช่วยคุณแล้ว ทำความสะอาดด้วยความหวังดีแทนการตำหนิตัวเอง","ar":"الرغبة في الصفاء رعاية بحد ذاتها. لا تحتاج إلى محو الماضي أو تنظيف كل شيء بإتقان دفعة واحدة. ابدأ بكوب أو بلاطة أو مساحة صغيرة. الهدف ليس كراهية ما اتّسخ، بل إعادته لخدمة الحياة. اغسل الكوب دون الحكم على ما احتواه، واترك ما لم يعد ينفعك. ليحمل التنظيف لطفًا لا لومًا."},"10":{"zh-CN":"“援”字意味着心里有一段关系、一份需要，或者一种“我可以伸手吗”的犹豫。怕被拒绝、怕亏欠感、怕给错了、怕接不住，这份担心恰恰是你在主动探寻一个合适的距离的参与度。递出者也是被成全者，接受者也是给予者。没有哪只手更高贵，也没有哪只手更卑微。援，不是“施”与“受”，是一段需要两只手同时完成的路。保持传递不松开，所要之物就不会掉，并且都会在两人的手心，共同持有。你的手此时还在传递的位置，就意味着你的相信还在。犹豫，恰恰是因为想要继续相信共同的一个结果，那不妨让这份相信更加大胆一些。你不是只站在一端的人。你有时是上的手，有时是下的手。能接，也是一种给；能给，也是一种接。你不需要是“救世主”，也不需要是“求助者”。你只是一个愿意让东西通过自己成就其价值的人。","zh-TW":"“援”字意味著心里有一段關系、一份需要，或者一種“我可以伸手嗎”的猶豫。怕被拒絕、怕虧欠感、怕給錯了、怕接不住，這份擔心恰恰是你在主動探尋一個合適的距離的參與度。遞出者也是被成全者，接受者也是給予者。沒有哪只手更高貴，也沒有哪只手更卑微。援，不是“施”與“受”，是一段需要兩只手同時完成的路。保持傳遞不松開，所要之物就不會掉，并且都會在兩人的手心，共同持有。你的手此時還在傳遞的位置，就意味著你的相信還在。猶豫，恰恰是因為想要繼續相信共同的一個結果，那不妨讓這份相信更加大膽一些。你不是只站在一端的人。你有時是上的手，有時是下的手。能接，也是一種給；能給，也是一種接。你不需要是“救世主”，也不需要是“求助者”。你只是一個愿意讓東西通過自己成就其價值的人。","en":"Reaching out can bring fear of rejection, indebtedness or getting it wrong. That hesitation may be your search for a respectful distance. Support is a path that needs two hands; neither hand is above the other. Receiving can also be a gift, and giving can open you to receiving. You need not become a rescuer or define yourself by needing help. You can simply participate in something that becomes possible together.","ja":"手を伸ばすとき、断られる不安、借りを作る不安、間違える不安があるかもしれません。それは、互いを尊重する距離を探している動きでもあります。支え合いは、二つの手で進む道。どちらが上でも下でもありません。受け取ることも贈り物になり、与えることで受け取る余地も生まれます。救う人や救われる人になりきらず、共にできることへ参加してください。","th":"การยื่นมืออาจมาพร้อมกลัวถูกปฏิเสธ กลัวติดค้าง หรือช่วยผิดทาง ความลังเลอาจเป็นการห ระยะที่เคารพกัน การเกื้อหนุนเป็นทางที่ต้องใช้สองมือ ไม่มีมือไหนสูงหรือต่ำกว่า การรับก็เป็นการให้ได้ และการให้ก็เปิดให้รับ คุณไม่ต้องเป็นผู้กอบกู้หรือนิยามตัวเองว่าเป็นคนขอความช่วยเหลือ เพียงร่วมทำสิ่งที่เป็นไปได้เมื่ออยู่ด้วยกัน","ar":"قد يصاحب مدّ اليد خوف من الرفض أو الدَّين أو الخطأ. ربما تبحث بذلك عن مسافة محترمة. الدعم طريق يحتاج يدين، ولا تعلو إحداهما الأخرى. التلقّي قد يكون عطاءً، والعطاء يفتح باب التلقّي. لا يلزم أن تصبح منقذًا أو أن تختزل نفسك في طلب المساعدة؛ شارك فيما يصبح ممكنًا معًا."},"11":{"zh-CN":"“听”意味着心里有一份“想要听懂”的温柔，哪怕对方的话很乱、很长、很重复。你的耐心还在，你没有走开。怕自己听漏了、听错了、不知道怎么回应，这份担心恰恰是你还在乎对方话语的证明。急着说、打腹稿、提前准备答案，都是太想“回应得好”的表现。其实听不需要你回得好。听只需要你的临在。耳朵只有一只，嘴有两张。话可以从不同的方向来，而你只有一个耳朵，但你让它进来。听，不是筛选“什么值得听”。听，是你愿意让声音找到你，不设门槛。你不是要听懂每一个字。你只需要让对方知道：我在。听，是你允许别人的声音，暂时住进你的安静里。它来了，它也会走。你不必留下它，也不必急着送走它。","zh-TW":"“聽”意味著心里有一份“想要聽懂”的溫柔，哪怕對方的話很亂、很長、很重復。你的耐心還在，你沒有走開。怕自己聽漏了、聽錯了、不知道怎么回應，這份擔心恰恰是你還在乎對方話語的證明。急著說、打腹稿、提前準備答案，都是太想“回應得好”的表現。其實聽不需要你回得好。聽只需要你的臨在。耳朵只有一只，嘴有兩張。話可以從不同的方向來，而你只有一個耳朵，但你讓它進來。聽，不是篩選“什么值得聽”。聽，是你愿意讓聲音找到你，不設門檻。你不是要聽懂每一個字。你只需要讓對方知道：我在。聽，是你允許別人的聲音，暫時住進你的安靜里。它來了，它也會走。你不必留下它，也不必急著送走它。","en":"Your wish to understand is a kind of gentleness, even when someone’s words are tangled or repeated. Worrying about the perfect reply can draw attention away from listening. You do not have to understand every word or solve what you hear. Let the other person know you are present. A voice can stay briefly in your quiet without becoming yours to keep or hurry away. Listening begins with making room.","ja":"言葉がまとまらなくても、何度繰り返されても、わかりたいと願うことは優しさです。完璧な返事を考えすぎると、聴くことから離れることもあります。すべてを理解したり、解決したりしなくて大丈夫。「ここにいる」と伝えてください。声がしばらく自分の静けさに滞在しても、抱え続ける必要も、追い出す必要もありません。聴くことは、場所を作ることから。","th":"ความอยากเข้าใจเป็นความอ่อนโยน แม้คำพูดอีกคนจะสับสนหรือซ้ำไปมา การมัวหาคำตอบที่สมบูรณ์อาจดึงคุณออกจากการฟัง ไม่ต้องเข้าใจทุกคำหรือแก้ทุกเรื่อง เพียงให้อีกคนรู้ว่าคุณอยู่ตรงนี้ เสียงของเขาพักในความเงียบของคุณชั่วครู่ได้ โดยไม่ต้องเก็บไว้หรือรีบไล่ไป การฟังเริ่มจากการให้พื้นที่","ar":"رغبتك في الفهم لطف، حتى حين تكون الكلمات متشابكة أو متكررة. الانشغال بالرد المثالي قد يبعدك عن الإصغاء. لا يلزم فهم كل كلمة أو حل ما تسمعه. دع الآخر يعرف أنك حاضر. يمكن لصوته أن يمكث قليلًا في هدوئك دون أن تحتفظ به أو تعجّل رحيله. يبدأ الإصغاء بإفساح المجال."},"12":{"zh-CN":"“专”意味着心里有一个想要“收拢”的方向——念头散着、事情堆着、注意力飘着。你渴望把散落的收成一股，把杂乱的理成一条。这份渴望，不是焦虑，是你还在乎“做成”的那个自己。怕分心、怕乱、怕绕来绕去回不到原点。这份怕，恰恰是你想要专注的证明。散乱不是你的错，是你还没有找到那根“线头”。专，不是把门关起来不许任何声音进来。是你手里握着线，知道该往哪个方向绕。一只手握纱锤，丝线从散到整，从乱到序。轮在转，手在动，线在收。专，不是一动不动。专，是动的每一圈，都绕在同一根轴上。你不追两只兔子，你只理这一根线。你不是没有专注力。你是太久没有给自己一个“可以慢慢绕”的下午。专，是你允许自己只做一件事——做完，放下；下一件，再说。线会乱，也会顺。手在，轮在，你就在。","zh-TW":"“專”意味著心里有一個想要“收攏”的方向——念頭散著、事情堆著、注意力飄著。你渴望把散落的收成一股，把雜亂的理成一條。這份渴望，不是焦慮，是你還在乎“做成”的那個自己。怕分心、怕亂、怕繞來繞去回不到原點。這份怕，恰恰是你想要專注的證明。散亂不是你的錯，是你還沒有找到那根“線頭”。專，不是把門關起來不許任何聲音進來。是你手里握著線，知道該往哪個方向繞。一只手握紗錘，絲線從散到整，從亂到序。輪在轉，手在動，線在收。專，不是一動不動。專，是動的每一圈，都繞在同一根軸上。你不追兩只兔子，你只理這一根線。你不是沒有專注力。你是太久沒有給自己一個“可以慢慢繞”的下午。專，是你允許自己只做一件事——做完，放下；下一件，再說。線會亂，也會順。手在，輪在，你就在。","en":"You may long to gather scattered thoughts into one direction. Wanting focus is not proof that you have failed at it. Imagine a spindle drawing loose threads around one centre: focus can move, provided it keeps returning to the same work. You need not shut out every sound. Give yourself permission to tend one thread, finish one task and set it down before the next. Tangled things can become orderly through patient handling.","ja":"散らばる考えを、ひとつの方向へまとめたいのかもしれません。集中を望むことは、集中できない人という証明ではありません。ばらばらの糸を一本の軸に巻く紡錘のように、動きながら戻り続ける集中もあります。すべての音を締め出さず、一本の糸に手をかけて。一つを終え、置いてから次へ。絡まりも、丁寧に扱えばほどけていきます。","th":"คุณอาจอยากรวบรวมความคิดที่กระจายให้มีทิศทางเดียว ความอยากจดจ่อไม่ได้แปลว่าคุณทำไม่ได้ ลองนึกถึงแกนหมุนที่รวบเส้นด้าย การจดจ่อเคลื่อนไหวได้ ถ้ายังกลับมาที่งานเดียวกัน ไม่ต้องปิดทุกเสียง อนุญาตให้ตัวเองดูแลด้ายเส้นเดียว ทำเรื่องหนึ่งให้เสร็จแล้ววางก่อนเริ่มเรื่องต่อไป สิ่งพันกันค่อย ๆ เป็นระเบียบได้ด้วยความอดทน","ar":"قد ترغب في جمع الأفكار المتناثرة في اتجاه واحد. طلب التركيز ليس دليلًا على فشلك فيه. تخيّل مغزلًا يلف الخيوط حول محور واحد؛ التركيز قد يتحرك ما دام يعود إلى العمل نفسه. لا تحتاج إلى إغلاق الباب أمام كل صوت. اعتنِ بخيط واحد، وأنهِ مهمة ثم ضعها قبل التالية. بالصبر ينتظم المتشابك."},"13":{"zh-CN":"“见”意味着心里有一份“想要看清楚”的渴望——想看清方向、看清关系、看清自己到底要什么。可你越用力看，越觉得模糊。这份模糊，不是你的眼睛坏了，是你太久没有用自己的眼睛看过自己。怕看不清、怕看错了、怕看见却无能为力。这份怕，恰恰是你还在意“看见”这件事的证明。见，不是你用别人的标准审视自己，是你创造一个平静的时刻，坐下来，用自己的眼睛，看一遍自己的来时路。从哪里开始，体验了什么，获得了什么。见，不是眼睛在动，是整个人停下来，允许眼睛看清楚。你不是看不见，你是太久没有让自己“被自己看见”。任何时刻，你愿意看，就已经是见了。","zh-TW":"“見”意味著心里有一份“想要看清楚”的渴望——想看清方向、看清關系、看清自己到底要什么。可你越用力看，越覺得模糊。這份模糊，不是你的眼睛壞了，是你太久沒有用自己的眼睛看過自己。怕看不清、怕看錯了、怕看見卻無能為力。這份怕，恰恰是你還在意“看見”這件事的證明。見，不是你用別人的標準審視自己，是你創造一個平靜的時刻，坐下來，用自己的眼睛，看一遍自己的來時路。從哪里開始，體驗了什么，獲得了什么。見，不是眼睛在動，是整個人停下來，允許眼睛看清楚。你不是看不見，你是太久沒有讓自己“被自己看見”。任何時刻，你愿意看，就已經是見了。","en":"Wanting clarity can become tiring when you only look through other people’s standards. Take a quiet moment to see your path with your own eyes: where you began, what you experienced and what you gained. Seeing is not always looking harder; sometimes your whole self needs to stop. You may have gone too long without allowing yourself to be seen by you. The willingness to look is already a beginning.","ja":"他人の基準で見続けると、はっきりさせたい気持ちが疲れに変わることがあります。静かな時間を作り、自分の目で歩みを見てください。どこから始め、何を経験し、何を得たのか。見ることは、目を凝らすことばかりではありません。自分全体が止まることも必要です。自分に自分を見てもらう、その気持ちがもう始まりです。","th":"ความอยากเห็นชัดอาจทำให้เหนื่อย หากมองผ่านมาตรฐานคนอื่นตลอด ลองมีช่วงเงียบ ๆ มองเส้นทางด้วยตาของตัวเอง เริ่มที่ไหน ผ่านอะไร และได้รับอะไร การเห็นไม่ใช่เพ่งแรงขึ้นเสมอไป บางครั้งทั้งตัวต้องหยุด คุณอาจไม่ได้ยอมให้ตัวเองมองเห็นตัวเองมานานแล้ว ความเต็มใจที่จะมองก็คือจุดเริ่ม","ar":"قد تُتعبك الرغبة في الوضوح حين تنظر بمعايير الآخرين فقط. خذ لحظة هادئة لترى طريقك بعينيك: من أين بدأت، وما عشته وما اكتسبته. الرؤية ليست دائمًا مزيدًا من التحديق؛ أحيانًا يحتاج كيانك كله إلى التوقف. ربما طال غياب نظرتك إلى نفسك. الاستعداد للنظر بداية بحد ذاته."},"14":{"zh-CN":"“安”是对还未发生的事情过度思虑的提醒符号。你所经历的担心、不确定感，或许有翻来覆去的时刻。“安”并非是风平浪静，没有事发生，而是任何时候，能够在波动的不同气候里，都能给自己找一个坐下来的地方，相信自己在经历着挑战，也同时拥有着安全。怕失控、怕落空、怕那些还没发生的不好的事。这份怕，是你想把生活过好把事做好的美好期待，是你内心的灿烂在具体事物的延伸。不安是正常的，它也提醒着我们需要再一次温和地觉察自己的心绪是否在盯着外界太久了。允许自己把心收进来——把心从外面那些抓不住的事情上，慢慢收回来，放在胸腔里，让它跳它的。你不是要强行控制进展，不是消灭不安，你只需要知道：心里的坚固屋顶在，那个带着不安依然还能选择“坐下来”的那个自己在，安住就在。","zh-TW":"“安”是對還未發生的事情過度思慮的提醒符號。你所經歷的擔心、不確定感，或許有翻來覆去的時刻。“安”并非是風平浪靜，沒有事發生，而是任何時候，能夠在波動的不同氣候里，都能給自己找一個坐下來的地方，相信自己在經歷著挑戰，也同時擁有著安全。怕失控、怕落空、怕那些還沒發生的不好的事。這份怕，是你想把生活過好把事做好的美好期待，是你內心的燦爛在具體事物的延伸。不安是正常的，它也提醒著我們需要再一次溫和地覺察自己的心緒是否在盯著外界太久了。允許自己把心收進來——把心從外面那些抓不住的事情上，慢慢收回來，放在胸腔里，讓它跳它的。你不是要強行控制進展，不是消滅不安，你只需要知道：心里的堅固屋頂在，那個帶著不安依然還能選擇“坐下來”的那個自己在，安住就在。","en":"Ease does not require a life without disturbance. It can mean finding somewhere to sit while uncertainty is still present. Worry about what has not happened may grow from your wish to live well, but attention can return from what you cannot hold to the body here. Let the heart beat without managing every outcome. You do not have to eliminate unease to find shelter within. Even with fear, you can choose a place to settle.","ja":"安らぎは、何も起こらない暮らしだけにあるのではありません。不確かさがあっても、腰を下ろせる場所を見つけること。まだ起きていないことへの心配は、よく生きたい願いからかもしれません。つかめない外のことから、ここにある体へ意識を戻して。すべての結果を管理せず、心臓にそのリズムを任せる。不安が残っていても、内側に休める場所を選べます。","th":"ความสงบไม่จำเป็นต้องเป็นชีวิตที่ไม่มีเรื่องรบกวน แต่อาจคือการหาที่นั่งได้แม้ยังไม่แน่นอน ความกังวลต่อสิ่งที่ยังไม่เกิดอาจมาจากความอยากใช้ชีวิตให้ดี ลองพาความสนใจจากสิ่งที่จับไม่ได้กลับมาที่ร่างกาย ปล่อยให้หัวใจเต้นโดยไม่จัดการทุกผลลัพธ์ คุณไม่ต้องกำจัดความไม่สบายใจก่อนจึงจะพักได้ แม้กลัวก็เลือกที่วางใจได้","ar":"السكينة لا تشترط حياة بلا اضطراب. قد تعني إيجاد موضع للجلوس مع بقاء عدم اليقين. القلق على ما لم يحدث قد ينشأ من رغبتك في حياة جيدة، لكن انتباهك يستطيع العودة من الخارج إلى جسدك هنا. دع القلب ينبض دون إدارة كل نتيجة. لا يلزم محو القلق كي تجد مأوى داخليًا؛ يمكنك الاستقرار رغم الخوف."},"15":{"zh-CN":"“和”意味着正处在“对不上”的关系里——你说了，对方没懂；你做了，结果不是想要的；你努力靠近，却感觉越来越远。你并不是放弃自己融入别处。怕冲突、怕不合群、怕自己跟别人不一样就被落下。这份怕，是还在乎“我们”这个词，且不想把自己弄丢。\n\n和，不是你变成别人。是你带着自己的音高，找到那个能一起吹的曲子。几根长短不同的禾管，编在一起，各自有各自的音高，却能吹出同一首曲子。管子不用一样长，声音不用一样大。你能够发出自己的声，也能和他人合在一起，自然地找到舒适的节奏。你不必压抑自己来换取和谐，也不必大声盖过别人来证明自己。你不是那个“对不上”的人。你只是一根还没找到同伴的管子。气息从你身体里出来，经过你，变成声音——那个声音是独特的。会有人听见，会有别的管子跟上来。合鸣，不是谁压过谁，是各自发声，同时好听。","zh-TW":"“和”意味著正處在“對不上”的關系里——你說了，對方沒懂；你做了，結果不是想要的；你努力靠近，卻感覺越來越遠。你并不是放棄自己融入別處。怕沖突、怕不合群、怕自己跟別人不一樣就被落下。這份怕，是還在乎“我們”這個詞，且不想把自己弄丟。\n\n和，不是你變成別人。是你帶著自己的音高，找到那個能一起吹的曲子。幾根長短不同的禾管，編在一起，各自有各自的音高，卻能吹出同一首曲子。管子不用一樣長，聲音不用一樣大。你能夠發出自己的聲，也能和他人合在一起，自然地找到舒適的節奏。你不必壓抑自己來換取和諧，也不必大聲蓋過別人來證明自己。你不是那個“對不上”的人。你只是一根還沒找到同伴的管子。氣息從你身體里出來，經過你，變成聲音——那個聲音是獨特的。會有人聽見，會有別的管子跟上來。合鳴，不是誰壓過誰，是各自發聲，同時好聽。","en":"Harmony does not ask you to become someone else or silence your own note. Imagine pipes of different lengths sounding one tune: each keeps its pitch while joining the others. Fear of conflict can show that you value connection without wanting to lose yourself. You need not shout over others or disappear beneath them. Listen for a rhythm where your particular voice can belong. Togetherness can be made of differences that are still heard.","ja":"調和のために、別人になったり、自分の音を消したりする必要はありません。長さの違う管が、一つの曲を奏でるように。それぞれの音の高さを保ちながら、合わせられます。衝突への不安には、つながりも自分も大切にしたい思いがあります。かき消す大声も、消えてしまう我慢もいりません。自分の声を含めて響くリズムを探してください。","th":"ความกลมกลืนไม่ได้ขอให้คุณเป็นคนอื่นหรือปิดเสียงตัวเอง ลองนึกถึงท่อดนตรีต่างความยาวที่เล่นเพลงเดียวกัน แต่ละท่อยังมีระดับเสียงของมัน กลัวขัดแย้งอาจเพราะคุณเห็นค่าความสัมพันธ์และไม่อยากเสียตัวเอง ไม่ต้องตะโกนทับใครหรือหายไปใต้เสียงเขา ลองฟังจังหวะที่เสียงเฉพาะของคุณมีที่อยู่ ความต่างยังอยู่ร่วมกันได้","ar":"الانسجام لا يطلب أن تصبح شخصًا آخر أو تسكت نغمتك. تخيّل أنابيب مختلفة الأطوال تعزف لحنًا واحدًا؛ تحتفظ كل منها بصوتها. الخوف من الصراع قد يدل على تقديرك للصلة دون فقدان نفسك. لا تحتاج إلى تغطية أصوات الآخرين أو الاختفاء تحتها. ابحث عن إيقاع يحتضن صوتك الخاص؛ قد يصنع الاختلاف تناغمًا."},"16":{"zh-CN":"你刚刚经历了一段远征，也许是身体的奔波，也许是心里的拉扯，也许只是撑了太久，忘了怎么停下来。“定”不是永远不动，是卸下负重和恐惧，回归到令自己感到安全的位置。是你允许自己把这一段的路，走完，然后歇一歇。此刻，你无需再怕停下来就会落后、怕一松懈就前功尽弃、怕“定了”就是认输。这份怕，是你太习惯用“赶路”证明自己还在前进。\n\n回归安全的空间，不是为了困住你的手脚，是为了让你知道：任何不安的时刻，都有一个地方，你可以随时回来。你非无家可归的旅人，而是那个已经走完这一段、正在脱下鞋子的归人。你无需要消灭害怕，你只需要记得恐惧时候回家的路。当你准备好的时候，可以再去远征，也可以再次回来。定，是你给自己一个“抵达”的信号。","zh-TW":"你剛剛經歷了一段遠征，也許是身體的奔波，也許是心里的拉扯，也許只是撐了太久，忘了怎么停下來。“定”不是永遠不動，是卸下負重和恐懼，回歸到令自己感到安全的位置。是你允許自己把這一段的路，走完，然后歇一歇。此刻，你無需再怕停下來就會落后、怕一松懈就前功盡棄、怕“定了”就是認輸。這份怕，是你太習慣用“趕路”證明自己還在前進。\n\n回歸安全的空間，不是為了困住你的手腳，是為了讓你知道：任何不安的時刻，都有一個地方，你可以隨時回來。你非無家可歸的旅人，而是那個已經走完這一段、正在脫下鞋子的歸人。你無需要消滅害怕，你只需要記得恐懼時候回家的路。當你準備好的時候，可以再去遠征，也可以再次回來。定，是你給自己一個“抵達”的信號。","en":"You may have come through a long journey of effort, travel or inner strain. Settling is not giving up or refusing ever to move again. It is letting this stretch of road end and returning to somewhere that feels safe. Constant motion need not be your proof of progress. Remember a place you can return to when fear rises. You can rest, take off your shoes and leave again when ready. Arrival is something you may allow yourself.","ja":"長い移動や努力、心の葛藤を通ってきたのかもしれません。落ち着くことは、諦めることでも、もう二度と動かないことでもありません。この一区間を終え、安全を感じる場所へ戻ることです。進み続ける姿で、前進を証明しなくても大丈夫。不安なときに帰れる場所を思い出してください。靴を脱いで休み、準備ができたらまた出発できます。到着を、自分に許して。","th":"คุณอาจเพิ่งผ่านการเดินทางยาว ทั้งแรงกายหรือแรงใจ การหยุดตั้งหลักไม่ใช่ยอมแพ้หรือไม่ขยับอีก แต่คือให้เส้นทางช่วงนี้จบแล้วกลับไปที่ปลอดภัย ไม่ต้องเคลื่อนไหวตลอดเพื่อพิสูจน์ว่าก้าวหน้า จำที่ซึ่งกลับได้เมื่อกลัว คุณพัก ถอดรองเท้า แล้วออกเดินใหม่เมื่อพร้อมได้ อนุญาตให้ตัวเองรู้สึกว่าถึงแล้วบ้าง","ar":"ربما اجتزت رحلة طويلة من الجهد أو التنقل أو الشد الداخلي. الاستقرار ليس استسلامًا ولا وعدًا بألا تتحرك مجددًا؛ إنه السماح لهذا الجزء من الطريق أن ينتهي والعودة إلى الأمان. الحركة الدائمة ليست برهان التقدم. تذكّر مكانًا تعود إليه حين تخاف. اخلع حذاءك واسترح، ثم انطلق حين تستعد. اسمح لنفسك بالشعور بالوصول."},"17":{"zh-CN":"你习惯对别人好、习惯体谅，甚至习惯把最后一块糖也让出去。 “善”并非无底线的温柔、包容和给予，把自己放在最后。当被话语包裹在中间的时候，恰恰也是生活邀请你再反思自己的这份“善”的时刻。温和顺意，并不代表可以被无度地索取。善，是先护住自己的尖锐的角，再给出柔和的眼神。怕自己不够好、怕拒绝别人就被讨厌、怕“自私”这个词落在自己头上。这份怕，是你习惯了用“给出去”来证明自己值得。善，不是把自己掏空，而是你先把自己照顾好，再把有余的分出去。善良本身，也自带攻击力。没有活出攻击性的“好人”、“正确的人”是不完整的。你完全可以对恶意亮出自己的尖锐立场，而不用再背负愧疚。这不是要变成冷漠的人，你只需要知道：你的善意，首先应该流向你自己。吸气，我可以给。呼气，我也可以不给。善，是你允许自己做出任何的决定。","zh-TW":"你習慣對別人好、習慣體諒，甚至習慣把最后一塊糖也讓出去。 “善”并非無底線的溫柔、包容和給予，把自己放在最后。當被話語包裹在中間的時候，恰恰也是生活邀請你再反思自己的這份“善”的時刻。溫和順意，并不代表可以被無度地索取。善，是先護住自己的尖銳的角，再給出柔和的眼神。怕自己不夠好、怕拒絕別人就被討厭、怕“自私”這個詞落在自己頭上。這份怕，是你習慣了用“給出去”來證明自己值得。善，不是把自己掏空，而是你先把自己照顧好，再把有余的分出去。善良本身，也自帶攻擊力。沒有活出攻擊性的“好人”、“正確的人”是不完整的。你完全可以對惡意亮出自己的尖銳立場，而不用再背負愧疚。這不是要變成冷漠的人，你只需要知道：你的善意，首先應該流向你自己。吸氣，我可以給。呼氣，我也可以不給。善，是你允許自己做出任何的決定。","en":"Kindness need not mean giving away the last of yourself. Fear of disappointing others may have taught you to prove your worth through giving. Your goodwill deserves to reach you too. Care for yourself, share what you can, and let a boundary protect that generosity. You may stand firmly against unkindness without becoming cold. Both giving and choosing not to give can be honest decisions.","ja":"優しさは、自分を空っぽにすることではありません。嫌われる不安から、与えることで価値を証明してきたのかもしれません。善意は自分にも向けてよいのです。自分を整え、分けられるものを分ける。境界線があるからこそ、優しさを守れます。与えることも、与えない選択も、誠実であってよいのです。","th":"ความใจดีไม่ต้องแลกกับการให้จนตัวเองว่างเปล่า กลัวทำให้คนผิดหวังอาจทำให้เคยพิสูจน์คุณค่าด้วยการให้ ความหวังดีควรถึงตัวคุณด้วย ดูแลตัวเอง แบ่งส่วนที่แบ่งได้ และใช้ขอบเขตปกป้องความเอื้อเฟื้อ คุณยืนมั่นต่อความไม่ดีได้โดยไม่ต้องเย็นชา ทั้งให้และไม่ให้เป็นทางเลือกที่ซื่อตรงได้","ar":"اللطف لا يعني إفراغ نفسك. ربما اعتدت إثبات قيمتك بالعطاء خوفًا من خذلان الآخرين. تستحق أنت أيضًا حسن نيتك. اعتنِ بنفسك وشارك ما تستطيع، ودع الحدود تحمي كرمك. يمكنك مواجهة الإساءة بثبات دون برود؛ العطاء أو الامتناع عنه قد يكونان قرارين صادقين."},"18":{"zh-CN":"身边的人生活的动态，吸引走了你的一部分注意力，看着庆祝的时刻，并不能感同身受的喜悦，反而是一种若有所缺。众人所理解的“福”，或许是那些还没到手的东西——更多的财富、更好的身体、更顺的日子。而真正的福，比想到的小得多——有呼吸在，就是福。怕自己不够幸运、怕错过、怕这辈子就这样了。当看向了“还缺什么”的时刻，福的体验就消失了，当心里默默欣赏生命的最小律动——呼吸，福就在当下发生着。福，不是奋力要追上的终点，而是你停下来，发现自己还在呼吸，还能咽下一杯水，还可以感受到温度，在每天保有一定的选择权。一颗一直赶路的心，是记不起呼吸的。感到不幸福的时刻，先捧起一样东西，对自己说：正好。不批判追逐更多的动力，它是创造力的必要源泉，但也能够在尽兴体验获得的同时，看见并满足于自己的每一口呼吸。","zh-TW":"身邊的人生活的動態，吸引走了你的一部分注意力，看著慶祝的時刻，并不能感同身受的喜悅，反而是一種若有所缺。眾人所理解的“福”，或許是那些還沒到手的東西——更多的財富、更好的身體、更順的日子。而真正的福，比想到的小得多——有呼吸在，就是福。怕自己不夠幸運、怕錯過、怕這輩子就這樣了。當看向了“還缺什么”的時刻，福的體驗就消失了，當心里默默欣賞生命的最小律動——呼吸，福就在當下發生著。福，不是奮力要追上的終點，而是你停下來，發現自己還在呼吸，還能咽下一杯水，還可以感受到溫度，在每天保有一定的選擇權。一顆一直趕路的心，是記不起呼吸的。感到不幸福的時刻，先捧起一樣東西，對自己說：正好。不批判追逐更多的動力，它是創造力的必要源泉，但也能夠在盡興體驗獲得的同時，看見并滿足于自己的每一口呼吸。","en":"Watching others celebrate can make you notice only what seems missing. Yet a blessing may be as small as a breath, a sip of water or warmth you can still feel. Wanting more is not wrong, but it need not hide what is here. Pause and hold something ordinary. Let it be enough for this one moment. You can pursue a fuller life while also recognising the life already moving through you.","ja":"人の喜びを見ると、自分に足りないものばかり見えることがあります。でも幸せは、一呼吸、水を飲めること、感じられる温かさほど小さくてもよいのです。もっと望む気持ちを責めず、今あるものも見てください。身近な物を手に取り、この一瞬は「ちょうどよい」と思ってみる。願いと、今の命への感謝は共にあってよいのです。","th":"มองคนอื่นฉลองอาจทำให้เห็นแต่สิ่งที่ขาด แต่ความโชคดีอาจเล็กเท่าลมหายใจ น้ำหนึ่งอึก หรือความอุ่นที่ยังรู้สึกได้ อยากมีมากขึ้นไม่ผิด เพียงอย่าให้บดบังสิ่งตรงนี้ หยุดถือของธรรมดาสักชิ้นและให้มันพอสำหรับช่วงเวลานี้ คุณมุ่งสู่ชีวิตที่เต็มขึ้นพร้อมเห็นชีวิตที่กำลังอยู่ในตัวได้","ar":"قد تجعلك احتفالات الآخرين ترى ما ينقصك فقط. لكن النعمة قد تكون نفسًا أو جرعة ماء أو دفئًا تشعر به. الرغبة في المزيد ليست خطأ، لكنها لا تحتاج إلى إخفاء الموجود. توقف وأمسك شيئًا عاديًا، ودعه يكفي لهذه اللحظة. يمكنك السعي إلى حياة أغنى وتقدير الحياة الجارية فيك الآن."},"19":{"zh-CN":"“晋”是对当下阶段的确认，确认你已经处在自己心之所向的地图中。“晋”不需要再快一点、再强一点、再往上一点，也不是有了更高的位置、更多的资源、更大的发声，才算“进了”。当箭头射中靶心的时刻，不是宣扬征服，而是虚心扎根的开始。抵达，是为了用光照亮大地更多的万物，得以生长。只管大胆地释放你的所长，不被怕落后、怕不够、怕到了也没人看见这些内在声音的影响。一颗利益他人的心，不会被迟疑绊住脚。这份不确定的担心，恰恰说明了你的“抵达”是有意义的。晋，不是你占据了别人的机会，而是你抵达了之后，光照亮了一块地方，让别人也能看见路。是箭头，也是一颗种子。当它安稳的落地的时刻，周围的草才开始长。你不需要证明自己能力有多强，只管在这个阶段，不忘让光照得更远一点。","zh-TW":"“晉”是對當下階段的確認，確認你已經處在自己心之所向的地圖中。“晉”不需要再快一點、再強一點、再往上一點，也不是有了更高的位置、更多的資源、更大的發聲，才算“進了”。當箭頭射中靶心的時刻，不是宣揚征服，而是虛心扎根的開始。抵達，是為了用光照亮大地更多的萬物，得以生長。只管大膽地釋放你的所長，不被怕落后、怕不夠、怕到了也沒人看見這些內在聲音的影響。一顆利益他人的心，不會被遲疑絆住腳。這份不確定的擔心，恰恰說明了你的“抵達”是有意義的。晉，不是你占據了別人的機會，而是你抵達了之后，光照亮了一塊地方，讓別人也能看見路。是箭頭，也是一顆種子。當它安穩的落地的時刻，周圍的草才開始長。你不需要證明自己能力有多強，只管在這個階段，不忘讓光照得更遠一點。","en":"You may already be within the landscape you once hoped to reach. Advancement is not only a higher position or a louder voice. Arrival can be the beginning of putting down roots and letting your strengths benefit others. Like an arrow that lands and becomes a seed, what you bring can light a small part of the ground. You need not keep proving how capable you are. Let what you do help someone else see a path.","ja":"望んでいた場所に、もう立っているのかもしれません。進むことは、地位や声の大きさだけではありません。到着して根を下ろし、自分の力を誰かのために生かす始まりでもあります。地に着いた矢が種になるように、持ち味が周りを照らすことがあります。能力の証明を急がず、誰かが道を見つけるために光を分けてください。","th":"คุณอาจอยู่ในพื้นที่ที่เคยหวังจะไปถึงแล้ว ความก้าวหน้าไม่ได้มีแค่ตำแหน่งสูงหรือเสียงดังขึ้น การมาถึงอาจเป็นจุดเริ่มของการหยั่งรากและใช้จุดแข็งช่วยผู้อื่น เหมือนลูกศรตกลงแล้วกลายเป็นเมล็ด สิ่งที่คุณนำมาอาจส่องพื้นเล็ก ๆ ไม่ต้องพิสูจน์ความสามารถตลอด ให้สิ่งที่ทำช่วยใครเห็นทางได้บ้าง","ar":"قد تكون بالفعل في المشهد الذي تمنيت بلوغه. التقدم ليس منصبًا أعلى أو صوتًا أقوى فقط. الوصول بداية للتجذّر ونفع الآخرين بقدراتك. كسهم يستقر ويصبح بذرة، يمكن لما تقدمه أن يضيء بقعة من الأرض. لا تحتاج إلى إثبات الكفاءة باستمرار؛ دع عملك يساعد غيرك على رؤية الطريق."},"20":{"zh-CN":"时间不是让你老了，是让东西熟了。这个阶段，觉得累、觉得慢，让你更加地向往一种轻装上阵的状态。包袱是负重，也是让你爬得更高的补给。你无需丢掉更多的东西，只需对已有的进行重新排列，创造一个轻松的排序。失去必要的负重也限制了你的高度。没有白走的路，不用再害怕自己走太慢、怕别人已经到达而你还在半路、怕背了一路却发现是白费力气。允许事情在这一刻堆积、发酵，时间会将它酝酿成庆祝的美酒。时间，本身就是一味不可快进的调味剂，相信它会在你抵达高处之时，让味道更加香醇。","zh-TW":"時間不是讓你老了，是讓東西熟了。這個階段，覺得累、覺得慢，讓你更加地向往一種輕裝上陣的狀態。包袱是負重，也是讓你爬得更高的補給。你無需丟掉更多的東西，只需對已有的進行重新排列，創造一個輕松的排序。失去必要的負重也限制了你的高度。沒有白走的路，不用再害怕自己走太慢、怕別人已經到達而你還在半路、怕背了一路卻發現是白費力氣。允許事情在這一刻堆積、發酵，時間會將它醞釀成慶祝的美酒。時間，本身就是一味不可快進的調味劑，相信它會在你抵達高處之時，讓味道更加香醇。","en":"Time can ripen what effort alone cannot hurry. Feeling slow or burdened may make you wish to discard everything, yet some of what you carry also sustains you. Try arranging the load before judging it all useless. The road you have walked has not been wasted. Like something fermenting into a richer flavour, experience needs time that cannot be skipped. You may allow this stage to mature without racing someone else’s arrival.","ja":"時間は、努力だけでは急がせられないものを熟させます。重さや遅さを感じても、荷物のすべてが無駄とは限りません。支えになるものもあるはずです。まず持ち方や順番を整えてみてください。歩いた道は消えません。発酵が味を深めるように、経験にも飛ばせない時間があります。他人の到着と競わず、今の段階が熟す余地を。","th":"เวลาทำให้บางสิ่งสุกงอมในแบบที่ความพยายามเร่งไม่ได้ รู้สึกช้าหรือหนักอาจทำให้อยากทิ้งทุกอย่าง แต่ของบางอย่างที่แบกก็หล่อเลี้ยงคุณ ลองจัดน้ำหนักใหม่ก่อนตัดสินว่าไร้ประโยชน์ ทางที่เดินมาไม่สูญเปล่า เหมือนการหมักที่เพิ่มรส ประสบการณ์ต้องใช้เวลาซึ่งข้ามไม่ได้ อนุญาตให้ช่วงนี้เติบโตโดยไม่แข่งกับเวลาถึงของคนอื่น","ar":"يُنضج الوقت ما لا يعجّله الجهد وحده. قد يدفعك الثقل إلى رمي كل شيء، لكن بعض ما تحمل يسندك أيضًا. جرّب ترتيب الحمل قبل الحكم عليه بأنه بلا فائدة. الطريق لم يضع سدى. كالنكهة التي تنضج بالتخمّر، تحتاج الخبرة وقتًا لا يُختصر. دع هذه المرحلة تنضج دون سباق مع وصول الآخرين."},"21":{"zh-CN":"“财”并不意味着更多，而是意味着更少。它不是更多的数字、更多的资源或更多的底气，而是更少的不确定感，更少的欲望，更少的比较。财，不是你缺什么。是你还没认出，什么已经是你的了。怕不够、怕失去、怕别人有而你没有，这份怕，是你发现新视角的动力，同时，也是对你自身对“拥有”的安全感保护。不妨在这一刻暂停，清点一下：我已经有什么了？在日常被你以为是包袱的，可能是还没打开的宝藏。那双能做事的手，那颗能感受的心，那个能思考的脑袋，这些是你最先拥有的初始之“财”，只是太久没有被看到。","zh-TW":"“財”并不意味著更多，而是意味著更少。它不是更多的數字、更多的資源或更多的底氣，而是更少的不確定感，更少的欲望，更少的比較。財，不是你缺什么。是你還沒認出，什么已經是你的了。怕不夠、怕失去、怕別人有而你沒有，這份怕，是你發現新視角的動力，同時，也是對你自身對“擁有”的安全感保護。不妨在這一刻暫停，清點一下：我已經有什么了？在日常被你以為是包袱的，可能是還沒打開的寶藏。那雙能做事的手，那顆能感受的心，那個能思考的腦袋，這些是你最先擁有的初始之“財”，只是太久沒有被看到。","en":"Wealth can also mean less comparison and a little less uncertainty, rather than more numbers. Fear of not having enough may keep you from recognising what is already yours. Take a quiet inventory: hands that can act, a mind that can think, a heart that can feel. Something you call a burden may contain a resource not yet opened. This does not deny your needs; it gives your existing resources a place in the picture.","ja":"豊かさは数字の多さだけでなく、比較や不確かさが少し減ることでもあります。足りない不安から、すでにあるものを見落としているかもしれません。動く手、考える頭、感じる心を、静かに数えてみてください。重荷と呼ぶものにも、まだ開いていない力があることがあります。必要を否定せず、すでに持つ資源にも場所を与えて。","th":"ความมั่งคั่งอาจหมายถึงเปรียบเทียบน้อยลงและไม่แน่นอนน้อยลง ไม่ใช่ตัวเลขมากขึ้นอย่างเดียว กลัวไม่พออาจบังสิ่งที่เป็นของคุณแล้ว ลองนับเงียบ ๆ มือที่ลงมือได้ สมองที่คิดได้ ใจที่รู้สึกได้ สิ่งที่เรียกว่าภาระอาจมีทรัพยากรที่ยังไม่ได้เปิด นี่ไม่ใช่ปฏิเสธความต้องการ แต่ให้สิ่งที่มีอยู่มีที่ในภาพด้วย","ar":"قد تعني الثروة مقارنة أقل وعدم يقين أقل، لا أرقامًا أكبر فقط. الخوف من النقص قد يحجب ما تملكه بالفعل. راجع بهدوء: يدان تعملان، وعقل يفكر، وقلب يشعر. ما تسميه عبئًا قد يخفي موردًا لم تفتحه. لا ينفي ذلك احتياجاتك؛ إنه يمنح مواردك الحالية مكانًا في الصورة."},"22":{"zh-CN":"事情不会因为你的期待，而改写它自身的出现方式。“事”意味着还未完成的过程，仍需亲手接过来，躬身参与。事太多、太杂的时候，令人想逃、心生烦乱。有事可做，是还在场上的最好说明。怕做不完、怕做不好、怕做了也没人看见，这样的顾虑是你对“做成”这件事的动力。事，不是扛着一份重量前行，它是你参与这个世界的一种方式。如果手里还握着权杖，事再小，也需置身其中。而你始终拥有着开口影响事情走向的权利。驾驭事情，而不被事所奴役。","zh-TW":"事情不會因為你的期待，而改寫它自身的出現方式。“事”意味著還未完成的過程，仍需親手接過來，躬身參與。事太多、太雜的時候，令人想逃、心生煩亂。有事可做，是還在場上的最好說明。怕做不完、怕做不好、怕做了也沒人看見，這樣的顧慮是你對“做成”這件事的動力。事，不是扛著一份重量前行，它是你參與這個世界的一種方式。如果手里還握著權杖，事再小，也需置身其中。而你始終擁有著開口影響事情走向的權利。駕馭事情，而不被事所奴役。","en":"An unfinished matter still asks for participation, even when it refuses to unfold as expected. Too many tasks can stir a wish to escape. Caring about doing them well is not a fault, but you need not be ruled by that worry. A task can be a way of taking part in the world rather than a weight that defines you. Pick up what is yours to do, and remember that your voice can influence how it proceeds.","ja":"途中の物事は、期待どおりでなくても参加を求めています。多すぎる仕事から逃げたくなることもあるでしょう。よくやりたい気持ちは大切ですが、不安に支配されなくても大丈夫。仕事は自分を決める重荷ではなく、世界に関わる一つの方法です。自分が担う部分を引き受け、進め方について声を出せることも忘れないでください。","th":"เรื่องที่ยังไม่เสร็จยังต้องการให้คุณมีส่วน แม้มันไม่เป็นตามคาด งานมากทำให้อยากหนีได้ ใส่ใจว่าจะทำให้ดีไม่ใช่ความผิด แต่ไม่ต้องถูกความกังวลปกครอง งานอาจเป็นวิธีมีส่วนในโลกแทนน้ำหนักที่นิยามคุณ รับส่วนที่เป็นของคุณ และจำว่าเสียงของคุณมีผลต่อวิธีเดินหน้าของเรื่องนั้น","ar":"الأمر غير المكتمل يحتاج مشاركتك، حتى إن لم يجرِ كما توقعت. كثرة المهام قد تثير الرغبة في الهرب. اهتمامك بإتقانها ليس عيبًا، لكن القلق لا ينبغي أن يحكمك. قد تكون المهمة طريقة للمشاركة في العالم لا وزنًا يعرّفك. تولَّ ما يخصك، وتذكّر أن صوتك يستطيع التأثير في سير الأمور."},"23":{"zh-CN":"“好”，让人在“关系”里不自觉地用力过度。你爱一个人，就想替他做、替他选、替他避开所有坑。希望一件事情“好”的时候，会力挽狂澜耗尽力气。“好”结果并非是控制、是焦心，也不是“我为你付出了这么多”。 怕受伤、怕走歪、怕不被需要，一颗害怕失控的心，停不下来控制、纠正和催促。“好”，只会发生在有一定自由度的留白之间，而不在窒息的距离里。就像播种了一粒种子，看不见长势的时候，怀疑好与不好，帮它提前破土或把他捏成想要的样子，而是你蹲下来，看它长成它自己的样子。保留一段守望的距离，不是冷漠无视，而是，不干预它自由跳舞的光。、","zh-TW":"“好”，讓人在“關系”里不自覺地用力過度。你愛一個人，就想替他做、替他選、替他避開所有坑。希望一件事情“好”的時候，會力挽狂瀾耗盡力氣。“好”結果并非是控制、是焦心，也不是“我為你付出了這么多”。 怕受傷、怕走歪、怕不被需要，一顆害怕失控的心，停不下來控制、糾正和催促。“好”，只會發生在有一定自由度的留白之間，而不在窒息的距離里。就像播種了一粒種子，看不見長勢的時候，懷疑好與不好，幫它提前破土或把他捏成想要的樣子，而是你蹲下來，看它長成它自己的樣子。保留一段守望的距離，不是冷漠無視，而是，不干預它自由跳舞的光。、","en":"Wanting the best for someone can slide into choosing, correcting and controlling for them. A good outcome also needs room to grow freely. Imagine watching a seed rather than pulling it up to check its progress or shaping it into what you wanted. Keeping a caring distance is not indifference. You can remain attentive without blocking another life’s movement. Love does not have to prove itself through constant intervention.","ja":"相手のためを思ううちに、選び、直し、管理しすぎることがあります。よい結果にも、自由に育つ余白が必要です。芽を確かめようと種を引き上げず、望む形に押し込まず、育つ様子を見守るように。思いやりある距離は、無関心ではありません。相手の動きを遮らず、気にかけていることはできます。愛を、絶え間ない介入で証明しなくてもよいのです。","th":"อยากให้อีกคนได้ดีอาจกลายเป็นเลือก แก้ และควบคุมแทนเขา ผลที่ดีก็ต้องมีพื้นที่เติบโต ลองมองเมล็ดโดยไม่ดึงขึ้นเช็กหรือบีบให้เป็นรูปร่างที่ต้องการ ระยะห่างที่ใส่ใจไม่ใช่ความเฉยชา คุณสนใจได้โดยไม่ขวางการเคลื่อนไหวของอีกชีวิต ความรักไม่ต้องพิสูจน์ด้วยการเข้าไปจัดการตลอด","ar":"قد تتحول الرغبة في الخير للآخر إلى اختيار وتصحيح وتحكّم نيابة عنه. النتيجة الجيدة تحتاج حرية للنمو. راقب البذرة بدل اقتلاعها لفحصها أو إجبارها على شكلك المفضّل. المسافة المهتمة ليست لامبالاة. تستطيع الانتباه دون تعطيل حركة حياة أخرى؛ الحب لا يحتاج تدخلًا دائمًا لإثباته."},"24":{"zh-CN":"你有多久没有体会到快乐了？觉得生活是灰色的，笑是给别人的，安静下来只有累。 “乐”并不是外面的事——好天气、好运气、好的人或好的事。快乐，是可以自己创造的。就像木架上的琴弦，你不拨动，它便不会发出声响。怕快乐再也不会回来，怕太短暂、怕笑了又会哭、怕和自己无关。“乐”是你主动碰了世界一下，世界弹回来一个声音。你不是没有快乐的琴，你是太久没有伸手拨它了。","zh-TW":"你有多久沒有體會到快樂了？覺得生活是灰色的，笑是給別人的，安靜下來只有累。 “樂”并不是外面的事——好天氣、好運氣、好的人或好的事。快樂，是可以自己創造的。就像木架上的琴弦，你不撥動，它便不會發出聲響。怕快樂再也不會回來，怕太短暫、怕笑了又會哭、怕和自己無關。“樂”是你主動碰了世界一下，世界彈回來一個聲音。你不是沒有快樂的琴，你是太久沒有伸手撥它了。","en":"If life has felt grey, joy may seem to belong only to good circumstances outside you. Yet a string does not sound until it is gently touched. Joy can begin with a small contact you make with the world, not a guarantee that sadness will never return. You need not demand a lasting happiness before trying a playful gesture. The instrument may still be here, waiting for your hand.","ja":"暮らしが灰色に感じられると、喜びは外のよい出来事にしかないように思えます。でも弦は、触れられて初めて鳴ります。喜びは、悲しみが二度と来ない保証ではなく、自分から世界へ小さく触れることでも始まります。ずっと続く幸せを確かめてからでなくて大丈夫。楽器はまだここにあり、あなたの手を待っているのかもしれません。","th":"ถ้าชีวิตดูหม่น ความสุขอาจเหมือนขึ้นกับเรื่องดีภายนอกเท่านั้น แต่สายดนตรีไม่ดังจนมีมือแตะ ความสุขเริ่มจากการสัมผัสโลกเล็ก ๆ ที่คุณเลือกได้ ไม่ใช่คำรับประกันว่าจะไม่เศร้าอีก ไม่ต้องรอความสุขถาวรก่อนลองทำสิ่งสนุก เครื่องดนตรีอาจยังอยู่ตรงนี้ รอมือของคุณ","ar":"إذا بدت الحياة رمادية، قد تظن أن الفرح رهين ظروف خارجية جيدة. لكن الوتر لا يصدر صوتًا حتى تلمسه. قد يبدأ الفرح بلمسة صغيرة منك للعالم، لا بضمان غياب الحزن إلى الأبد. لا تشترط سعادة دائمة قبل تجربة حركة مرحة. ربما ما زالت الآلة هنا تنتظر يدك."},"25":{"zh-CN":"你是否在这个阶段最不敢停？觉得一停下来就会被追上、被落下、被忘记。“止”让人想到停滞，是妥协、是半途而废、是不如别人。而一只脚掌踩实地面的时刻，不是逃跑的影子，不是跨步的激越，是胸有成竹的一种稳。止，不是结束。是你决定：我先把身体停在这，等一等心灵。怕停了就再也跑不动、怕别人超过你、怕这一停就再也无法启动。你无需用“不停”来证明自己还在前进。与其慌慌张张赶路，不如选择把当下这一步踩实，创造一个停顿的视角，再抬起下一步落在更加接近你所想要的位置。路并不会因为你的暂停而消失，反而会增添更多的选项。暂停，并非半途而废，而是蓄积力量，再次从半途有力出发。","zh-TW":"你是否在這個階段最不敢停？覺得一停下來就會被追上、被落下、被忘記。“止”讓人想到停滯，是妥協、是半途而廢、是不如別人。而一只腳掌踩實地面的時刻，不是逃跑的影子，不是跨步的激越，是胸有成竹的一種穩。止，不是結束。是你決定：我先把身體停在這，等一等心靈。怕停了就再也跑不動、怕別人超過你、怕這一停就再也無法啟動。你無需用“不停”來證明自己還在前進。與其慌慌張張趕路，不如選擇把當下這一步踩實，創造一個停頓的視角，再抬起下一步落在更加接近你所想要的位置。路并不會因為你的暫停而消失，反而會增添更多的選項。暫停，并非半途而廢，而是蓄積力量，再次從半途有力出發。","en":"A firmly planted foot is not a sign of defeat. You can stop your body for a moment and let your heart catch up. Fear of falling behind may have made constant movement feel compulsory, but the road does not disappear when you pause. Ground this step before choosing the next. A pause can reveal options you miss while rushing and help you begin again with more steadiness.","ja":"地面をしっかり踏む足は、敗北のしるしではありません。体を少し止めて、心が追いつくのを待ってよいのです。遅れる不安から動き続けても、休んだから道がなくなるわけではありません。今の一歩を確かめてから、次を選ぶ。急いで見落とす選択肢が見え、より確かな足取りで再び始められることがあります。","th":"เท้าที่เหยียบพื้นมั่นคงไม่ใช่ความพ่ายแพ้ คุณหยุดร่างกายสักครู่ให้ใจตามทันได้ กลัวตามไม่ทันอาจทำให้รู้สึกว่าต้องเคลื่อนไหวตลอด แต่ทางไม่หายเมื่อคุณพัก ลงน้ำหนักก้าวนี้ก่อนเลือกก้าวต่อ การหยุดอาจเปิดทางเลือกที่มองไม่เห็นตอนรีบ และช่วยให้เริ่มใหม่อย่างมั่นคง","ar":"القدم الثابتة على الأرض ليست هزيمة. يمكنك إيقاف الجسد لحظة كي يلحق به قلبك. ربما جعل الخوف من التأخر الحركة إلزامية، لكن الطريق لا يختفي حين تتوقف. ثبّت هذه الخطوة قبل اختيار التالية. قد تكشف الوقفة خيارات غابت أثناء العجلة وتعينك على انطلاقة أهدأ."},"26":{"zh-CN":"你是否忙到不敢休息，觉得停下来就是滞后、就是无用、就是愧对那些还在跑的人。 “休”并非结束、后退、认输、无用，是你成全身心的诉求，选择先靠一会儿，整理之后再继续。你无需硬撑着去到达某个节点，不用担心外界的评价，也不用担心倚靠会成为依赖。一颗随时转动的心，看不见满满日程之外的风景。休，不是对自我的否定，而是友善地成全真实的自我需要，不要等倒下了再寻求被接住。对自己诚实，允许慢下来，才是远行的智者。","zh-TW":"你是否忙到不敢休息，覺得停下來就是滯后、就是無用、就是愧對那些還在跑的人。 “休”并非結束、后退、認輸、無用，是你成全身心的訴求，選擇先靠一會兒，整理之后再繼續。你無需硬撐著去到達某個節點，不用擔心外界的評價，也不用擔心倚靠會成為依賴。一顆隨時轉動的心，看不見滿滿日程之外的風景。休，不是對自我的否定，而是友善地成全真實的自我需要，不要等倒下了再尋求被接住。對自己誠實，允許慢下來，才是遠行的智者。","en":"Have you been so busy that resting feels like falling behind, being useless or letting down those still running? Rest is not an ending, retreat or defeat. It is an answer to the needs of body and mind: lean for a moment, gather yourself, then continue. You do not have to force yourself to a milestone or earn permission through exhaustion. Accepting support need not mean dependence. A mind that never stops can miss life beyond a full schedule. Rest is a kind response to your real needs, not a rejection of yourself. You do not need to collapse before being held. Be honest with yourself and allow a slower pace.","ja":"忙しすぎて、休むことが遅れや無価値、走り続ける人への申し訳なさに感じられていませんか。休息は終わりでも、後退でも、敗北でもありません。心と体の願いを受けとめ、少し身を預け、整えてからまた進むことです。無理に節目まで耐えたり、疲れ切ってから許可を得たりする必要はありません。支えを受けることは、必ずしも依存ではありません。動き続ける心には、予定の外の景色が見えにくくなります。休むことは自分の否定ではなく、本当の必要への優しい応えです。倒れるまで待たず、自分に正直に、ゆっくり進むことを許してください。","th":"คุณยุ่งจนการพักเหมือนตามหลัง ไร้ประโยชน์ หรือผิดต่อคนที่ยังวิ่งอยู่ไหม การพักไม่ใช่จุดจบ การถอย หรือยอมแพ้ แต่เป็นการตอบรับความต้องการของกายใจ เอนพิงสักครู่ รวบรวมตัวเอง แล้วค่อยไปต่อ ไม่ต้องฝืนถึงหลักชัยหรือเหนื่อยจนหมดแรงก่อนจึงจะพักได้ รับการรองรับไม่ได้แปลว่าต้องพึ่งพาตลอด ใจที่หมุนไม่หยุดอาจมองไม่เห็นชีวิตนอกตารางแน่น ๆ การพักคือความอ่อนโยนต่อความต้องการจริง ไม่ใช่ปฏิเสธตัวเอง ไม่ต้องรอล้มก่อนจึงให้ใครรองรับ ซื่อตรงกับตัวเองและอนุญาตให้ช้าลง","ar":"هل انشغلت حتى صار الاستراحة تبدو تأخرًا أو عجزًا أو خذلانًا لمن يواصلون الركض؟ الراحة ليست نهاية ولا تراجعًا ولا هزيمة. إنها استجابة لحاجة الجسد والعقل: استند قليلًا، واجمع نفسك، ثم تابع. لا يلزم أن تجبر نفسك على بلوغ محطة أو أن تنهك لتستحق الراحة. قبول السند لا يعني الاعتماد الدائم. الذهن الذي لا يتوقف قد يفوته ما وراء الجدول المزدحم. الراحة لطف بحاجاتك الحقيقية، لا رفض لنفسك. لا تنتظر الانهيار كي تتلقى الدعم؛ كن صادقًا مع نفسك واسمح بإيقاع أبطأ."},"27":{"zh-CN":"走了这么久，你或许依然觉得还没到——目标还不够、成果还不够、自己还不够好。误以为“至”是终点线、是高光、是别人说“你做到了”。怕偏离了自己的初心，怕实现不了渴望的画面，怕成为不了理想中的状态，怕这只是一次偶然的运气。一颗一支在飞向目标的心，难免会忽视了飞的过程，你无需再用“还没到”来鞭策自己。至，不是你终于站在了庆贺的画面里，是你停下来，认出：我已经在这里了。\n\n你不是没有抵达。你是太久没有允许自己对此时的靶心满意，正在做着这件事，就在这里，我已经“在了”。","zh-TW":"走了這么久，你或許依然覺得還沒到——目標還不夠、成果還不夠、自己還不夠好。誤以為“至”是終點線、是高光、是別人說“你做到了”。怕偏離了自己的初心，怕實現不了渴望的畫面，怕成為不了理想中的狀態，怕這只是一次偶然的運氣。一顆一支在飛向目標的心，難免會忽視了飛的過程，你無需再用“還沒到”來鞭策自己。至，不是你終于站在了慶賀的畫面里，是你停下來，認出：我已經在這里了。\n\n你不是沒有抵達。你是太久沒有允許自己對此時的靶心滿意，正在做著這件事，就在這里，我已經“在了”。","en":"You may keep telling yourself you have not arrived because the goal, achievement or person you hoped to become still seems distant. Arrival need not be a public celebration or someone else’s approval. Pause and recognise where you already stand. The time spent moving matters too. You can acknowledge “I am here” without giving up further hopes. This moment can be a real point of arrival rather than another reason to demand more from yourself.","ja":"目標や成果、理想の自分がまだ遠く、「まだ着いていない」と言い続けているのかもしれません。到着は、人前の祝福や他人の承認だけではありません。今立つ場所を、少し止まって認めてください。進んできた時間にも意味があります。さらなる願いを捨てずに、「私はここにいる」と言ってよいのです。今を、もっと求める理由だけにしなくて大丈夫。","th":"คุณอาจบอกตัวเองว่ายังไม่ถึง เพราะเป้าหมาย ผลงาน หรือตัวตนที่หวังยังไกล การถึงไม่จำเป็นต้องมีคนฉลองหรืออนุมัติ หยุดรับรู้ที่ที่ยืนอยู่แล้ว เวลาระหว่างเดินก็มีค่า คุณยอมรับว่า “ฉันอยู่ตรงนี้” ได้โดยไม่ทิ้งความหวังต่อไป ช่วงนี้เป็นการมาถึงจริงได้ ไม่ใช่แค่เหตุผลให้เรียกร้องตัวเองเพิ่ม","ar":"قد تقول إنك لم تصل لأن الهدف أو الإنجاز أو صورتك المنشودة ما زالت بعيدة. الوصول لا يشترط احتفالًا أو موافقة الآخرين. توقف واعترف بالمكان الذي تقف فيه بالفعل. لوقت المسير قيمة أيضًا. يمكنك قول «أنا هنا» دون ترك آمالك التالية؛ هذه اللحظة قد تكون وصولًا حقيقيًا لا مطالبة جديدة بالمزيد."},"28":{"zh-CN":"效率的最大的阻碍并非迟滞，而是跑偏。明明很努力了，结果却总差一点，明明瞄准了，却也会分心偏离。“效”有时是某个阶段的结果、是成绩、是别人眼里的“有用”，也可以是在行动的过程中，提醒自己再次对焦。效，不是你一次就做对。是你愿意在途中，柔和且不苛责地拨自己一下。不用担心调整太慢来不及，怕自己不是“天生就会”的那种人。没有次次都完美中靶的出发。效，不是不偏，是允许偏离之后，你还愿意拨了回正。不需要重头再来，不需要否定之前的路。只是给自己发出一个柔和的邀请，重心再次回来。","zh-TW":"效率的最大的阻礙并非遲滯，而是跑偏。明明很努力了，結果卻總差一點，明明瞄準了，卻也會分心偏離。“效”有時是某個階段的結果、是成績、是別人眼里的“有用”，也可以是在行動的過程中，提醒自己再次對焦。效，不是你一次就做對。是你愿意在途中，柔和且不苛責地撥自己一下。不用擔心調整太慢來不及，怕自己不是“天生就會”的那種人。沒有次次都完美中靶的出發。效，不是不偏，是允許偏離之后，你還愿意撥了回正。不需要重頭再來，不需要否定之前的路。只是給自己發出一個柔和的邀請，重心再次回來。","en":"Sometimes effort misses its direction rather than lacking strength. Effectiveness can be a gentle act of refocusing on the way, not proof that you got everything right at once. Drifting does not cancel the road already travelled. You can notice it and adjust without beginning your whole life again. Let correction be an invitation to return to your centre instead of a verdict against yourself.","ja":"力が足りないより、方向が少しずれていることがあります。成果につながる動きは、一度で正しくできる証明ではなく、途中で優しく焦点を戻すことでもあります。ずれたからといって、歩いた道は無効になりません。すべてを最初からやり直さず、気づいて調整してよいのです。修正を、自分への判決ではなく、中心へ戻る招待にしてください。","th":"บางครั้งความพยายามไม่ได้ขาดแรง แต่คลาดทิศทาง ประสิทธิผลอาจเป็นการค่อย ๆ ปรับโฟกัสระหว่างทาง ไม่ใช่ทำถูกทั้งหมดครั้งเดียว การหลุดทางไม่ได้ลบเส้นทางที่ผ่านมา คุณเห็นแล้วปรับได้โดยไม่เริ่มชีวิตใหม่ทั้งหมด ให้การแก้ไขเป็นคำชวนกลับสู่แกนตัวเอง ไม่ใช่คำตัดสิน","ar":"أحيانًا يضل الجهد اتجاهه لا قوته. قد تكون الفاعلية إعادة تركيز لطيفة أثناء الطريق، لا إثباتًا لصواب كل شيء من البداية. الانحراف لا يلغي ما قطعته. لاحظه وعدّل دون إعادة حياتك من الصفر. اجعل التصحيح دعوة إلى العودة لمركزك، لا حكمًا ضد نفسك."},"29":{"zh-CN":"本条原始资料中字名与正文存在差异，深入解读仍待核对。","zh-TW":"本條原始資料中字名與正文存在差異，深入解讀仍待核對。","en":"The character name and interpretation in the supplied source do not agree. A deeper reading will be added after the source has been checked.","ja":"提供資料では、文字名と本文の内容が一致していません。詳しい解釈は、資料の確認後に掲載します。","th":"ชื่ออักษรกับเนื้อหาในเอกสารต้นฉบับไม่ตรงกัน จะเพิ่มคำอธิบายเชิงลึกหลังตรวจสอบแหล่งข้อมูลแล้ว","ar":"لا يتطابق اسم الحرف مع تفسيره في المصدر المقدّم. سيُضاف التأمل المفصّل بعد التحقق من المصدر."},"30":{"zh-CN":"催促你拼命往前的声音，往往来自“不够”，在这个声音下，你看不见本来富饶的自己。觉得账户不够、积累不够、底气不够，“富”并不是更多的数字、更快的回报、更满的存量，而是一次满意的封存。封坛，静等，才是富的开始。怕攒得慢、怕别人比你快、怕打开时已经坏了。这份怕，是对“马上能喝”的结果期待。请带着不评判的友善去看见自己的这份着急。富，不是你拥有了多少，而是你愿意在某个恰到好处的节点，主动地封起来，耐心等待，不急打开。封存，不是不见了，只是它在那里，悄悄与时间同行后自然地让你闻到另一种喜悦的醇香。处在封坛的阶段，不妨用耐心成全一份延迟满足，看看它会传递给你什么样的发现。","zh-TW":"催促你拼命往前的聲音，往往來自“不夠”，在這個聲音下，你看不見本來富饒的自己。覺得賬戶不夠、積累不夠、底氣不夠，“富”并不是更多的數字、更快的回報、更滿的存量，而是一次滿意的封存。封壇，靜等，才是富的開始。怕攢得慢、怕別人比你快、怕打開時已經壞了。這份怕，是對“馬上能喝”的結果期待。請帶著不評判的友善去看見自己的這份著急。富，不是你擁有了多少，而是你愿意在某個恰到好處的節點，主動地封起來，耐心等待，不急打開。封存，不是不見了，只是它在那里，悄悄與時間同行后自然地讓你聞到另一種喜悅的醇香。處在封壇的階段，不妨用耐心成全一份延遲滿足，看看它會傳遞給你什么樣的發現。","en":"The voice saying “not enough” can hide what has already accumulated. Abundance is sometimes the choice to seal the jar and let time work, rather than demand an immediate return. Waiting does not mean your effort has vanished. Notice your impatience without condemning it, and allow something worthwhile to mature. This stage may offer the quieter discovery of what patient care can become.","ja":"「足りない」という声で、蓄えてきたものが見えなくなることがあります。豊かさは、すぐに成果を求めるより、壺を封じて時間に任せる選択でもあります。待つことは、努力が消えたことではありません。焦りを責めずに認め、大切なものが熟すのを許して。丁寧に待つことでしか見つからない味わいがあるかもしれません。","th":"เสียงว่า “ยังไม่พอ” อาจบังสิ่งที่สะสมมา ความมั่งคั่งบางครั้งคือเลือกปิดไหแล้วให้เวลาทำงาน แทนเรียกผลทันที การรอไม่ได้แปลว่าความพยายามหายไป รับรู้ความใจร้อนโดยไม่ตำหนิ แล้วให้สิ่งมีค่าค่อย ๆ สุกงอม ช่วงนี้อาจพาไปพบสิ่งที่การดูแลอย่างอดทนสร้างขึ้น","ar":"صوت «ليس كافيًا» قد يخفي ما تراكم بالفعل. الوفرة أحيانًا قرار بإغلاق الوعاء وترك الوقت يعمل بدل طلب عائد فوري. الانتظار لا يعني اختفاء جهدك. لاحظ استعجالك بلا إدانة، ودع ما يستحق ينضج. قد تكشف هذه المرحلة بهدوء ما تصنعه الرعاية الصبورة."},"31":{"zh-CN":"你已经足够美了。你无需再追求瘦一点、白一点、年轻一点、更像谁一点。“美”并无统一的标准，模板下生长的是依赖于外界的审美评价体系，识别不出来独特的初始的美，那份未被修改的自然之美。美，不是符合标准。担心自己不够好看、怕被人比下去、怕不符合“那个样子”，是提醒你在用外部的标准审视自己。美的心灵，是自由的。不执着于追求长成什么样子，而是停下来发自内心的认可：嗯，这样也行。你不需要变成别人的审美。美，是你允许自己那些格格不入的独特性，成为自己的标准。","zh-TW":"你已經足夠美了。你無需再追求瘦一點、白一點、年輕一點、更像誰一點。“美”并無統一的標準，模板下生長的是依賴于外界的審美評價體系，識別不出來獨特的初始的美，那份未被修改的自然之美。美，不是符合標準。擔心自己不夠好看、怕被人比下去、怕不符合“那個樣子”，是提醒你在用外部的標準審視自己。美的心靈，是自由的。不執著于追求長成什么樣子，而是停下來發自內心的認可：嗯，這樣也行。你不需要變成別人的審美。美，是你允許自己那些格格不入的獨特性，成為自己的標準。","en":"Beauty does not require you to become thinner, younger or more like someone else. A borrowed standard can make your unedited particularity hard to see. The worry that you do not look right may be a reminder to question whose eyes you are using. Pause and consider allowing your own form to count. Your differences need not be corrected before you can meet yourself with appreciation.","ja":"美しさのために、もっと細く、若く、誰かに似る必要はありません。借りた基準では、手を加えていない自分らしさが見えにくくなります。見た目への不安があるなら、誰の目で見ているのか問い直してみてください。自分の姿を、自分の基準に含めてよいのです。違いを直してからでなくても、自分を認めることはできます。","th":"ความงามไม่ต้องทำให้ผอมลง อ่อนวัยลง หรือเหมือนคนอื่น มาตรฐานที่ยืมมาอาจทำให้มองไม่เห็นความเฉพาะตัวที่ยังไม่ถูกแก้ กลัวดูไม่ดีอาจเตือนให้ถามว่ากำลังมองผ่านตาของใคร หยุดแล้วลองให้รูปร่างของตัวเองนับเป็นความงามได้ ความต่างไม่ต้องถูกแก้ก่อนจึงจะชื่นชมตัวเอง","ar":"الجمال لا يفرض نحافة أو شبابًا أكثر أو تشبّهًا بآخر. قد يحجب معيار مستعار خصوصيتك الطبيعية. القلق بشأن المظهر قد يذكّرك بالسؤال: بعيني من تنظر؟ توقف واسمح لشكلك الخاص بأن يكون معتبرًا. لا يلزم تصحيح اختلافاتك قبل أن تقابل نفسك بالتقدير."},"32":{"zh-CN":"你或许在担心自己给得不够多、爱得不够好。你以为要更温柔、更包容、更无私，才配得上“慈”这个字。可心下面没有条件——不是你做对了才爱你，不是你回报了才继续给。心稳稳地在那里接住所有关系，就是在爱着。怕爱错了人、怕被辜负、怕付出没有回音，这份担心，不是你的错，是在提醒爱不需要用“交换”来衡量。慈，不是一段满分的关系。而是看得见六十分关系中的难处，和对方的局限性，并愿意把心放在那里承接，允许一切如其所是。不增强，不削弱，不试图解决完所有问题，仅仅只是看见，并放下评判与之自然共处。关系里，你可以不完美。你可以累、可以退、可以暂时不爱。但心还在。那颗心不因为做错了就收回，不因为没有回报就关闭。无条件的爱，不是你必须一直给，而是你不在和对方不如意的呈现对抗，而是你开始接纳了人的局限性，并心怀祝福各自成长。","zh-TW":"你或許在擔心自己給得不夠多、愛得不夠好。你以為要更溫柔、更包容、更無私，才配得上“慈”這個字。可心下面沒有條件——不是你做對了才愛你，不是你回報了才繼續給。心穩穩地在那里接住所有關系，就是在愛著。怕愛錯了人、怕被辜負、怕付出沒有回音，這份擔心，不是你的錯，是在提醒愛不需要用“交換”來衡量。慈，不是一段滿分的關系。而是看得見六十分關系中的難處，和對方的局限性，并愿意把心放在那里承接，允許一切如其所是。不增強，不削弱，不試圖解決完所有問題，僅僅只是看見，并放下評判與之自然共處。關系里，你可以不完美。你可以累、可以退、可以暫時不愛。但心還在。那顆心不因為做錯了就收回，不因為沒有回報就關閉。無條件的愛，不是你必須一直給，而是你不在和對方不如意的呈現對抗，而是你開始接納了人的局限性，并心懷祝福各自成長。","en":"Compassion is not a perfect relationship or an obligation to give endlessly. You can see another person’s limitations without making every difficulty a judgment. Love need not be measured only as an exchange. You are allowed to be tired, step back and remain imperfect. A caring heart can recognise limits, release the demand to solve everything, and wish each person room to grow. Acceptance does not require fighting every disappointment or abandoning yourself.","ja":"慈しみは、満点の関係でも、与え続ける義務でもありません。相手の限界を見つめ、難しさをすべて評価に変えずにいること。愛を交換だけで測らなくてもよいのです。疲れたり、退いたり、不完全でいたりして大丈夫。すべてを解決する要求を緩め、それぞれの成長を願うこともできます。受け入れることは、自分を捨てることではありません。","th":"เมตตาไม่ใช่ความสัมพันธ์เต็มร้อยหรือหน้าที่ให้ไม่สิ้นสุด คุณมองข้อจำกัดของอีกคนได้โดยไม่ตัดสินทุกปัญหา ความรักไม่ต้องวัดเป็นการแลกเปลี่ยนเท่านั้น คุณเหนื่อย ถอย และไม่สมบูรณ์ได้ ใจที่ดูแลกันรับรู้ขอบเขต ปล่อยข้อเรียกร้องว่าต้องแก้ทุกอย่าง และอวยพรให้แต่ละคนเติบโต การยอมรับไม่ต้องทิ้งตัวเอง","ar":"الرحمة ليست علاقة مثالية أو واجب عطاء بلا نهاية. يمكنك رؤية حدود الآخر دون تحويل كل صعوبة إلى حكم. لا يُقاس الحب بالمبادلة وحدها. يُسمح لك بالتعب والتراجع وعدم الكمال. يستطيع القلب المهتم إدراك الحدود وترك مطلب حل كل شيء وتمنّي النمو للجميع. القبول لا يستلزم التخلي عن نفسك."},"33":{"zh-CN":"外界的展现，牵动着你对自身进展的期待，你或许在责怪自己“不够能”——为什么别人可以那么快出成果，你却迟迟未能如意。这这样的状态，只是提醒你选择了外界在对标，而这个阶段对你更有帮助的对标，是完成对内心的储能。“能”不是一直源源不断地输出、永远在状态、从不失手的成果。能，也可以有收的节奏。猛兽不会一直进攻，而是在不同的季节找到自己的轻重缓急。不用担心你的能力发挥不出来，不被看见或认可，也无需用“冲”证明自己的价值。不是你每一下都全力以赴，是你知道，哪一段时刻值得用全力。你是最了解自己的人，缓缓展现，将成果放大到更大的岁月长河，你依然有足够的时间。","zh-TW":"外界的展現，牽動著你對自身進展的期待，你或許在責怪自己“不夠能”——為什么別人可以那么快出成果，你卻遲遲未能如意。這這樣的狀態，只是提醒你選擇了外界在對標，而這個階段對你更有幫助的對標，是完成對內心的儲能。“能”不是一直源源不斷地輸出、永遠在狀態、從不失手的成果。能，也可以有收的節奏。猛獸不會一直進攻，而是在不同的季節找到自己的輕重緩急。不用擔心你的能力發揮不出來，不被看見或認可，也無需用“沖”證明自己的價值。不是你每一下都全力以赴，是你知道，哪一段時刻值得用全力。你是最了解自己的人，緩緩展現，將成果放大到更大的歲月長河，你依然有足夠的時間。","en":"Capability is not an endless stream of output. Comparing your pace with others can hide the need to replenish your own reserves. Even a powerful animal does not attack in every season. You can decide when to conserve energy and when a moment deserves your full strength. A quieter period does not erase your ability. Give your contribution a longer horizon, and let it emerge at a pace that belongs to you.","ja":"力は、出し続けることだけではありません。他人の速さと比べると、自分を蓄える必要が見えなくなります。強い動物も、いつも攻めているわけではありません。温存する時と、力を注ぐ時を選んでよいのです。静かな期間にも能力は失われません。長い時間の中で、自分の歩幅で力を表してください。","th":"ความสามารถไม่ใช่การผลิตผลงานไม่หยุด เปรียบเทียบกับคนอื่นอาจทำให้ลืมเติมพลัง แม้สัตว์แข็งแรงก็ไม่ได้บุกทุกฤดู คุณเลือกได้ว่าจะเก็บแรงหรือใช้เต็มที่เมื่อไร ช่วงเงียบไม่ได้ลบความสามารถ ให้ผลงานมีขอบฟ้าที่ยาวขึ้น และปรากฏในจังหวะของคุณ","ar":"القدرة ليست تدفّقًا دائمًا من الإنتاج. مقارنة سرعتك بالآخرين قد تحجب حاجتك لشحن مواردك. حتى الحيوان القوي لا يهاجم في كل موسم. اختر متى تحفظ طاقتك ومتى يستحق الموقف كامل قوتك. الهدوء لا يمحو قدرتك؛ امنح مساهمتك أفقًا أطول وإيقاعًا يخصّك."},"34":{"zh-CN":"目前的状态有些改变不再和以前相似，这是迭代后又一轮开始的信号。无需担心会发生什么，也无需着急寻求确定。你或许在等待一个“完美的开始”，总觉得还没准备好——还不够强、还不够清楚、还不是时候。 “元”并非是起跑线上的枪声，也不是是万事俱备后的那一下，而是事情进入新的转机刚刚好打开的那一条缝。你不需要准备好一切，你只需置身其中。不用怀疑这一下不是“对的开始”，你的经历赋予了你太想要一个不会错的起点。元，不是你踩在万全的准备上。而是，勇敢地把握住机会，就是好的开始。","zh-TW":"目前的狀態有些改變不再和以前相似，這是迭代后又一輪開始的信號。無需擔心會發生什么，也無需著急尋求確定。你或許在等待一個“完美的開始”，總覺得還沒準備好——還不夠強、還不夠清楚、還不是時候。 “元”并非是起跑線上的槍聲，也不是是萬事俱備后的那一下，而是事情進入新的轉機剛剛好打開的那一條縫。你不需要準備好一切，你只需置身其中。不用懷疑這一下不是“對的開始”，你的經歷賦予了你太想要一個不會錯的起點。元，不是你踩在萬全的準備上。而是，勇敢地把握住機會，就是好的開始。","en":"Something has changed, and another beginning may be opening. You do not need certainty about everything before entering it. The wish for a perfect start can make every opening seem too early. A beginning may be only a small gap in familiar circumstances. Your past experience can help you meet it without guaranteeing that nothing will go wrong. Taking an available step can be a good start in itself.","ja":"何かが変わり、次の始まりが開きつつあるのかもしれません。すべてを確かめてから入る必要はありません。完璧な出発を望むほど、どんな機会も早すぎるように見えます。始まりは、日常の小さな隙間かもしれません。経験を頼りに、間違わない保証ではなく、今ある一歩を選んでください。それ自体がよい始まりです。","th":"บางสิ่งเปลี่ยนไปและการเริ่มใหม่อาจกำลังเปิด ไม่ต้องแน่ใจทุกอย่างก่อนเข้าไป อยากเริ่มสมบูรณ์อาจทำให้ทุกโอกาสดูเร็วเกิน การเริ่มอาจเป็นช่องเล็ก ๆ ในสิ่งคุ้นเคย ประสบการณ์ช่วยให้พบมันได้โดยไม่รับประกันว่าจะไม่ผิด ก้าวที่มีให้ตอนนี้ก็เป็นการเริ่มที่ดีได้","ar":"تغيّر شيء ما وربما تُفتح بداية أخرى. لا تحتاج إلى اليقين بكل شيء قبل دخولها. طلب البداية المثالية قد يجعل كل فرصة تبدو مبكرة. قد تكون البداية شقًا صغيرًا في المألوف. خبرتك تسندك دون ضمان غياب الخطأ. اتخاذ خطوة متاحة بداية جيدة بحد ذاته."},"35":{"zh-CN":"在你的周围都在强调效率和成果，能为自己创造一些更有利的条件，是对自己负责的驱动力。此刻或许你嫌自己反应不够快、决定不够狠、效率不够高。“利”并非是锋利、是速度、是一刀两断不拖泥带水，这个符号是刀割麦穗，对准永远比盲目地收割重要。收获之前，确定方向，成熟与否是收获的时机。怕慢一步就被抢了先、怕犹豫就错过了时机、怕自己没有收获。你已经拥有着收获的能力，“快”并不能够代表一切。你只需要花些时间观察方向，在对的时候用对的那一下，便是无悔的收获。","zh-TW":"在你的周圍都在強調效率和成果，能為自己創造一些更有利的條件，是對自己負責的驅動力。此刻或許你嫌自己反應不夠快、決定不夠狠、效率不夠高。“利”并非是鋒利、是速度、是一刀兩斷不拖泥帶水，這個符號是刀割麥穗，對準永遠比盲目地收割重要。收獲之前，確定方向，成熟與否是收獲的時機。怕慢一步就被搶了先、怕猶豫就錯過了時機、怕自己沒有收獲。你已經擁有著收獲的能力，“快”并不能夠代表一切。你只需要花些時間觀察方向，在對的時候用對的那一下，便是無悔的收獲。","en":"Speed is not the only measure of a useful action. Before harvesting, notice what is ripe and where the blade should go. Anxiety about being overtaken may make observation feel like delay, although direction and timing are part of your skill. You already have the capacity to act. Give yourself time to see clearly, then make the movement that fits the moment rather than cutting everywhere at once.","ja":"役立つ行動は、速さだけでは測れません。刈り取る前に、何が熟し、どこへ刃を向けるかを見ること。先を越される不安で観察が遅れに見えても、方向と時機を読むことは力の一部です。行動する力はすでにあります。一度に何でも刈るより、よく見て、その時に合う動きを選んでください。","th":"การกระทำที่มีประโยชน์ไม่ได้วัดด้วยความเร็วอย่างเดียว ก่อนเก็บเกี่ยว ดูว่าอะไรสุกและควรใช้คมตรงไหน กลัวถูกแซงอาจทำให้การสังเกตเหมือนเสียเวลา ทั้งที่ทิศและจังหวะคือทักษะ คุณมีความสามารถลงมือแล้ว ให้เวลามองชัดแล้วขยับให้เหมาะกับตอนนั้น แทนตัดทุกอย่างพร้อมกัน","ar":"السرعة ليست المقياس الوحيد للفعل النافع. قبل الحصاد، انظر إلى النضج وموضع النصل. قد يجعلك خوف السبق ترى الملاحظة تأخيرًا، مع أن الاتجاه والتوقيت جزء من مهارتك. القدرة موجودة؛ خذ وقتًا للرؤية ثم اختر الحركة المناسبة بدل القطع في كل اتجاه."},"36":{"zh-CN":"当事情结果未按你的期待出现的时候，便会感到受阻。这种不顺的状态，并不是要你否定整个过程，也不是为了比较为什么别人那么顺，你却总遇到阻碍。经历弯道的溪水才能发出独特的声响。“顺”不是没有阻碍、一路畅通、心想事成，而是你遇到石头的障碍，知道依然可以如同水流一样平稳绕过。你无需改变什么，弯道才是生活里的基本配置，人人都如同你一样，不必羡慕，也不必与障碍对抗。温柔地和自己的心情待在一起，承认自己所处的境地。在平静的时刻，再次注视这一当下的局面，观察走势是否有规律有利于事情的进展，是否存在着一些不被阻碍的机会点。跟随水势的节律，融入其中，顺应则通达。","zh-TW":"當事情結果未按你的期待出現的時候，便會感到受阻。這種不順的狀態，并不是要你否定整個過程，也不是為了比較為什么別人那么順，你卻總遇到阻礙。經歷彎道的溪水才能發出獨特的聲響。“順”不是沒有阻礙、一路暢通、心想事成，而是你遇到石頭的障礙，知道依然可以如同水流一樣平穩繞過。你無需改變什么，彎道才是生活里的基本配置，人人都如同你一樣，不必羨慕，也不必與障礙對抗。溫柔地和自己的心情待在一起，承認自己所處的境地。在平靜的時刻，再次注視這一當下的局面，觀察走勢是否有規律有利于事情的進展，是否存在著一些不被阻礙的機會點。跟隨水勢的節律，融入其中，順應則通達。","en":"A bend in the stream is not a failure of the water. When results differ from your hopes, you need not dismiss the whole process or compare your path with someone else’s. Acknowledge the obstacle and your feelings about it. Then look for an opening the current can follow. Moving smoothly can mean bending around a stone, not having every stone removed. Your gentleness can be part of how you continue.","ja":"流れの曲がり角は、水の失敗ではありません。望みと違う結果でも、過程全体を否定したり、人と比べたりしなくて大丈夫。障害と、それに対する気持ちを認めてください。そのうえで流れられる隙間を探す。順調さは、石をすべて除くことではなく、回り込めることでもあります。優しさも、進み方の一部になります。","th":"ทางโค้งของลำธารไม่ใช่ความล้มเหลวของน้ำ ผลไม่ตรงหวังไม่ต้องทำให้ปฏิเสธทั้งกระบวนการหรือเทียบกับใคร ยอมรับสิ่งกีดขวางและความรู้สึก แล้วมองช่องที่กระแสผ่านได้ ราบรื่นอาจหมายถึงอ้อมหิน ไม่ใช่เอาหินออกหมด ความอ่อนโยนเป็นส่วนหนึ่งของการไปต่อได้","ar":"انعطاف الجدول ليس فشلًا للماء. اختلاف النتيجة عن أملك لا يوجب رفض المسار كله أو مقارنته بغيرك. اعترف بالعائق وبمشاعرك، ثم ابحث عن فتحة يسلكها التيار. السلاسة قد تعني الالتفاف حول الحجر لا إزالة كل الأحجار. قد يكون اللطف جزءًا من استمرارك."},"37":{"zh-CN":"合作是当下的状态，你或许在“合作”里感到委屈——觉得自己出多了、别人出少了；或者觉得自己想使劲，却使不上。你以为“共”是平均、是公平、是你来我往的清晰回应。可这个符号告诉你，不是每只手用一样的力，是每只手都愿意在。怕自己吃亏、怕别人不值得、怕白费力气，这份怕，是你潜意识对你的保护。共，不是掂量谁多谁少。而是彼此愿意把手放上去，保持不放下来。你不是一个人在抬，多了的这份力量也是你此时的需要与重要分担。","zh-TW":"合作是當下的狀態，你或許在“合作”里感到委屈——覺得自己出多了、別人出少了；或者覺得自己想使勁，卻使不上。你以為“共”是平均、是公平、是你來我往的清晰回應。可這個符號告訴你，不是每只手用一樣的力，是每只手都愿意在。怕自己吃虧、怕別人不值得、怕白費力氣，這份怕，是你潛意識對你的保護。共，不是掂量誰多誰少。而是彼此愿意把手放上去，保持不放下來。你不是一個人在抬，多了的這份力量也是你此時的需要與重要分擔。","en":"Sharing a task can bring concern about who contributes more. That concern may be trying to protect you, but partnership is not always identical effort from every hand. Notice the people willing to stay engaged and what their presence makes possible. You are not lifting entirely alone. A shared commitment can matter alongside a fair conversation about each person’s capacity and contribution.","ja":"共同作業では、誰の負担が多いか気になることがあります。それは自分を守る感覚でもありますが、すべての手が同じ力を出すとは限りません。関わり続けようとする人と、その存在で可能になることに気づいてください。ひとりきりで持ち上げてはいません。互いの余力や役割を話し合いながら、共に持つ意思も大切にできます。","th":"ร่วมงานอาจทำให้กังวลว่าใครให้มากกว่า ความกังวลอาจกำลังปกป้องคุณ แต่การร่วมมือไม่ได้แปลว่าทุกมือใช้แรงเท่ากันเสมอ ลองเห็นคนที่ยังพร้อมมีส่วนและสิ่งที่เป็นไปได้เพราะเขาอยู่ คุณไม่ได้ยกคนเดียว ความตั้งใจร่วมสำคัญควบคู่กับการคุยอย่างเป็นธรรมเรื่องกำลังและส่วนร่วม","ar":"قد يثير العمل المشترك قلقًا بشأن من يبذل أكثر. لهذا القلق وظيفة حماية، لكن الشراكة لا تعني دائمًا جهدًا متطابقًا من كل يد. لاحظ من يبقى مشاركًا وما يتيحه وجوده. أنت لا ترفع الحمل وحدك. الالتزام المشترك مهم، إلى جانب حوار عادل عن قدرة كل شخص ومساهمته."},"38":{"zh-CN":"安稳是你这个阶段安全感的重要来源。你或许在“站不稳”的焦虑里——事情太多、变化太快、不知道下一秒会倒向哪边。何以为“立”？这个问题消耗了太多的内在力量。立，不是固定在那里、不是硬撑、也是不管风吹雨打都不动，而是在风雨之中，依然能够锚定一个有利于自身的点，稳稳地不为撼动。对于这个阶段的你来说，这个锚点会是什么？“立”并非必须是静止的，是勇敢迎接一切晃动的从容，以及善用锚点的韧性。疾风不会一直吹，骤雨不会一直下，不用害怕一松就倒、怕动起来就失控、怕自己撑不住。你要做的，只是在不同的天气，识别出自己的重心在哪，知道该往哪个方向用力创造动态的平衡。","zh-TW":"安穩是你這個階段安全感的重要來源。你或許在“站不穩”的焦慮里——事情太多、變化太快、不知道下一秒會倒向哪邊。何以為“立”？這個問題消耗了太多的內在力量。立，不是固定在那里、不是硬撐、也是不管風吹雨打都不動，而是在風雨之中，依然能夠錨定一個有利于自身的點，穩穩地不為撼動。對于這個階段的你來說，這個錨點會是什么？“立”并非必須是靜止的，是勇敢迎接一切晃動的從容，以及善用錨點的韌性。疾風不會一直吹，驟雨不會一直下，不用害怕一松就倒、怕動起來就失控、怕自己撐不住。你要做的，只是在不同的天氣，識別出自己的重心在哪，知道該往哪個方向用力創造動態的平衡。","en":"Standing firmly need not mean staying rigid in every wind. When things change quickly, ask what can serve as an anchor for you now. Stability can be a responsive balance: knowing your centre and adjusting how you use your strength. Storms do not last forever, and movement is not necessarily loss of control. You can meet changing conditions without requiring yourself never to sway.","ja":"しっかり立つことは、どんな風にも硬直することではありません。変化が速いとき、今のよりどころを問いかけてください。安定は、重心を知り、力の向きを調整する動的なバランスでもあります。嵐は永遠ではなく、動くことも制御を失うこととは限りません。揺れない自分を要求せず、変化に応じて立つことができます。","th":"ยืนมั่นไม่จำเป็นต้องแข็งต้านทุกลม เมื่อสิ่งต่าง ๆ เปลี่ยนเร็ว ถามว่าอะไรเป็นจุดยึดตอนนี้ ความมั่นคงเป็นสมดุลที่ปรับได้ รู้จุดศูนย์กลางแล้วเปลี่ยนวิธีใช้แรง พายุไม่ได้อยู่นิรันดร์ การขยับไม่จำเป็นต้องเสียการควบคุม คุณพบความเปลี่ยนแปลงได้โดยไม่เรียกร้องว่าต้องไม่ไหวเลย","ar":"الثبات لا يعني التصلّب أمام كل ريح. حين تتسارع التغيّرات، اسأل عمّا يصلح مرساة لك الآن. الاستقرار توازن يستجيب: تعرف مركزك وتعدّل استخدام قوتك. العواصف لا تدوم، والحركة ليست فقدان السيطرة دائمًا. يمكنك مواجهة الظروف دون مطالبة نفسك بألا تتمايل."},"39":{"zh-CN":"为你感到喜悦，这个阶段能够在平淡的生活中，还能够发现值得庆祝的瞬间。这份“喜”是过往来时路在当下传递给你的礼物。请不要着急跳过此刻的心情，你完全拥有着可以久久沉浸在其中的资格，你配得上这份礼物。请允许自己在这一刻多做停留，就像品味一个下雨天的屋檐，一朵花开的芬芳，一束阳光的温度，不疾不徐，不被打扰。“喜”的发生，从来都不是从天而降，你动手敲击，它才会有声响。好事并非只有耀眼的高光时刻、出其不意的幸运、精心准备的惊喜，而是这个当下，你的完好无损，你自由流畅的呼吸。持久的“喜”从来不是别人给的额外的附件，而是源于一颗平和、安宁的内心自给自足的安然。不用担心快乐太短，不用怀疑自己“不值得”开心，纠结来自于把“喜”默认为未来远景中才会存在的画面。“喜”不是结果，就是现在，此刻，完好的你。","zh-TW":"為你感到喜悅，這個階段能夠在平淡的生活中，還能夠發現值得慶祝的瞬間。這份“喜”是過往來時路在當下傳遞給你的禮物。請不要著急跳過此刻的心情，你完全擁有著可以久久沉浸在其中的資格，你配得上這份禮物。請允許自己在這一刻多做停留，就像品味一個下雨天的屋檐，一朵花開的芬芳，一束陽光的溫度，不疾不徐，不被打擾。“喜”的發生，從來都不是從天而降，你動手敲擊，它才會有聲響。好事并非只有耀眼的高光時刻、出其不意的幸運、精心準備的驚喜，而是這個當下，你的完好無損，你自由流暢的呼吸。持久的“喜”從來不是別人給的額外的附件，而是源于一顆平和、安寧的內心自給自足的安然。不用擔心快樂太短，不用懷疑自己“不值得”開心，糾結來自于把“喜”默認為未來遠景中才會存在的畫面。“喜”不是結果，就是現在，此刻，完好的你。","en":"If you have found something to celebrate in an ordinary day, let yourself stay with it. You do not have to earn that moment again or hurry past it because it may be brief. Warmth, a flower’s scent or an unforced breath can be enough to notice. Joy is not reserved for a future achievement. It can be a meeting between your attention and the life that is here now.","ja":"日常の中に喜べることを見つけたなら、少しそこにいてください。短いかもしれないからと急いで通り過ぎたり、もう一度資格を得ようとしたりしなくて大丈夫。温かさ、花の香り、自然な呼吸にも気づけます。喜びは未来の達成だけのものではありません。今ある命と、あなたの注意が出会うところにもあります。","th":"ถ้าพบสิ่งน่าฉลองในวันธรรมดา ให้ตัวเองอยู่กับมัน ไม่ต้องหารายได้ให้คู่ควรอีกหรือรีบผ่านเพราะมันสั้น ความอุ่น กลิ่นดอกไม้ หรือลมหายใจที่ไม่ฝืนก็พอให้สังเกต ความยินดีไม่ได้สงวนไว้ให้ความสำเร็จอนาคต มันเกิดเมื่อความใส่ใจพบชีวิตที่อยู่ตรงนี้ได้","ar":"إن وجدت ما تحتفل به في يوم عادي، ابقَ معه قليلًا. لا تحتاج إلى استحقاق اللحظة مجددًا أو تجاوزها لأنها قصيرة. دفء أو رائحة زهرة أو نفس مريح تكفي للملاحظة. الفرح ليس محجوزًا لإنجاز آتٍ؛ قد ينشأ من لقاء انتباهك بالحياة الحاضرة."},"40":{"zh-CN":"你辛苦了，最近不少的事情令你劳心费神，请允许自己有片刻的安宁。\n\n你或许在怪自己“想太多”——脑袋停不下来，翻来覆去同一件事，越想越不在状态。越想停止“思”的内耗，屏蔽杂音、噪音，越和“思”紧密地连在一起。这个符号告诉你，心上面有令你操心的田地，也同时留有着窗口。思，不是你授权被念头淹没，是你坐在心里，看着念头从窗口飘过，并不带对自身的苛责。怕停不下来、怕想了也没用、怕自己被念头带跑，请放下对“思”必须要有结果的执着。思，不是你强行想出的答案，而是允许它自然流动之后的看见。","zh-TW":"你辛苦了，最近不少的事情令你勞心費神，請允許自己有片刻的安寧。\n\n你或許在怪自己“想太多”——腦袋停不下來，翻來覆去同一件事，越想越不在狀態。越想停止“思”的內耗，屏蔽雜音、噪音，越和“思”緊密地連在一起。這個符號告訴你，心上面有令你操心的田地，也同時留有著窗口。思，不是你授權被念頭淹沒，是你坐在心里，看著念頭從窗口飄過，并不帶對自身的苛責。怕停不下來、怕想了也沒用、怕自己被念頭帶跑，請放下對“思”必須要有結果的執著。思，不是你強行想出的答案，而是允許它自然流動之后的看見。","en":"You may be tired of the same thoughts circling again and again. Fighting them can sometimes tie you more tightly to them. Imagine sitting within the heart while thoughts pass a window. Notice them without adding blame or demanding an immediate answer. Thinking need not end in a result to be allowed. A little space around the flow can make room for something to become clearer.","ja":"同じ考えが巡り、疲れているのかもしれません。追い払おうとするほど、結びつきが強まることもあります。心の中に座り、窓の向こうを考えが通ると想像してください。責めず、すぐの答えを求めずに見守る。思考は、必ず成果を出さなくてもあってよいのです。流れの周りに余白ができると、自然に見えてくることもあります。","th":"คุณอาจเหนื่อยกับความคิดเดิมที่วนซ้ำ การต่อสู้อาจยิ่งผูกคุณไว้ ลองนึกว่านั่งอยู่ในใจมองความคิดผ่านหน้าต่าง สังเกตโดยไม่เพิ่มคำโทษหรือบังคับคำตอบทันที การคิดไม่ต้องจบด้วยผลลัพธ์จึงจะได้รับอนุญาต พื้นที่รอบกระแสอาจเปิดให้บางอย่างชัดขึ้น","ar":"قد تتعب من دوران الأفكار نفسها. مقاومتها قد تزيد ارتباطك بها. تخيّل الجلوس داخل القلب ومراقبة الأفكار تعبر نافذة. لاحظ دون لوم أو طلب إجابة فورية. لا يشترط أن ينتهي التفكير بنتيجة كي يُسمح به. مساحة حول التدفق قد تتيح رؤية أوضح."},"41":{"zh-CN":"被需要，也是一种重要的价值体验。从左手到右手，从你这到那，递出的过程，会升起“给”的顾虑——给时间、给精力、给关心、给资源、给钱财，怕给了就没了，怕给了收不回，怕最后两手空空。“予”的符号是纺线的梭子不断递出线的过程，看似是失去、是消耗、是付出，实则是存在的流动，是它到了另一个地方。怕自己不够给、怕给了不值得的人、怕有一天需要的时候拿不回来，过程中的纠结并不会带来爱，只会生气怨。“拥有”不一定需要时刻捏在手里，而是成全别人那一刻的内心依然富足的体验。予，是给出，并非放手。所有的给予，都在另一处编织的关系流动的经纬，长成更加宽广的柔韧。","zh-TW":"被需要，也是一種重要的價值體驗。從左手到右手，從你這到那，遞出的過程，會升起“給”的顧慮——給時間、給精力、給關心、給資源、給錢財，怕給了就沒了，怕給了收不回，怕最后兩手空空。“予”的符號是紡線的梭子不斷遞出線的過程，看似是失去、是消耗、是付出，實則是存在的流動，是它到了另一個地方。怕自己不夠給、怕給了不值得的人、怕有一天需要的時候拿不回來，過程中的糾結并不會帶來愛，只會生氣怨。“擁有”不一定需要時刻捏在手里，而是成全別人那一刻的內心依然富足的體驗。予，是給出，并非放手。所有的給予，都在另一處編織的關系流動的經緯，長成更加寬廣的柔韌。","en":"Giving time, care or resources can stir fear that nothing will remain. The image here is a shuttle passing thread: what leaves one hand can become part of a wider fabric. Giving is not necessarily disappearance; it can be movement into relationship. Notice both your capacity and your willingness, rather than turning the exchange into resentment. Something can matter to you without always being held tightly in your hand.","ja":"時間や気持ちを差し出すと、何も残らない不安が生まれることがあります。ここにあるのは、糸を渡す杼のイメージ。手を離れたものが、広い織物の一部になることもあります。与えることは消失だけではなく、関係の中の流れでもあります。恨みに変わる前に、余力と意思を確かめてください。握り続けなくても、大切であり続けるものがあります。","th":"ให้เวลา ความใส่ใจ หรือทรัพยากรอาจทำให้กลัวไม่เหลืออะไร ภาพนี้เหมือนกระสวยส่งด้าย สิ่งที่ออกจากมืออาจเป็นส่วนของผืนที่กว้างกว่า การให้ไม่จำเป็นต้องสูญหาย แต่อาจเคลื่อนไปในความสัมพันธ์ สังเกตทั้งกำลังและความเต็มใจแทนทำให้การแลกเปลี่ยนเป็นความคับแค้น สิ่งหนึ่งสำคัญกับคุณได้โดยไม่ต้องกำแน่นตลอด","ar":"قد يثير منح الوقت أو الرعاية خوف ألا يبقى شيء. الصورة هنا مكوك يمرّر الخيط؛ ما يغادر اليد قد يدخل نسيجًا أوسع. العطاء ليس اختفاءً بالضرورة، بل حركة في العلاقة. لاحظ قدرتك ورغبتك بدل تحويل التبادل إلى استياء. قد يظل الشيء مهمًا دون إمساكه بإحكام دائمًا."},"42":{"zh-CN":"委屈和压抑，并不是你的底色。习惯了一切归因于“我”，是对自己的最大敌意。记得孩童时候的你吗，多么容易自我表达，可以不顾及任何感受。你或许在怪自己“不够好”——脾气上来了压不住，或者压住了又觉得忍气吞声。放下对完美的“我”的认知，我不一定随时得是懂事的、温和的、得体的、周全的、不制造麻烦的。怕发火会伤人、怕拒绝会得罪人、怕真实的自己不被接受。改写“好人”必须没有刺。这个符号是一把三千年前的兵器，在受到威胁的时候，有防御和保护的功能。在你经历着受到威胁的时刻，别忘记，“我”天生就是一把兵器。你完全有着足够的勇气，对所有入侵和越界回复：不可以。我，有价值，有刃，有锋，有防御，也有攻击。不需要成为社会期待中理想化的完美“我”，去经历冲突、去热烈碰撞，勇敢活出“我”的攻击性，你的心灵才不会受内伤。我，不是你剪掉爪子的样子，有你想给的温柔，也有不退的底线。你知道，什么时候亮刃，什么时候收。","zh-TW":"委屈和壓抑，并不是你的底色。習慣了一切歸因于“我”，是對自己的最大敵意。記得孩童時候的你嗎，多么容易自我表達，可以不顧及任何感受。你或許在怪自己“不夠好”——脾氣上來了壓不住，或者壓住了又覺得忍氣吞聲。放下對完美的“我”的認知，我不一定隨時得是懂事的、溫和的、得體的、周全的、不制造麻煩的。怕發火會傷人、怕拒絕會得罪人、怕真實的自己不被接受。改寫“好人”必須沒有刺。這個符號是一把三千年前的兵器，在受到威脅的時候，有防御和保護的功能。在你經歷著受到威脅的時刻，別忘記，“我”天生就是一把兵器。你完全有著足夠的勇氣，對所有入侵和越界回復：不可以。我，有價值，有刃，有鋒，有防御，也有攻擊。不需要成為社會期待中理想化的完美“我”，去經歷沖突、去熱烈碰撞，勇敢活出“我”的攻擊性，你的心靈才不會受內傷。我，不是你剪掉爪子的樣子，有你想給的溫柔，也有不退的底線。你知道，什么時候亮刃，什么時候收。","en":"You do not have to be agreeable, composed and convenient at every moment to deserve respect. Anger or the wish to say no may be telling you that a boundary matters. The old weapon image can be read as the capacity to protect yourself, not an instruction to harm. You can speak clearly when something is not acceptable. Gentleness and a firm limit can belong to the same self.","ja":"いつも穏やかで、気が利き、迷惑をかけない人でなければ尊重されない、ということはありません。怒りや「いいえ」の気持ちは、境界線の大切さを知らせることがあります。古い武器のイメージは、傷つける指示ではなく、自分を守る力として受けとめられます。受け入れられないことを明確に伝えてよいのです。優しさと譲れない線は、同じ自分の中にあってよいのです。","th":"ไม่ต้องน่าพอใจ สุขุม และสะดวกสำหรับคนอื่นทุกขณะจึงจะควรได้รับความเคารพ ความโกรธหรืออยากบอกไม่อาจบอกว่าขอบเขตสำคัญ ภาพอาวุธโบราณอ่านได้ว่าเป็นพลังปกป้องตัวเอง ไม่ใช่คำสั่งทำร้าย คุณพูดชัดได้เมื่อบางอย่างยอมรับไม่ได้ ความอ่อนโยนกับเส้นที่มั่นคงอยู่ในตัวตนเดียวกันได้","ar":"لا يلزم أن تكون لطيفًا وهادئًا ومريحًا للآخرين في كل لحظة لتستحق الاحترام. قد يخبرك الغضب أو رفض شيء بأن حدًا مهمًا قد مُسّ. تُقرأ صورة السلاح القديم كقدرة على الحماية، لا دعوة للأذى. يمكنك قول ما لا تقبله بوضوح. اللطف والحد الثابت يسكنان الذات نفسها."},"43":{"zh-CN":"当现状不是你想要的时候，创造一个变化，是一种在不失去原样的同时，能够继续朝着向好的方向发展的拐点。变化带来不安，而不变也并不代表着安全。怕失去熟悉的东西、怕新的不如旧的好、怕变化意味着某种挫败。结束一种状态，不一定是让其消失，这个念头会带来对抗。“化”不是消失、不是断裂、不是从有到无。这个符号呈现的事是两个人，一正一反，在动态的位置中寻找平衡对称。化，不是没了。是水升起来成了云，云落下来又成了雨。你不需要改变什么，减少什么，只是换一个位置，创造一个新的全局的视角，找到同一种物质的另一种形态，继续存在。","zh-TW":"當現狀不是你想要的時候，創造一個變化，是一種在不失去原樣的同時，能夠繼續朝著向好的方向發展的拐點。變化帶來不安，而不變也并不代表著安全。怕失去熟悉的東西、怕新的不如舊的好、怕變化意味著某種挫敗。結束一種狀態，不一定是讓其消失，這個念頭會帶來對抗。“化”不是消失、不是斷裂、不是從有到無。這個符號呈現的事是兩個人，一正一反，在動態的位置中尋找平衡對稱。化，不是沒了。是水升起來成了云，云落下來又成了雨。你不需要改變什么，減少什么，只是換一個位置，創造一個新的全局的視角，找到同一種物質的另一種形態，繼續存在。","en":"Change can feel like losing what is familiar, but staying the same does not always mean safety. Transformation need not erase everything that came before. Water becomes cloud and returns as rain: something continues in another form. Try shifting your position to see the whole scene differently. You may find a way forward that changes the arrangement without declaring your previous life a failure.","ja":"変化は慣れたものを失うように感じられますが、変わらないことが安全とは限りません。変容は、これまでをすべて消すことではありません。水が雲になり、雨で戻るように、別の形で続くものがあります。立つ位置を変えて全体を見てください。以前の自分を失敗と決めずに、配置を変えて進む道が見つかるかもしれません。","th":"เปลี่ยนอาจเหมือนเสียสิ่งคุ้นเคย แต่เหมือนเดิมก็ไม่ได้ปลอดภัยเสมอ การแปรเปลี่ยนไม่ต้องลบทุกอย่างก่อนหน้า น้ำกลายเป็นเมฆแล้วกลับเป็นฝน บางสิ่งต่อเนื่องในอีกรูป ลองย้ายตำแหน่งเพื่อเห็นภาพรวมต่างไป คุณอาจพบทางเปลี่ยนการจัดวางโดยไม่ตัดสินชีวิตเดิมว่าล้มเหลว","ar":"قد يبدو التغيير فقدانًا للمألوف، لكن البقاء كما أنت لا يضمن الأمان. التحوّل لا يمحو كل ما سبق. يصير الماء سحابًا ويعود مطرًا؛ شيء يستمر في هيئة أخرى. غيّر موضعك لترى المشهد بصورة مختلفة. ربما تجد ترتيبًا جديدًا دون إعلان حياتك السابقة فشلًا."},"44":{"zh-CN":"此刻，安放你所有的担忧、顾虑，给自己传递出一份深长的“信任”。你所处的路径已经抵达越来越开阔的位置。船划到宽处，桨就不用那么急了。不是力气变大了，是水面变宽了。想要“好起来”的这路上累了许久，努力了很久，尤其在那些会反复的时刻。“愈”并不是伤口完全消失、不是再也不会痛、更不是回到什么都没发生之前的样子。这个符号的意象是，一个人在划船，越划越宽，越划越轻松，心情也会越来越舒畅的状态。愈，不是回到过去，也不是终点，而是哪怕前路漫漫，依然怀着“信任”前行。你渡过了窄处，迎接你的是更加宽广的水，稳稳托着你的每一步。","zh-TW":"此刻，安放你所有的擔憂、顧慮，給自己傳遞出一份深長的“信任”。你所處的路徑已經抵達越來越開闊的位置。船劃到寬處，槳就不用那么急了。不是力氣變大了，是水面變寬了。想要“好起來”的這路上累了許久，努力了很久，尤其在那些會反復的時刻。“愈”并不是傷口完全消失、不是再也不會痛、更不是回到什么都沒發生之前的樣子。這個符號的意象是，一個人在劃船，越劃越寬，越劃越輕松，心情也會越來越舒暢的狀態。愈，不是回到過去，也不是終點，而是哪怕前路漫漫，依然懷著“信任”前行。你渡過了窄處，迎接你的是更加寬廣的水，穩穩托著你的每一步。","en":"Think of a boat reaching wider water after a narrow passage. The journey toward feeling better can include effort and difficult returns; it need not restore a past in which nothing happened. Recovery here is an image of moving onward with a little more trust and room to breathe. You may ease the urgency of each stroke. What you have crossed can remain part of you while the water ahead offers more space.","ja":"狭い水路を抜け、広い水面へ出る舟を思い浮かべてください。よくなりたい道には、努力や揺り戻しもあります。何も起きなかった過去へ戻る必要はありません。ここでの癒やしは、少しの信頼と呼吸の余地を持って進むイメージです。ひと漕ぎごとの急ぎを緩めて。通ってきた道を含んだまま、広い水へ進めます。","th":"นึกถึงเรือที่ผ่านช่องแคบสู่น้ำกว้าง ทางสู่ดีขึ้นอาจมีทั้งความพยายามและวันที่ย้อนยาก ไม่ต้องกลับสู่อดีตที่เหมือนไม่มีอะไรเกิด การฟื้นตัวในภาพนี้คือไปต่อด้วยความเชื่อใจและพื้นที่หายใจเพิ่มนิด คุณผ่อนความเร่งในแต่ละจังหวะพายได้ สิ่งที่ผ่านยังเป็นส่วนของคุณ ขณะน้ำข้างหน้าเปิดกว้างขึ้น","ar":"تخيّل قاربًا يصل إلى ماء أوسع بعد ممر ضيق. طريق التحسّن قد يحمل جهدًا وعودة للصعوبة؛ لا يلزم أن يعيد ماضيًا لم يحدث فيه شيء. التعافي هنا صورة للتقدم بمزيد من الثقة وفسحة التنفس. خفف استعجال كل جدفة. يمكن لما عبرته أن يبقى جزءًا منك بينما يتسع الماء أمامك."},"45":{"zh-CN":"这一路一定不容易吧，在获得的同时也疏漏了一些重要，请在此刻，给自己一个坚实的拥抱。有呼吸在，你就在。在“安康”的路上奔波，消耗了你不少的心气——希望更健康、希望得到安宁、希望心里感到喜悦。“康”并不是赶出来的，买来的，或必须用力才够得到的。“康”这个符号告诉你，一个人俯身打水，桶放下去，水自然涌进来，从一滴到一股，越汲越多。不必拉得太急，允许自己在这个阶段放缓速度，驻足等一等容器，时间足够的时候它就恢复满了。康，不是你去追，而是你停下来，耐心等水满。怕受到威胁、怕太脆弱、怕再不做就失控，害怕本身就是一剂助长“不康”的材料。虚空得以应物，为重要的事物腾挪空间，水流才进得来。你值得在握这份重新漫溢的安康。","zh-TW":"這一路一定不容易吧，在獲得的同時也疏漏了一些重要，請在此刻，給自己一個堅實的擁抱。有呼吸在，你就在。在“安康”的路上奔波，消耗了你不少的心氣——希望更健康、希望得到安寧、希望心里感到喜悅。“康”并不是趕出來的，買來的，或必須用力才夠得到的。“康”這個符號告訴你，一個人俯身打水，桶放下去，水自然涌進來，從一滴到一股，越汲越多。不必拉得太急，允許自己在這個階段放緩速度，駐足等一等容器，時間足夠的時候它就恢復滿了。康，不是你去追，而是你停下來，耐心等水滿。怕受到威脅、怕太脆弱、怕再不做就失控，害怕本身就是一劑助長“不康”的材料。虛空得以應物，為重要的事物騰挪空間，水流才進得來。你值得在握這份重新漫溢的安康。","en":"You have spent energy seeking steadiness and well-being. Pause to notice what needs replenishing rather than making recovery another race. Imagine lowering a bucket and giving it time to fill. Pulling too quickly leaves little room for the water. You can make space for what matters and accept a slower rhythm. This image offers an invitation to care for yourself, not a demand to feel well immediately.","ja":"安らぎや健やかさを求めて、多くの力を使ってきたのかもしれません。回復まで競争にせず、何を満たす必要があるか感じてください。桶を下ろし、水がたまるのを待つように。急いで引けば、十分に入りません。大切なものの場所を空け、ゆっくりしたリズムを受け入れてよいのです。これは、すぐ元気になる要求ではなく、自分をいたわる招待です。","th":"คุณใช้แรงมากเพื่อความมั่นคงและสุขภาวะ ลองหยุดดูว่าอะไรต้องเติม แทนทำให้การฟื้นเป็นการแข่งขันอีก นึกถึงหย่อนถังแล้วรอให้น้ำเต็ม ดึงเร็วเกินน้ำก็เข้าไม่พอ คุณเปิดพื้นที่ให้สิ่งสำคัญและรับจังหวะช้าลงได้ ภาพนี้ชวนให้ดูแลตัวเอง ไม่ได้เรียกร้องว่าต้องดีทันที","ar":"بذلت طاقة بحثًا عن الاستقرار والعافية. لاحظ ما يحتاج إلى تجدد بدل جعل التعافي سباقًا آخر. تخيّل إنزال دلو وتركه يمتلئ؛ سحبه سريعًا لا يتيح الماء الكافي. أفسح المجال لما يهم واقبل إيقاعًا أبطأ. الصورة دعوة للرعاية، لا مطالبة بأن تصبح بخير فورًا."},"46":{"zh-CN":"你的所有付出都配得上一次上升。你或许在催促自己“快点升”——职位快点升、状态快点升、财富快点升、智慧快点增长、人生快点往上走。“升”并非硬拉、不是攀爬、也不是不顾一切往上够。这个符号告诉你，一只手，将酒斗从坛里提起。经历了长期至暗时刻的孤独酝酿，才成就了当下的“升”。既是美酒，无需用蛮力拽，醇香对带领一只手在恰当的时刻舀起上升。怕被遗忘、怕升不上去、怕慢了就会变卦、怕自己不够好。担心是对更高空间的向往，同时，也会让你直接跳过酒酿本身的美好，去仰慕那个接下来的位置。你的本身，就已经完成了一次内在的“升”。成为自己稳定的进化容器。","zh-TW":"你的所有付出都配得上一次上升。你或許在催促自己“快點升”——職位快點升、狀態快點升、財富快點升、智慧快點增長、人生快點往上走。“升”并非硬拉、不是攀爬、也不是不顧一切往上夠。這個符號告訴你，一只手，將酒斗從壇里提起。經歷了長期至暗時刻的孤獨醞釀，才成就了當下的“升”。既是美酒，無需用蠻力拽，醇香對帶領一只手在恰當的時刻舀起上升。怕被遺忘、怕升不上去、怕慢了就會變卦、怕自己不夠好。擔心是對更高空間的向往，同時，也會讓你直接跳過酒釀本身的美好，去仰慕那個接下來的位置。你的本身，就已經完成了一次內在的“升”。成為自己穩定的進化容器。","en":"Wanting to rise can make the next position seem more valuable than the growth already taking place within you. Picture a ladle lifting what has quietly matured in a jar. The preparation matters as much as the upward movement. You do not have to pull yourself higher by force or overlook what time has developed. Let your own steadiness be a container for the next stage.","ja":"上へ進みたい気持ちで、内側の成長より次の位置だけが大切に見えることがあります。壺で静かに熟したものを、柄杓ですくう姿を想像してください。持ち上がる動きと同じくらい、準備の時間も大切です。力ずくで引き上げず、育ってきたものを見落とさないで。自分の安定を、次の段階を育てる器にしてください。","th":"อยากสูงขึ้นอาจทำให้ตำแหน่งถัดไปมีค่ากว่าการเติบโตที่เกิดในตัวแล้ว นึกถึงทัพพีตักสิ่งที่บ่มเงียบ ๆ ในไห การเตรียมมีค่าพอกับการยกขึ้น ไม่ต้องดึงตัวเองด้วยแรงหรือมองข้ามสิ่งที่เวลาพัฒนา ให้ความมั่นคงของคุณเป็นภาชนะสำหรับขั้นต่อไป","ar":"الرغبة في الصعود قد تجعل المكان التالي أهم من النمو الجاري فيك. تخيّل مغرفة ترفع ما نضج بهدوء داخل جرّة. للتحضير قيمة كقيمة الارتفاع. لا تحتاج إلى جذب نفسك بالقوة أو تجاهل ما طوّره الوقت. دع ثباتك وعاءً للمرحلة التالية."},"47":{"zh-CN":"丝还没染色的时候，不是没有颜色，是所有颜色都还在路上。你不需要急着涂满，白着，就是完整的。你或许在嫌弃自己“太素”——不够有趣、不够耀眼、不够丰富。“素”的符号，是白色的原丝，没染过并不代表没有价值，却恰恰是价值所在——初始本真的原貌，它最珍贵的样子未被涂抹侵染的白。怕自己太普通、怕不被注意、怕不符合别人的期待，有这样念头升起的时刻，是因为优先认定了“素”是不够好。素，不是你还没成为什么，是你本来就是什么。不需要加，不需要改。那匹白丝，没染的时候，一束光能映万物。不是空白，是本白。所有颜色，都从你自由开始。","zh-TW":"絲還沒染色的時候，不是沒有顏色，是所有顏色都還在路上。你不需要急著涂滿，白著，就是完整的。你或許在嫌棄自己“太素”——不夠有趣、不夠耀眼、不夠豐富。“素”的符號，是白色的原絲，沒染過并不代表沒有價值，卻恰恰是價值所在——初始本真的原貌，它最珍貴的樣子未被涂抹侵染的白。怕自己太普通、怕不被注意、怕不符合別人的期待，有這樣念頭升起的時刻，是因為優先認定了“素”是不夠好。素，不是你還沒成為什么，是你本來就是什么。不需要加，不需要改。那匹白絲，沒染的時候，一束光能映萬物。不是空白，是本白。所有顏色，都從你自由開始。","en":"Undyed silk is not incomplete. Its original state holds possibilities without needing every colour at once. Feeling too plain may reflect someone else’s expectation of brightness rather than a lack in you. You do not have to add a performance or alter yourself to become worthy of attention. The quiet texture you already have can be enough. Let any new colour be a choice, not a repair of your existence.","ja":"染めていない絹は、未完成ではありません。すべての色を急いで足さなくても、もとの姿に可能性があります。地味すぎるという思いは、自分の欠如ではなく、他人の期待かもしれません。注目に値するために、飾ったり変わったりする必要はありません。今ある静かな質感も十分です。色を加えるなら、存在の修理ではなく、自分の選択として。","th":"ไหมที่ยังไม่ย้อมไม่ได้ไม่สมบูรณ์ สภาพเดิมมีความเป็นไปได้โดยไม่ต้องใส่ทุกสีพร้อมกัน รู้สึกธรรมดาเกินอาจมาจากความคาดหวังคนอื่น ไม่ใช่ความขาดในตัว ไม่ต้องเพิ่มการแสดงหรือแก้ตัวเองจึงจะควรได้รับความสนใจ เนื้อสัมผัสเงียบ ๆ ที่มีอาจพอ ให้สีใหม่เป็นทางเลือก ไม่ใช่การซ่อมการมีอยู่","ar":"الحرير غير المصبوغ ليس ناقصًا. حالته الأصلية تحمل احتمالات دون احتياج كل الألوان. الشعور بأنك عادي قد يعكس توقع الآخرين لا نقصًا فيك. لا يلزم إضافة أداء أو تعديل نفسك لتستحق الانتباه. ملمسك الهادئ قد يكفي. ليكن اللون الجديد اختيارًا لا إصلاحًا لوجودك."},"48":{"zh-CN":"观点的分歧，仅仅代表立场的不同，不能代表你不好。你或许在争与不争之间拉扯——有些分歧想要表达，有些道理想分辩，有些亏咽不下。“禅”并非是佛系的归隐，不柔弱、不是退让、更不是把气咽回去。这个符号呈现的是，古人在表达对天地的崇敬，让人们免于战乱。禅，不是丢掉武器，而是握武器，但选择不攻击。怕放下就是认输、怕不争就是懦弱、怕自己的边界被踏平。不争不代表不具备争的能力。大音希声，大象无形，真正高能的人，反而是最先放得下的人，也是最能体悟到内心的“禅”的人。火，可以慢慢熄灭。武器仅代表力量，你清楚什么时候该亮，什么时候该收。你不是没有战斗的能力。你是那位有能力，也有不战的智慧的智者。","zh-TW":"觀點的分歧，僅僅代表立場的不同，不能代表你不好。你或許在爭與不爭之間拉扯——有些分歧想要表達，有些道理想分辯，有些虧咽不下。“禪”并非是佛系的歸隱，不柔弱、不是退讓、更不是把氣咽回去。這個符號呈現的是，古人在表達對天地的崇敬，讓人們免于戰亂。禪，不是丟掉武器，而是握武器，但選擇不攻擊。怕放下就是認輸、怕不爭就是懦弱、怕自己的邊界被踏平。不爭不代表不具備爭的能力。大音希聲，大象無形，真正高能的人，反而是最先放得下的人，也是最能體悟到內心的“禪”的人。火，可以慢慢熄滅。武器僅代表力量，你清楚什么時候該亮，什么時候該收。你不是沒有戰斗的能力。你是那位有能力，也有不戰的智慧的智者。","en":"Disagreement does not mean there is something wrong with you. You can have the strength to defend a boundary and also choose not to enter every fight. Quiet is not automatically surrender, and declining conflict need not erase your position. Let the heat settle enough to choose your response. This symbol invites the wisdom of using strength deliberately, with room for both firmness and restraint.","ja":"意見が違うことは、自分が悪いという意味ではありません。境界線を守る力を持ちながら、すべての争いには入らない選択もできます。静けさは必ずしも降伏ではなく、衝突を避けても立場は消えません。熱が少し落ち着いてから、応じ方を選んでください。力を意識して使うこと、確かさと節度を両立することへの招待です。","th":"เห็นต่างไม่ได้แปลว่าคุณผิด คุณมีแรงปกป้องขอบเขตพร้อมเลือกไม่ร่วมทุกการทะเลาะได้ เงียบไม่ได้ยอมแพ้เสมอ และไม่ปะทะไม่ได้ลบจุดยืน ปล่อยให้ความร้อนลดพอเลือกคำตอบ อักษรนี้ชวนใช้แรงอย่างตั้งใจ มีทั้งความมั่นคงและการยับยั้ง","ar":"اختلاف الرأي لا يعني أن فيك خللًا. تستطيع امتلاك قوة حماية حدودك واختيار عدم دخول كل معركة. الهدوء ليس استسلامًا تلقائيًا، ورفض الصراع لا يمحو موقفك. دع الحرارة تهدأ كي تختار استجابتك. يدعوك الرمز إلى استخدام القوة بوعي، مع الثبات وضبط النفس."},"49":{"zh-CN":"你正在经历着一个重要的阶段，就像用四只手抬一根木头，不是在比谁力气大，而是每一只都愿意不放下来。有的时候，你在“要扛不住了”的边缘——觉得所有重量都在自己身上，别人看不见，也帮不上。人们理解的“兴”以为是显眼的存在、是盛大的场面、是一个人撑起的高光。有时候会担心，怕一松手就掉了、怕没人接得上、怕自己还不够强。“兴”并非是独角戏，你不需要一个人去完成全部。任何你需要支持的时候，交流和邀请能够让别人把手放上来。一只手会抖，四只手就稳了。你不是一个人在单方面做，你也不需要一个人做完，此刻，你是否能够识别出另外和你一起托举着的手？","zh-TW":"你正在經歷著一個重要的階段，就像用四只手抬一根木頭，不是在比誰力氣大，而是每一只都愿意不放下來。有的時候，你在“要扛不住了”的邊緣——覺得所有重量都在自己身上，別人看不見，也幫不上。人們理解的“興”以為是顯眼的存在、是盛大的場面、是一個人撐起的高光。有時候會擔心，怕一松手就掉了、怕沒人接得上、怕自己還不夠強。“興”并非是獨角戲，你不需要一個人去完成全部。任何你需要支持的時候，交流和邀請能夠讓別人把手放上來。一只手會抖，四只手就穩了。你不是一個人在單方面做，你也不需要一個人做完，此刻，你是否能夠識別出另外和你一起托舉著的手？","en":"What you are carrying need not become a solo performance. When the weight feels invisible to everyone else, conversation and an invitation can make support possible. Imagine several hands lifting one beam: their shared willingness matters more than a contest of strength. Look for the hands already beside yours, and consider where another could join. You do not have to finish everything alone to make your contribution meaningful.","ja":"担っていることを、ひとりの舞台にしなくても大丈夫です。重さが誰にも見えないと感じるとき、話し、招くことで支えが生まれることがあります。一本の梁を複数の手で持つように、力比べより共に持つ意思を。隣にある手と、加われる手を探してください。貢献を意味あるものにするために、全部をひとりで終える必要はありません。","th":"สิ่งที่แบกไม่ต้องเป็นการแสดงเดี่ยว เมื่อรู้สึกไม่มีใครเห็นน้ำหนัก การคุยและชวนช่วยอาจเปิดทาง นึกถึงหลายมือยกไม้เดียวกัน ความเต็มใจร่วมสำคัญกว่าแข่งแรง มองหามือที่อยู่ข้างคุณแล้วและที่อาจเข้าร่วม คุณไม่ต้องทำทั้งหมดคนเดียวเพื่อให้ส่วนร่วมมีความหมาย","ar":"ما تحمله لا يلزم أن يصبح عرضًا فرديًا. حين يبدو العبء غير مرئي، قد يفتح الحوار وطلب المشاركة باب الدعم. تخيّل أيدي ترفع عارضة واحدة؛ الاستعداد المشترك أهم من منافسة القوة. انظر إلى الأيدي بجوارك وإلى من يمكنه الانضمام. لا تحتاج إلى إنهاء كل شيء وحدك لتكون مساهمتك ذات معنى."},"50":{"zh-CN":"应接不暇的问题，是磨砺心性的必要养分，你正在快速的成长迭代。在“解不开”的时刻，心生烦躁是正常的，这是你想把事做好的善意。问题堆在一起，越理越乱，越使劲越紧的时候，不妨停下来。“解”不是用莽力、不是硬拆、不是不放过每一个细节。这个符号告诉你，一把再小的刀刃，只要找准的关键点，轻松就能挑开最重要的那个结。解，不需要拆掉所有绳子，而是先静心观察，找到可以松动的那个关键点。怕漏了哪个环节、怕自己不够聪明、怕解不开就等同于自己不行，放下对自己必须面面俱到的维护。再乱的线，也只有两个线头，正着不行，反着也可以试试。此时，你在问题的哪个端头用力？","zh-TW":"應接不暇的問題，是磨礪心性的必要養分，你正在快速的成長迭代。在“解不開”的時刻，心生煩躁是正常的，這是你想把事做好的善意。問題堆在一起，越理越亂，越使勁越緊的時候，不妨停下來。“解”不是用莽力、不是硬拆、不是不放過每一個細節。這個符號告訴你，一把再小的刀刃，只要找準的關鍵點，輕松就能挑開最重要的那個結。解，不需要拆掉所有繩子，而是先靜心觀察，找到可以松動的那個關鍵點。怕漏了哪個環節、怕自己不夠聰明、怕解不開就等同于自己不行，放下對自己必須面面俱到的維護。再亂的線，也只有兩個線頭，正著不行，反著也可以試試。此時，你在問題的哪個端頭用力？","en":"When a knot tightens the harder you pull, pause before adding more force. Solving something does not always require dismantling every thread. A small opening at the right point can release the whole pattern. Frustration shows that you want this to work, not that you lack intelligence. Look from the other end if necessary. Ask which part can loosen now, rather than requiring yourself to master every detail at once.","ja":"引くほど結び目が締まるなら、力を足す前に止まってください。解くことは、すべての糸をばらすことではありません。要所の小さな隙間から全体が緩むこともあります。苛立ちは、よくしたい気持ちの表れで、知性の不足ではありません。反対側からも見てください。全部を一度に理解するより、今緩められる一点を探して。","th":"ถ้ายิ่งดึงปมยิ่งแน่น หยุดก่อนเพิ่มแรง การแก้ไม่ต้องรื้อด้ายทุกเส้น ช่องเล็กในจุดที่ใช่อาจคลายทั้งรูปแบบ หงุดหงิดบอกว่าอยากให้ดี ไม่ได้แปลว่าไม่ฉลาด ลองมองอีกปลายเมื่อจำเป็น ถามว่าส่วนไหนคลายได้ตอนนี้ แทนบังคับให้ควบคุมทุกละเอียดพร้อมกัน","ar":"حين تشتد العقدة كلما سحبت، توقف قبل زيادة القوة. الحل لا يستلزم تفكيك كل خيط. فتحة صغيرة في الموضع المناسب قد ترخي النمط كله. الإحباط يدل على رغبتك في النجاح لا نقص الذكاء. انظر من الطرف الآخر عند الحاجة. اسأل عمّا يمكن إرخاؤه الآن بدل إتقان كل التفاصيل مرة واحدة."},"51":{"zh-CN":"你或许在追求“平静”——不许自己生气、不许自己低落、不许心里有波澜。“平”并非是一条直线、没有情绪，永远不偏不倚。这个符号，有着横向的平稳，也有拔地而起的蜿蜒，以及来自左右的飞沙走石。经历过“不平”才能体悟“平”。平，不是恒久的均匀，而是允许事物如其所是，该高的高，该低的低，该多的多，该少的少。怕自己起伏的波动、怕被人觉得不稳、怕打破均匀的常规。这份怕，源自相信“平”必须是平的。平，是你允许自己高，也允许自己低。不是极力拉平差距，而是在有着明显差异的时候，也能护住内心的“平”。在心绪起伏之后，知道回到水平的状态。这份觉察，令你在高的时候不飘，低的时候不慌。就像无处安放的一口气，堵着就不平。散了，就均匀了。","zh-TW":"你或許在追求“平靜”——不許自己生氣、不許自己低落、不許心里有波瀾。“平”并非是一條直線、沒有情緒，永遠不偏不倚。這個符號，有著橫向的平穩，也有拔地而起的蜿蜒，以及來自左右的飛沙走石。經歷過“不平”才能體悟“平”。平，不是恒久的均勻，而是允許事物如其所是，該高的高，該低的低，該多的多，該少的少。怕自己起伏的波動、怕被人覺得不穩、怕打破均勻的常規。這份怕，源自相信“平”必須是平的。平，是你允許自己高，也允許自己低。不是極力拉平差距，而是在有著明顯差異的時候，也能護住內心的“平”。在心緒起伏之后，知道回到水平的狀態。這份覺察，令你在高的時候不飄，低的時候不慌。就像無處安放的一口氣，堵著就不平。散了，就均勻了。","en":"Calm is not a rule against anger, sadness or changes in feeling. A living landscape has heights and hollows. Balance can mean allowing those differences while knowing how to return to your centre. You do not need to flatten every rise or fear every low point. Notice the movement, make room for it and let a held breath loosen. Awareness can keep a high from carrying you away and a low from defining everything.","ja":"平静は、怒りや悲しみ、気持ちの変化を禁止する規則ではありません。生きた風景には高低があります。その違いを認めながら、中心へ戻る方法を知ることもバランスです。上がり下がりをすべて均す必要はありません。動きに気づき、余地を作り、詰めた息を緩めて。高いときも低いときも、それだけが自分のすべてではありません。","th":"สงบไม่ใช่กฎห้ามโกรธ เศร้า หรือเปลี่ยนอารมณ์ ภูมิประเทศที่มีชีวิตมีทั้งสูงและต่ำ สมดุลอาจคือยอมให้ต่างพร้อมรู้ทางกลับสู่กลาง ไม่ต้องทำทุกยอดให้ราบหรือกลัวทุกจุดต่ำ สังเกตการเคลื่อนไหว เปิดที่ให้มัน และคลายลมหายใจที่กลั้น การรู้ตัวช่วยไม่ให้ช่วงสูงพัดพา หรือช่วงต่ำนิยามทุกอย่าง","ar":"الهدوء ليس منعًا للغضب أو الحزن أو تغير الشعور. للمشهد الحي مرتفعات ومنخفضات. التوازن قد يعني السماح بالفروق مع معرفة طريق العودة إلى مركزك. لا تُسطّح كل ارتفاع ولا تخشَ كل انخفاض. لاحظ الحركة وافسح لها المجال وأرخِ النفس المحتبس. الوعي يمنع القمة أو القاع من تعريفك كله."},"52":{"zh-CN":"你或许在“还能再相信吗”的犹豫里——被辜负过、被冷落过、被承诺又落空过，这都不是你的错。“孚”并非是对方的回应、不是从不会落空的等待，不是从未缺席的如愿。这个符号告诉你，一只手，留在同一个的位置，不论阴晴圆缺从不松开。孚，不是你得到了相等的回应。是你优先已经决定了：我不会放。怕再信一次又会落空、怕自己太傻、怕守护到最后只剩自己。这份怕，是你太相信“孚”必须两个人。孚，是一个人的守护，心甘情愿且不求回应。只去如如不动地完成自己想做的过程。不会因为对方变了，你就收。信，是孤独着的大爱。","zh-TW":"你或許在“還能再相信嗎”的猶豫里——被辜負過、被冷落過、被承諾又落空過，這都不是你的錯。“孚”并非是對方的回應、不是從不會落空的等待，不是從未缺席的如愿。這個符號告訴你，一只手，留在同一個的位置，不論陰晴圓缺從不松開。孚，不是你得到了相等的回應。是你優先已經決定了：我不會放。怕再信一次又會落空、怕自己太傻、怕守護到最后只剩自己。這份怕，是你太相信“孚”必須兩個人。孚，是一個人的守護，心甘情愿且不求回應。只去如如不動地完成自己想做的過程。不會因為對方變了，你就收。信，是孤獨著的大愛。","en":"After disappointment, wondering whether you can trust again is understandable. This reading turns attention toward the commitment you freely choose, rather than a guarantee of equal response. What do you still wish to care for, and what does keeping faith mean to you? Such care need not be a bargain or proof of foolishness. Let it remain a conscious choice, made with an honest view of your own willingness and limits.","ja":"失望のあと、もう一度信じられるか迷うのは自然です。この解釈は、同じだけ返ってくる保証より、自分が自由に選ぶ誠実さへ目を向けます。何をまだ大切にしたいのか、信じ続けることは自分に何を意味するのか。思いを交換や愚かさの証明にしなくて大丈夫。自分の意思と限界を正直に見ながら、意識して選ぶものにしてください。","th":"หลังผิดหวัง ลังเลว่าจะเชื่อใจอีกได้ไหมเป็นเรื่องเข้าใจได้ คำอธิบายนี้ชวนมองความผูกพันที่คุณเลือกเอง แทนรับประกันว่าจะตอบกลับเท่ากัน ยังอยากดูแลอะไร และรักษาความเชื่อหมายถึงอะไรต่อคุณ การใส่ใจไม่ต้องเป็นข้อต่อรองหรือหลักฐานว่าโง่ ให้เป็นทางเลือกที่รู้ตัว ซื่อตรงกับความเต็มใจและขอบเขตของตัวเอง","ar":"بعد الخيبة، من المفهوم أن تتساءل عن الثقة مجددًا. يوجّه هذا التأمل النظر إلى الالتزام الذي تختاره بحرية، لا ضمان الاستجابة المتساوية. ما الذي ما زلت تريد رعايته، وماذا يعني الوفاء لك؟ ليس الاهتمام مقايضة أو دليل سذاجة. ليبقَ اختيارًا واعيًا يرى رغبتك وحدودك بصدق."},"53":{"zh-CN":"刀收在鞘里，不是没有力，是不必让每个人都知道你有多利。不是藏起来，待时而动。你或许在“要不要表现自己”之间犹豫——太突出怕被嫉妒，太张扬怕被模仿，太安静怕被遗忘。“谦”并非是低头、退让，或把光芒让给别人。这个符号是成熟的麦穗低头不语，由旁人去自由言说。强者才有资本谦，不再依峙外界的评价体系来认出自己的优秀。谦，不是你不够好，相反，是你已足够好，但并不急着让所有人知道。怕被忽视、怕机会溜走、怕不争就得不到，是你认定了“谦”等同于“失去”。谦，是你知道自己的分量，但你拿自己擅长的部分往别人的不足上去压。让它在时光里，自己说话，娓娓道来，收放自如。","zh-TW":"刀收在鞘里，不是沒有力，是不必讓每個人都知道你有多利。不是藏起來，待時而動。你或許在“要不要表現自己”之間猶豫——太突出怕被嫉妒，太張揚怕被模仿，太安靜怕被遺忘。“謙”并非是低頭、退讓，或把光芒讓給別人。這個符號是成熟的麥穗低頭不語，由旁人去自由言說。強者才有資本謙，不再依峙外界的評價體系來認出自己的優秀。謙，不是你不夠好，相反，是你已足夠好，但并不急著讓所有人知道。怕被忽視、怕機會溜走、怕不爭就得不到，是你認定了“謙”等同于“失去”。謙，是你知道自己的分量，但你拿自己擅長的部分往別人的不足上去壓。讓它在時光里，自己說話，娓娓道來，收放自如。","en":"A blade in its sheath has not lost its edge. Humility can come from knowing your own weight rather than waiting for everyone to recognise it. You need not make yourself smaller or press your strengths against another person’s weaknesses. Let the work speak in its own time. Choosing when to reveal your ability can be confidence, not disappearance, and quiet need not mean that you have nothing to offer.","ja":"鞘に収まった刃も、力を失ってはいません。謙虚さは、皆に認めてもらう前に自分の重みを知ることから生まれます。自分を小さくしたり、得意なことで相手の弱さを圧したりしなくてよいのです。仕事が時間の中で語る余地を。力を見せる時を選ぶ静けさは、消えることではなく、自信でもあります。","th":"คมที่อยู่ในฝักไม่ได้เสียความคม ความถ่อมตนอาจมาจากรู้คุณค่าตัวเองโดยไม่รอให้ทุกคนเห็น ไม่ต้องทำตัวเล็กหรือใช้จุดแข็งกดจุดอ่อนใคร ให้งานพูดตามเวลา เลือกเวลาแสดงความสามารถเป็นความมั่นใจ ไม่ใช่หายไป และเงียบไม่ได้แปลว่าไม่มีอะไรให้","ar":"النصل في غمده لم يفقد حدّه. قد ينبع التواضع من معرفة قيمتك بدل انتظار اعتراف الجميع. لا تصغّر نفسك ولا تضغط بقوتك على ضعف غيرك. دع العمل يتحدث في وقته. اختيار وقت إظهار القدرة ثقة لا اختفاء، والهدوء لا يعني خلوّ اليد."},"54":{"zh-CN":"这并不是一个轻松的过程，好在你已经完好无缺地走到了这一刻，将这份肯定和欣赏给到你自己。应接不暇的人和事等待你去处理，疲惫是身体报警的信号，提醒你在忙碌中腾挪片刻的独处。“太累了”，意味着你接住了太多、背了太多、记了太多、放了太多，一个都不能落下。此时的“累”是包袱、是疲惫、是拖累、是渴望轻松。这个符号，有大量的绳结，不是为了来绑住你，是用来铭记。累，不是堆积了负担，是你把走过重要的路，都好好系住。怕停下就失控，怕放下就忘了、怕轻了就辜负曾经的努力、怕“不累”就是不负责。“累”不是永远都是苦的，它的回甘在时间长河的另一个端头，那一刻的甘甜终将回应你，我没白走。","zh-TW":"這并不是一個輕松的過程，好在你已經完好無缺地走到了這一刻，將這份肯定和欣賞給到你自己。應接不暇的人和事等待你去處理，疲憊是身體報警的信號，提醒你在忙碌中騰挪片刻的獨處。“太累了”，意味著你接住了太多、背了太多、記了太多、放了太多，一個都不能落下。此時的“累”是包袱、是疲憊、是拖累、是渴望輕松。這個符號，有大量的繩結，不是為了來綁住你，是用來銘記。累，不是堆積了負擔，是你把走過重要的路，都好好系住。怕停下就失控，怕放下就忘了、怕輕了就辜負曾經的努力、怕“不累”就是不負責。“累”不是永遠都是苦的，它的回甘在時間長河的另一個端頭，那一刻的甘甜終將回應你，我沒白走。","en":"You have carried, remembered and managed a great deal. Fatigue can be a signal to make room for yourself, not proof that you are failing. The knots in this symbol can hold memories of important paths as well as weight. You need not keep suffering to prove those efforts mattered. A little rest does not erase what you have lived or learned. Acknowledge the work already done and consider what can be set down for now.","ja":"多くを担い、覚え、整えてきたのですね。疲れは失敗の証明ではなく、自分の場所を空ける合図でもあります。この字の結び目は、重さだけでなく大切な道の記憶も留めます。努力の価値を示すため、苦しみ続ける必要はありません。少し休んでも、経験や学びは消えません。してきたことを認め、今置けるものを考えてください。","th":"คุณแบก จดจำ และจัดการมามาก ความเหนื่อยอาจเป็นสัญญาณให้มีที่เพื่อตัวเอง ไม่ใช่ล้มเหลว ปมในอักษรเก็บความทรงจำเส้นทางสำคัญพร้อมน้ำหนัก ไม่ต้องทนต่อเพื่อพิสูจน์ว่าความพยายามมีค่า พักนิดไม่ได้ลบสิ่งที่ผ่านหรือเรียนรู้ รับรู้สิ่งที่ทำแล้วและลองดูว่าอะไรพักวางได้ตอนนี้","ar":"حملت وتذكّرت وأدرت الكثير. التعب قد يكون إشارة لإفساح مكان لنفسك، لا دليل فشل. عُقد الرمز تحمل ذكريات طرق مهمة إلى جانب الوزن. لا تحتاج إلى استمرار المعاناة لإثبات قيمة الجهد. الراحة لا تمحو الخبرة أو التعلم. اعترف بالعمل المنجز وانظر فيما يمكن وضعه جانبًا الآن."},"55":{"zh-CN":"现实没有提供更多你想要的选择，这个阶段的拥有是保护，也是禁锢。“被卡住”的感觉是在提醒，你的生长速度已经超出了现有的环境，你需要为自己创造更宽广的空间，安放这股力量。怕自己永远出不去、怕努力都是白费、怕这间屋子就是结局，出不去、进不来、四面都是限制的时候，“困”似乎是绝境、是无路、是种对现状的爱莫能助。这个符号，是一间临时的小屋，在四周包围的同时，也留有着缝隙。光从哪里进来，哪里就是路径，风在哪里流动，哪里就是出口。假设你是一株植物，哪些瞬间让你体验到了喜欢的“光”？","zh-TW":"現實沒有提供更多你想要的選擇，這個階段的擁有是保護，也是禁錮。“被卡住”的感覺是在提醒，你的生長速度已經超出了現有的環境，你需要為自己創造更寬廣的空間，安放這股力量。怕自己永遠出不去、怕努力都是白費、怕這間屋子就是結局，出不去、進不來、四面都是限制的時候，“困”似乎是絕境、是無路、是種對現狀的愛莫能助。這個符號，是一間臨時的小屋，在四周包圍的同時，也留有著縫隙。光從哪里進來，哪里就是路徑，風在哪里流動，哪里就是出口。假設你是一株植物，哪些瞬間讓你體驗到了喜歡的“光”？","en":"Feeling confined may suggest that what once protected you no longer has enough space for your growth. This room is not necessarily the end of the story. Notice its gaps: where light enters, where air moves, where a possibility remains. If you were a plant, which moments would feel like the light you need? You do not have to solve every limitation today to begin recognising a direction toward more room.","ja":"閉じ込められた感じは、かつて守ってくれた環境が、今の成長には狭いという知らせかもしれません。この部屋が物語の終わりとは限りません。光や風が入る隙間、残る可能性を探してください。植物だとしたら、どんな瞬間が必要な光に感じられるでしょう。すべての制約を今日解かなくても、広さへ向かう方向には気づけます。","th":"รู้สึกติดอาจบอกว่าสิ่งที่เคยปกป้องเริ่มแคบเกินการเติบโต ห้องนี้ไม่จำเป็นต้องเป็นตอนจบ ดูช่องว่าง แสงเข้าที่ไหน ลมผ่านที่ใด ยังมีอะไรเป็นไปได้ ถ้าเป็นพืช ช่วงไหนเหมือนแสงที่ต้องการ ไม่ต้องแก้ทุกข้อจำกัดวันนี้เพื่อเริ่มเห็นทางสู่พื้นที่กว้างขึ้น","ar":"قد يعني الضيق أن ما حماك سابقًا لم يعد يتّسع لنموك. الغرفة ليست بالضرورة نهاية القصة. لاحظ شقوقها: أين يدخل الضوء ويتحرك الهواء وتبقى إمكانية؟ لو كنت نباتًا، أي لحظات تشبه الضوء الذي تحتاجه؟ لا يلزم حل كل قيد اليوم كي تلمح اتجاهًا إلى مساحة أوسع."},"56":{"zh-CN":"你所重视的这件事情，是一件有着独特意义的长期工程。不必急着看到“成果”——房子要快一点盖好、事情要快一点做成、自己要快一点变成想成为的样子。 “建”并不是高度、速度，也不是看得见的拔地而起。“建”这个符号，是一只手拿着工具，一下一下夯实地基。建，不是往上冲，反而是往下稳。你在过程之中有任何的期待，都是对它的珍视，没有人比你更清楚这个“工程”的意义。同时，也怕慢了就来不及、怕别人已经盖好了你还在打地基、怕这一下一下的重复没有意义。这份怕，是你默认了“快”才是对的、正确的。建，不是你加了多少层，是当你踩上去的时候，脚下稳稳的扎实不晃。","zh-TW":"你所重視的這件事情，是一件有著獨特意義的長期工程。不必急著看到“成果”——房子要快一點蓋好、事情要快一點做成、自己要快一點變成想成為的樣子。 “建”并不是高度、速度，也不是看得見的拔地而起。“建”這個符號，是一只手拿著工具，一下一下夯實地基。建，不是往上沖，反而是往下穩。你在過程之中有任何的期待，都是對它的珍視，沒有人比你更清楚這個“工程”的意義。同時，也怕慢了就來不及、怕別人已經蓋好了你還在打地基、怕這一下一下的重復沒有意義。這份怕，是你默認了“快”才是對的、正確的。建，不是你加了多少層，是當你踩上去的時候，腳下穩穩的扎實不晃。","en":"What matters to you may be a long construction, not a quick display of height. A hand steadily compacting the ground can be doing essential work even when little rises above it. Comparing your foundation with someone else’s finished building hides that work. You know why this project matters. Give the repeated movements their place, and ask whether the ground beneath you is becoming sound rather than only counting how many floors you have added.","ja":"大切なことは、高さをすぐ見せるより、長く築く仕事なのかもしれません。地面を一つずつ固める手は、上に何も見えなくても重要な仕事をしています。他人の完成した建物と比べると、基礎が見えなくなります。何のために築くかは自分が知っています。階数だけでなく、足元が確かになっているかを見て、繰り返す動きにも場所を与えてください。","th":"สิ่งสำคัญอาจเป็นงานสร้างระยะยาว ไม่ใช่โชว์ความสูงเร็ว ๆ มือที่ค่อย ๆ อัดดินกำลังทำงานจำเป็น แม้ยังไม่เห็นสิ่งตั้งขึ้น เทียบฐานรากตัวเองกับตึกเสร็จของคนอื่นบังงานนั้น คุณรู้ว่าโครงการนี้มีความหมายอย่างไร ให้การทำซ้ำมีค่า แล้วถามว่าพื้นใต้เท้าแน่นขึ้นไหม แทนนับแต่ชั้นที่เพิ่ม","ar":"ما يهمك قد يكون بناءً طويلًا لا عرضًا سريعًا للارتفاع. اليد التي تثبّت الأرض تؤدي عملًا أساسيًا ولو لم يرتفع شيء بعد. مقارنة أساسك ببناء غيرك المكتمل تحجب العمل. أنت تعرف معنى المشروع. امنح التكرار قيمته، واسأل عن متانة الأرض تحتك لا عدد الطوابق وحده."},"57":{"zh-CN":"丰富的持有并不能带来暂时的歇息，直到你遇到了这个“有”的符号。\n\n感到“不够”令人焦虑——看别人有的，自己没有；看过去有的，现在少了；看未来可能有的，怕赶不上。“有”并不是更多、更满、比别人多才算数。这个符号，意味着持有的另一端有一个对等的力量。当下多少的力量，能够举起多少的份量。“有”并非是某个具体的读数。是任何时候，可以拿起、放下的手臂，是选择的自由。有，是力量增长之后，水到渠成的如愿在握。","zh-TW":"豐富的持有并不能帶來暫時的歇息，直到你遇到了這個“有”的符號。\n\n感到“不夠”令人焦慮——看別人有的，自己沒有；看過去有的，現在少了；看未來可能有的，怕趕不上。“有”并不是更多、更滿、比別人多才算數。這個符號，意味著持有的另一端有一個對等的力量。當下多少的力量，能夠舉起多少的份量。“有”并非是某個具體的讀數。是任何時候，可以拿起、放下的手臂，是選擇的自由。有，是力量增長之后，水到渠成的如愿在握。","en":"Having more does not always quiet the feeling of not having enough. This symbol invites a different view of possession: the strength to hold something and the freedom to put it down. What can your present capacity comfortably carry? “Having” need not be a number that exceeds everyone else’s. It can be a relationship between what you hold, what supports you and the choices still available to you.","ja":"多く持っても、足りない感覚が静まるとは限りません。この文字は、持つ力と置く自由から所有を見直す招待です。今の自分に、無理なく持てるのはどれくらいでしょう。「有る」は、人を上回る数字だけではありません。持つもの、支える力、残っている選択肢の関係としても感じられます。","th":"มีมากไม่ได้ทำให้ความไม่พอเงียบเสมอ อักษรนี้ชวนมองการมีอีกแบบ คือแรงที่จะถือและอิสระที่จะวาง ตอนนี้กำลังคุณรองรับอะไรได้สบาย “มี” ไม่ต้องเป็นตัวเลขมากกว่าทุกคน แต่อาจเป็นความสัมพันธ์ระหว่างสิ่งที่ถือ สิ่งที่รองรับ และทางเลือกที่ยังมี","ar":"امتلاك المزيد لا يهدّئ دائمًا شعور النقص. يدعوك الرمز إلى رؤية أخرى للامتلاك: قوة الحمل وحرية الوضع. ماذا تستطيع قدرتك الحالية حمله براحة؟ «الامتلاك» ليس رقمًا يتجاوز الآخرين، بل علاقة بين ما تمسكه وما يسندك والخيارات المتاحة."},"58":{"zh-CN":"走的路多了、长了，遇到的阻碍也会变多了。你所遇到的障碍，都是对体能的训练。你或许在等“事事顺遂”的信号——等条件成熟、等阻碍消失、等一切准备好再出发。 “亨”并不是永远的畅通无阻、也不是天时地利人和的完美成全。这个符号，是一个静置的空间，在你所有上路的行囊中，是否也带上了能被对方感受到的敬意。亨，不是路自己通的，而是你用敬意，敲开了门。怕走错、怕不通、怕没有好的结果，这些担忧让这段路走起来犹犹豫豫。唯有你的脚步没有卡顿，敬意才能被慷慨地感知。当你保持这样的状态临在，通就发生了。","zh-TW":"走的路多了、長了，遇到的阻礙也會變多了。你所遇到的障礙，都是對體能的訓練。你或許在等“事事順遂”的信號——等條件成熟、等阻礙消失、等一切準備好再出發。 “亨”并不是永遠的暢通無阻、也不是天時地利人和的完美成全。這個符號，是一個靜置的空間，在你所有上路的行囊中，是否也帶上了能被對方感受到的敬意。亨，不是路自己通的，而是你用敬意，敲開了門。怕走錯、怕不通、怕沒有好的結果，這些擔憂讓這段路走起來猶猶豫豫。唯有你的腳步沒有卡頓，敬意才能被慷慨地感知。當你保持這樣的狀態臨在，通就發生了。","en":"Waiting for every obstacle to vanish can keep the journey from beginning. A way through may open through the respect and presence you bring, rather than perfect conditions. Ask whether your approach allows the other person to feel that respect. Uncertainty can remain while you still take a thoughtful step. Passage is not always something the world supplies in advance; sometimes it grows through the way you meet it.","ja":"障害が全部消えるのを待つと、旅が始まらないことがあります。道は完璧な条件ではなく、持っていく敬意や姿勢から開くこともあります。相手に敬意が届く関わり方か、確かめてください。不確かさが残っていても、丁寧な一歩は選べます。通り道は、あらかじめ用意されるだけでなく、出会い方から生まれることもあります。","th":"รอให้ทุกอุปสรรคหายอาจทำให้ไม่เริ่มทาง ช่องผ่านอาจเปิดจากความเคารพและการอยู่ตรงนั้น ไม่ใช่เงื่อนไขสมบูรณ์ ลองถามว่าวิธีเข้าหาทำให้อีกคนรู้สึกถึงความเคารพไหม ความไม่แน่นอนอยู่ได้พร้อมก้าวอย่างคิดใคร่ครวญ ทางไม่ได้มีให้ล่วงหน้าเสมอ บางครั้งเกิดจากวิธีที่คุณพบโลก","ar":"انتظار زوال كل عائق قد يمنع البداية. ربما يفتح الاحترام والحضور طريقًا أكثر من الظروف المثالية. اسأل إن كان الآخر يشعر بالاحترام في طريقتك. يمكن لعدم اليقين أن يبقى فيما تخطو بعناية. الممر ليس دائمًا جاهزًا؛ أحيانًا ينشأ من طريقة لقائك بالعالم."},"59":{"zh-CN":"此刻，你正处于一段新的际遇之中，在新鲜之余也有了更多的思考，这些思考并非没有必要的操心，恰恰是告诉你，自己对当下的珍视。你或许在找“对的位置”——这份工作适合我吗？这段关系对吗？我该留在这里吗？“宜”并不是标准答案，不是外界认证，也不是终于找到的归属。可这个符号告诉你，物品已经放在了合适的位置上，不偏不倚，不多不少。你的存在已被安全地承接住。宜，不是你找对了地方，而是当你专心地站在那里，那个地方就对了。怕站错队、怕选错路、怕“不合适”三个字落在自己头上。这份怕，是你太相信“宜”必须由别人点头。宜，不是你去够一个位置，贴近某个标准。而是你带着对自己的认可与相信，站在那里，不躲，不颤，不争，不抢，位置就稳了。你不是要找“该去的地方”。你去了，那里就该是你。","zh-TW":"此刻，你正處于一段新的際遇之中，在新鮮之余也有了更多的思考，這些思考并非沒有必要的操心，恰恰是告訴你，自己對當下的珍視。你或許在找“對的位置”——這份工作適合我嗎？這段關系對嗎？我該留在這里嗎？“宜”并不是標準答案，不是外界認證，也不是終于找到的歸屬。可這個符號告訴你，物品已經放在了合適的位置上，不偏不倚，不多不少。你的存在已被安全地承接住。宜，不是你找對了地方，而是當你專心地站在那里，那個地方就對了。怕站錯隊、怕選錯路、怕“不合適”三個字落在自己頭上。這份怕，是你太相信“宜”必須由別人點頭。宜，不是你去夠一個位置，貼近某個標準。而是你帶著對自己的認可與相信，站在那里，不躲，不顫，不爭，不搶，位置就穩了。你不是要找“該去的地方”。你去了，那里就該是你。","en":"In a new situation, questioning where you belong can show how much you care. Suitability is not always a certificate someone else gives you. Notice what changes when you stand somewhere with attention and self-respect rather than stretching toward a borrowed standard. You can explore whether a place supports you while also recognising what your presence brings to it. Belonging can begin with allowing yourself to be here.","ja":"新しい状況で居場所を問い直すのは、大切にしているからかもしれません。ふさわしさは、他人からもらう証明書だけではありません。借りた基準へ背伸びする代わりに、注意と自尊心を持って立つと何が変わるでしょう。場所が自分を支えるか確かめながら、自分の存在がそこにもたらすものも認めてください。ここにいてよいと許すことから、居場所が始まることもあります。","th":"อยู่สถานการณ์ใหม่แล้วถามว่าเหมาะตรงไหนอาจเพราะคุณใส่ใจ ความเหมาะไม่ได้เป็นใบรับรองจากคนอื่นเสมอ สังเกตว่าอะไรเปลี่ยนเมื่อยืนด้วยความใส่ใจและเคารพตัวเอง แทนเอื้อมตามมาตรฐานที่ยืมมา คุณสำรวจได้ว่าที่นั้นรองรับคุณไหม พร้อมเห็นสิ่งที่การมีอยู่ของคุณนำมา การเป็นส่วนหนึ่งอาจเริ่มจากอนุญาตให้ตัวเองอยู่ตรงนี้","ar":"التساؤل عن مكانك في موقف جديد قد يدل على اهتمامك. الملاءمة ليست شهادة يمنحها الآخرون دائمًا. لاحظ ما يتغير حين تقف بانتباه واحترام لنفسك بدل التمدد نحو معيار مستعار. افحص ما إذا كان المكان يسندك، واعترف بما يضيفه وجودك. قد يبدأ الانتماء بالسماح لنفسك بأن تكون هنا."},"60":{"zh-CN":"风来，树就摇。不是为谁好看，是风来了，它不能不摇。你也是，有些表达，不是为了被看见，是到了该动的时候。\n\n你或许在“要不要表现自己”之间犹豫——怕被笑、怕不好看、怕太另类，怕被评头论足，怕没人能懂。“舞”不是表演、取悦，也不一定要有观众。舞，是对真实感受的自由释放，只为完成自我的表达。只管尽情释放此刻的自由，不是在表演给谁看，而是在回应此刻真实的力量。当身体里吹起了风，便不用再克制它的方向。","zh-TW":"風來，樹就搖。不是為誰好看，是風來了，它不能不搖。你也是，有些表達，不是為了被看見，是到了該動的時候。\n\n你或許在“要不要表現自己”之間猶豫——怕被笑、怕不好看、怕太另類，怕被評頭論足，怕沒人能懂。“舞”不是表演、取悅，也不一定要有觀眾。舞，是對真實感受的自由釋放，只為完成自我的表達。只管盡情釋放此刻的自由，不是在表演給誰看，而是在回應此刻真實的力量。當身體里吹起了風，便不用再克制它的方向。","en":"A tree moves when the wind reaches it, not because someone is watching. Some expression can be like that: a response to what is alive within you. You do not need an audience, perfect form or everyone’s understanding before moving. Let the body answer a real feeling in a way that is comfortable for you. The gesture can belong to you without becoming a performance for approval.","ja":"木は、見られるためではなく、風が来たから揺れます。表現にも、内側の生きた感覚への応えという形があります。観客や完璧な形、全員の理解を待たなくてもよいのです。心地よい範囲で、体が本当の気持ちに応えるのを許してください。その動きは、承認のための演技ではなく、自分のものであってよいのです。","th":"ต้นไม้ไหวเมื่อลมมา ไม่ใช่เพราะมีคนดู การแสดงออกบางอย่างคือการตอบสิ่งมีชีวิตข้างใน ไม่ต้องมีผู้ชม รูปแบบสมบูรณ์ หรือทุกคนเข้าใจก่อนขยับ ให้ร่างกายตอบความรู้สึกจริงในแบบที่สบาย ท่าทางเป็นของคุณได้โดยไม่เป็นการแสดงขอการยอมรับ","ar":"تتحرك الشجرة حين يصلها الهواء لا لأن أحدًا يراقب. بعض التعبير استجابة لما يحيا داخلك. لا تحتاج إلى جمهور أو شكل مثالي أو فهم الجميع قبل الحركة. دع الجسد يجيب شعورًا حقيقيًا بطريقة مريحة لك. يمكن للحركة أن تخصك دون أن تكون عرضًا طلبًا للقبول."},"61":{"zh-CN":"一个人做不完所有的事情，合作是这个阶段的必经之路。你或许在“配合”里感到吃力——觉得别人慢、觉得自己快、觉得总对不上节奏。“协”不是放弃自己的立场，也不是让步后的跟随。“协”这个符号，是在一个独立的口号下，同时往一个方向使力。不需谁迁就谁，而是大家选了同一个“现在”，精准用动作响应那个“一起”的拍子。\n\n怕自己不合群、怕拖累别人、怕跟不上就出局，之所以顾虑，是因为想留下。 你不一定要成为力气最大的那一个，你只需要做到“一致”。比深浅重要的是，同频。","zh-TW":"一個人做不完所有的事情，合作是這個階段的必經之路。你或許在“配合”里感到吃力——覺得別人慢、覺得自己快、覺得總對不上節奏。“協”不是放棄自己的立場，也不是讓步后的跟隨。“協”這個符號，是在一個獨立的口號下，同時往一個方向使力。不需誰遷就誰，而是大家選了同一個“現在”，精準用動作響應那個“一起”的拍子。\n\n怕自己不合群、怕拖累別人、怕跟不上就出局，之所以顧慮，是因為想留下。 你不一定要成為力氣最大的那一個，你只需要做到“一致”。比深淺重要的是，同頻。","en":"Cooperation can feel difficult when everyone seems to move at a different speed. Joining does not require abandoning your position or becoming the strongest person in the group. It can mean choosing a shared moment and directing effort toward the same movement. Ask what would help you hear the common beat. A coordinated contribution may matter more than doing the most, and you do not need to complete the whole task alone.","ja":"皆の速さが違うと、協力は難しく感じられます。加わることは、自分の立場を捨てることでも、一番強くなることでもありません。同じ瞬間を選び、同じ動きに力を向けることでもあります。共通の拍子を聴くには何が役立つでしょう。量の多さより、合うタイミングが大切なこともあります。全体をひとりで終える必要はありません。","th":"ร่วมมืออาจยากเมื่อทุกคนเหมือนเร็วต่างกัน เข้าร่วมไม่ต้องทิ้งจุดยืนหรือเป็นคนแรงสุด แต่อาจเลือกช่วงเวลาร่วมและใช้แรงในทิศเดียว ถามว่าอะไรช่วยให้ได้ยินจังหวะร่วม ส่วนร่วมที่ประสานกันอาจสำคัญกว่าทำมากที่สุด และไม่ต้องทำงานทั้งหมดคนเดียว","ar":"قد تصعب المشاركة حين تختلف السرعات. الانضمام لا يفرض ترك موقفك أو أن تكون الأقوى. قد يعني اختيار لحظة مشتركة وتوجيه الجهد للحركة نفسها. ما الذي يساعدك على سماع الإيقاع المشترك؟ التنسيق قد يكون أهم من فعل الأكثر، ولا يلزم إكمال المهمة وحدك."},"62":{"zh-CN":"这个阶段你体验过了一个人的时刻，没有热闹的寒暄，有着不需要随时回应的自由。“一个人”久了也会感到慌张——怕被落下、怕不合群、怕没人对话久了就脱离社会。“独”并非孤独、冷清，它不是应该被填满的空。这个符号代表，一只旷野上强大的兽，独自走着。它不活在热闹和拥挤里，不被外界的期待所驱使，它不需要结队，只是踏出自由的每一步。独，不是没有同伴，自己就是一支队伍。独，不是缺失，却是种富足，这是不再依赖外界也能自给自足的丰盛。独，往往孕育着过人的才华。那些独自闻风、听雨、踩自己的影子的时光，正在不慌不忙地引领你走在不从众的阔路上。","zh-TW":"這個階段你體驗過了一個人的時刻，沒有熱鬧的寒暄，有著不需要隨時回應的自由。“一個人”久了也會感到慌張——怕被落下、怕不合群、怕沒人對話久了就脫離社會。“獨”并非孤獨、冷清，它不是應該被填滿的空。這個符號代表，一只曠野上強大的獸，獨自走著。它不活在熱鬧和擁擠里，不被外界的期待所驅使，它不需要結隊，只是踏出自由的每一步。獨，不是沒有同伴，自己就是一支隊伍。獨，不是缺失，卻是種富足，這是不再依賴外界也能自給自足的豐盛。獨，往往孕育著過人的才華。那些獨自聞風、聽雨、踩自己的影子的時光，正在不慌不忙地引領你走在不從眾的闊路上。","en":"Time alone can hold freedom as well as unease. Solitude is not necessarily an empty space that must be filled or proof that you do not belong. Imagine an animal crossing open land in its own stride. Quiet time to hear rain, notice wind or follow your shadow can nourish a way of living that is yours. Company remains possible, but your own presence can also be a source of fullness.","ja":"ひとりの時間には、不安だけでなく自由もあります。孤独は、埋めなければならない空白や、仲間に入れない証明とは限りません。広い土地を自分の歩幅で進む動物を想像してください。雨や風、影に気づく時間が、自分らしい暮らしを育てます。人と共にいることも選べますが、自分の存在も豊かさの源になります。","th":"เวลาอยู่คนเดียวมีทั้งอิสระและไม่สบายใจ ความสันโดษไม่จำเป็นต้องเป็นช่องว่างที่ต้องเติมหรือหลักฐานว่าไม่เข้าพวก นึกถึงสัตว์เดินในทุ่งกว้างตามก้าวตัวเอง เวลาเงียบฟังฝน รู้ลม หรือมองเงา อาจหล่อเลี้ยงวิถีที่เป็นของคุณ ยังมีเพื่อนได้ แต่การอยู่กับตัวเองก็เป็นความเต็มได้","ar":"للوقت المنفرد حرية وقلق معًا. الوحدة ليست فراغًا يجب ملؤه أو دليلًا على عدم الانتماء. تخيّل حيوانًا يعبر أرضًا مفتوحة بخطوته الخاصة. سماع المطر وملاحظة الريح والظل قد يغذّي أسلوب حياة يخصك. الرفقة ممكنة، لكن حضورك لنفسك مصدر امتلاء أيضًا."},"63":{"zh-CN":"为你曾经经历的美好瞬间，感到同样的喜悦，那里一定发生过让你念念不忘的故事。同时，也为你已成定局的过往、未画完的半圆这样的“遗憾”时刻心感祝福，因为这份“遗憾”你解锁了人生完整的体验。这些瞬间的反复咀嚼，会让你在“早知如此”的漩涡里——那句话不该说、那个选择不该做、那一步不该迈。你以为“悔”是责怪、是教训、是你做的不够好，可这个符号告诉你，尽管去享受每一款经历，始终有一颗心，稳稳地在下面接住你。怕回不去、怕来不及、怕再出错，这份担忧是来提醒你，对现状并不处处如意。你无需改写过去，只需先停下来，腾挪出手，让它有空档能够再次拾起真实的意愿。需要一定的时间管理，也需要你的勇气。悔，是再次站回在自己的田地的耕耘，喜欢什么果实，就播下什么种子。不着急修改，就在此刻，去创造你希望的愿景，不需要大，从最小的单位开始。每一个“现在”，都是新的门。","zh-TW":"為你曾經經歷的美好瞬間，感到同樣的喜悅，那里一定發生過讓你念念不忘的故事。同時，也為你已成定局的過往、未畫完的半圓這樣的“遺憾”時刻心感祝福，因為這份“遺憾”你解鎖了人生完整的體驗。這些瞬間的反復咀嚼，會讓你在“早知如此”的漩渦里——那句話不該說、那個選擇不該做、那一步不該邁。你以為“悔”是責怪、是教訓、是你做的不夠好，可這個符號告訴你，盡管去享受每一款經歷，始終有一顆心，穩穩地在下面接住你。怕回不去、怕來不及、怕再出錯，這份擔憂是來提醒你，對現狀并不處處如意。你無需改寫過去，只需先停下來，騰挪出手，讓它有空檔能夠再次拾起真實的意愿。需要一定的時間管理，也需要你的勇氣。悔，是再次站回在自己的田地的耕耘，喜歡什么果實，就播下什么種子。不著急修改，就在此刻，去創造你希望的愿景，不需要大，從最小的單位開始。每一個“現在”，都是新的門。","en":"Memories can bring both delight and unfinished sadness. Replaying what you should have said or chosen may reveal that something in the present still wants care. You do not have to rewrite the past before living again. Pause and free a little room to notice what you truly want now. Return to your own ground and plant one small seed toward it. Regret can become an opening for action rather than an endless judgment.","ja":"思い出には、喜びと未完の悲しみが共にあります。言えばよかったこと、選べばよかったことが巡るとき、今もいたわりを求める部分があるのかもしれません。過去を書き換えてからでなくても、また生き始めてよいのです。止まって余地を作り、今の本当の願いを見てください。自分の土に戻り、小さな種をひとつ。後悔を、終わらない判決ではなく入口へ。","th":"ความทรงจำมีทั้งสุขและเศร้าที่ยังไม่จบ คิดซ้ำว่าควรพูดหรือเลือกอย่างไรอาจบอกว่าปัจจุบันยังมีส่วนต้องดูแล ไม่ต้องเขียนอดีตใหม่ก่อนใช้ชีวิตอีก หยุดเปิดที่เล็ก ๆ ให้เห็นสิ่งที่ต้องการจริงตอนนี้ กลับสู่ผืนดินตัวเองและปลูกเมล็ดเล็กหนึ่งเมล็ด ความเสียดายเป็นประตูสู่ลงมือได้ แทนคำตัดสินไม่จบ","ar":"تحمل الذكريات بهجة وحزنًا غير مكتمل. تكرار ما كان ينبغي قوله أو اختياره قد يكشف حاجة حاضرة للرعاية. لا يلزم إعادة كتابة الماضي قبل العيش. توقف وأفسح مكانًا لرغبتك الصادقة الآن. عد إلى أرضك وازرع بذرة صغيرة نحوها. قد يصبح الندم بابًا للفعل لا حكمًا لا ينتهي."},"64":{"zh-CN":"做一件并不擅长的事，意味着你需要花更多的耐心去练习。在一次次尝试的过程中，你或许在“做不好”的沮丧里——练了很多次还是错，努力了很久还是不够。当下的“习”重复且枯燥。小鸟在日光下一次次扑扇翅膀。不是每一次都能飞起来，有时候高，有时候低，但每一次，都在靠近天空。习，不是你终于做到了，而是你在做的过程里，已经发生着改变。沮丧和挫败，只因你太想把它做好。“习”是当下的一种体验，不是必须要看到结果。当你身处“习”的过程中，去体验过程，振翅的时候，体验振翅，重来的时候，体验重来。保持动作与愿景一致，虽慢，但能抵达。你的每一次坚持，都是在为更宽广的天空蓄力。","zh-TW":"做一件并不擅長的事，意味著你需要花更多的耐心去練習。在一次次嘗試的過程中，你或許在“做不好”的沮喪里——練了很多次還是錯，努力了很久還是不夠。當下的“習”重復且枯燥。小鳥在日光下一次次撲扇翅膀。不是每一次都能飛起來，有時候高，有時候低，但每一次，都在靠近天空。習，不是你終于做到了，而是你在做的過程里，已經發生著改變。沮喪和挫敗，只因你太想把它做好。“習”是當下的一種體驗，不是必須要看到結果。當你身處“習”的過程中，去體驗過程，振翅的時候，體驗振翅，重來的時候，體驗重來。保持動作與愿景一致，雖慢，但能抵達。你的每一次堅持，都是在為更寬廣的天空蓄力。","en":"Learning something unfamiliar asks for patience. Repeated attempts may feel dull or discouraging, but a bird’s wingbeat matters before it can stay in the sky. Change is already happening within the practice, not only at the final success. Feel the movement while moving, and the restart while beginning again. Keep the action connected to your intention. Each return can build capacity without needing to prove everything today.","ja":"慣れないことを学ぶには、辛抱強さがいります。繰り返しが退屈で、うまくいかなくても、鳥の羽ばたきは飛べる前から意味を持ちます。変化は成功の瞬間だけでなく、練習の中でも起きています。動くときは動きを、やり直すときはその経験を感じてください。意図と行動をつなげて。今日すべてを証明せずとも、戻るたびに力は育ちます。","th":"เรียนสิ่งไม่คุ้นต้องอดทน ลองซ้ำอาจน่าเบื่อหรือท้อ แต่การกระพือปีกมีความหมายก่อนนกบินค้างฟ้าได้ การเปลี่ยนเกิดในฝึกแล้ว ไม่ใช่เฉพาะสำเร็จท้ายสุด รู้สึกถึงการขยับขณะขยับ และเริ่มใหม่ขณะเริ่ม ให้การกระทำต่อกับเจตนา การกลับมาทุกครั้งสร้างกำลังได้โดยไม่ต้องพิสูจน์ทุกอย่างวันนี้","ar":"تعلّم غير المألوف يحتاج صبرًا. قد تبدو المحاولات متكررة ومحبطة، لكن رفّة الجناح مهمة قبل أن يبقى الطائر في السماء. التغيير يحدث داخل التدريب لا عند النجاح الأخير فقط. عش الحركة وأنت تتحرك والبداية وأنت تعود. صِل فعلك بنيتك؛ كل عودة تبني قدرة دون إثبات كل شيء اليوم."}},"questions":{"3":{"ja":{"q":"雨上がり、地面に小さな空が映っています。","a":["通り過ぎる前に、水たまりの空を見る","道の状態を見て、乾いた道を選ぶ"]},"th":{"q":"ฝนหยุดแล้ว มีท้องฟ้าสะท้อนอยู่บนพื้น","a":["ก้มดูเงาสะท้อนก่อนเดินอ้อม","ดูสภาพทางแล้วเลือกทางแห้ง"]},"ar":{"q":"توقف المطر وبقيت قطعة من السماء على الأرض.","a":["أنظر إلى الانعكاس قبل أن أتابع","أقيّم الطريق وأختار مسارًا جافًا"]}},"4":{"ja":{"q":"街角で、懐かしい歌が流れてきました。","a":["思い出がゆっくり戻るのに任せる","曲名を調べて、あとで聴くために保存する"]},"th":{"q":"เพลงเก่าดังขึ้นตรงมุมถนน","a":["ปล่อยให้ความทรงจำค่อย ๆ กลับมา","ดูชื่อเพลงแล้วบันทึกไว้ฟังทีหลัง"]},"ar":{"q":"تسمع أغنية قديمة عند زاوية الشارع.","a":["أدع ذكرى تعود بهدوء","أبحث عن اسمها وأحفظها لأسمعها لاحقًا"]}},"5":{"ja":{"q":"予定が急に取り消され、午後が空きました。","a":["今、自分がしたいことを感じてみる","午後の予定を組み直す"]},"th":{"q":"แผนถูกยกเลิกกะทันหัน บ่ายนี้ว่างแล้ว","a":["ลองดูว่าตอนนี้อยากทำอะไร","จัดตารางช่วงบ่ายใหม่"]},"ar":{"q":"أُلغي موعدك فجأة وأصبح بعد الظهر خاليًا.","a":["أتساءل عمّا أرغب فيه الآن","أعيد تنظيم خططي للمساء"]}},"6":{"ja":{"q":"友だちが、温かい水を渡してくれました。","a":["コップと手のひらの温もりを感じる","まず、倒れない場所に置く"]},"th":{"q":"เพื่อนยื่นน้ำอุ่นให้หนึ่งแก้ว","a":["รับรู้ความอุ่นของแก้วและฝ่ามือ","หาที่มั่นคงวางแก้วก่อน"]},"ar":{"q":"يقدّم لك صديق كوبًا من الماء الدافئ.","a":["أشعر بدفء الكوب وراحة يدي","أجد له مكانًا ثابتًا أولًا"]}},"7":{"ja":{"q":"今日は、すべてを終えられませんでした。","a":["少し疲れている自分を、まず認める","残ったことの優先順位をつけ直す"]},"th":{"q":"วันนี้ทำทุกอย่างไม่เสร็จ","a":["ยอมรับก่อนว่าตัวเองเหนื่อยนิดหน่อย","จัดลำดับความสำคัญของสิ่งที่เหลือใหม่"]},"ar":{"q":"لم تنهِ كل شيء اليوم.","a":["أعترف أولًا بأنني متعب قليلًا","أعيد ترتيب أولويات المهام المتبقية"]}},"8":{"ja":{"q":"思いがけず、手書きの手紙が届きました。","a":["文字を見たときの気持ちに気づく","まず読み終え、内容を整理する"]},"th":{"q":"ได้รับจดหมายเขียนมือที่ไม่คาดคิด","a":["สังเกตความรู้สึกเมื่อเห็นลายมือก่อน","อ่านจนจบแล้วเรียบเรียงเนื้อหา"]},"ar":{"q":"تصل رسالة بخط اليد على غير توقع.","a":["ألاحظ شعوري حين أرى الخط","أقرأها كاملة وأرتّب مضمونها"]}},"9":{"ja":{"q":"エレベーターで、知らない人が微笑みました。","a":["微笑み返し、小さな温かさを感じる","会釈して、考えていたことに戻る"]},"th":{"q":"คนแปลกหน้ายิ้มให้ในลิฟต์","a":["ยิ้มกลับแล้วรู้สึกอุ่นใจเล็กน้อย","พยักหน้าทักแล้วคิดเรื่องเดิมต่อ"]},"ar":{"q":"يبتسم لك شخص غريب في المصعد.","a":["أبتسم وأشعر بقليل من الدفء","أومئ وأعود إلى أفكاري"]}},"10":{"ja":{"q":"曲がりながら育つ木を見つけました。","a":["その木らしい形だと感じる","何が成長に影響したのか考える"]},"th":{"q":"เห็นต้นไม้เติบโตเอียงโค้ง","a":["ชื่นชมรูปร่างที่เป็นของมัน","สงสัยว่าอะไรมีผลต่อการเติบโต"]},"ar":{"q":"تلاحظ شجرة تنمو مائلة.","a":["أقدّر شكلها الخاص","أتساءل عمّا أثّر في نموّها"]}},"11":{"ja":{"q":"食事の味が、記憶の中の味に似ています。","a":["一緒に食べた人を思い出す","食材や調味料を考える"]},"th":{"q":"อาหารมื้อนี้มีรสคล้ายในความทรงจำ","a":["นึกถึงคนที่เคยกินด้วยกัน","แยกแยะว่าใช้วัตถุดิบและเครื่องปรุงอะไร"]},"ar":{"q":"يشبه طعم وجبة شيئًا من ذكرياتك.","a":["أتذكر من شاركني الطعام","أميّز المكونات والتوابل"]}},"12":{"ja":{"q":"まだ答えのないことに向き合っています。","a":["わからないままでいる余地を、自分に許す","わかっている条件と次の一歩を書き出す"]},"th":{"q":"กำลังเผชิญเรื่องที่ยังไม่มีคำตอบ","a":["ให้พื้นที่ตัวเองยอมรับสิ่งที่ยังไม่รู้","จดสิ่งที่รู้และขั้นตอนต่อไป"]},"ar":{"q":"تواجه أمرًا بلا إجابة واضحة بعد.","a":["أفسح مجالًا لعدم اليقين","أدوّن المعطيات والخطوة التالية"]}},"13":{"ja":{"q":"写真の中で、少し不揃いに笑っています。","a":["そのくつろいだ瞬間が好きだと思う","構図のよい別の写真を選ぶ"]},"th":{"q":"ในรูป คุณยิ้มไม่ค่อยเป๊ะ","a":["ชอบช่วงเวลาที่ผ่อนคลายนั้น","เลือกรูปที่องค์ประกอบดีกว่า"]},"ar":{"q":"ابتسامتك غير مثالية في صورة.","a":["أحب تلك اللحظة العفوية","أختار صورة بتكوين أفضل"]}},"14":{"ja":{"q":"夜遅く、窓の外にまだ灯りが見えます。","a":["あそこにも起きている人がいると想像する","時刻を見て、休む時間を決める"]},"th":{"q":"ดึกแล้ว ข้างนอกยังมีไฟดวงหนึ่ง","a":["นึกภาพว่าตรงนั้นมีคนยังตื่นอยู่","ดูเวลาแล้วตัดสินใจว่าจะพักเมื่อไร"]},"ar":{"q":"في وقت متأخر، لا تزال نافذة مضاءة.","a":["أتخيّل شخصًا آخر ما زال مستيقظًا","أنظر إلى الوقت وأخطط لراحتي"]}},"15":{"ja":{"q":"小さなことを、ひとつ終えました。","a":["心の中で、そっと「できた」と言う","リストから消して、次へ進む"]},"th":{"q":"เพิ่งทำเรื่องเล็ก ๆ เสร็จ","a":["บอกตัวเองเบา ๆ ว่าทำได้แล้ว","ขีดออกจากรายการแล้วเริ่มเรื่องต่อไป"]},"ar":{"q":"أنجزت للتو مهمة صغيرة.","a":["أقرّ في داخلي بهدوء: لقد فعلتها","أشطبها من القائمة وأنتقل للتالية"]}},"16":{"ja":{"q":"誰かが、心を込めて名前を呼びました。","a":["自分を見てもらえた瞬間を感じる","振り返って、用件を確かめる"]},"th":{"q":"มีคนเรียกชื่อคุณอย่างใส่ใจ","a":["สังเกตช่วงเวลาที่รู้สึกว่ามีคนมองเห็น","หันไปดูว่าเขาต้องการอะไร"]},"ar":{"q":"يناديك أحدهم باسمك باهتمام.","a":["ألاحظ شعور أنني مرئي","ألتفت لأعرف ما يحتاجه"]}},"17":{"ja":{"q":"風が吹き、机の紙が散らばりました。","a":["少し止まって、風を感じる","元の順番に整える"]},"th":{"q":"ลมพัดกระดาษบนโต๊ะกระจัดกระจาย","a":["หยุดสักนิดเพื่อรู้สึกถึงลม","จัดกระดาษตามลำดับเดิม"]},"ar":{"q":"بعثر النسيم أوراق مكتبك.","a":["أتوقف قليلًا لأشعر بالنسيم","أعيد الأوراق إلى ترتيبها"]}},"18":{"ja":{"q":"週末の朝、部屋は静かです。","a":["もう少し横になり、周りの音を聴く","予定を確認し、一日を始める"]},"th":{"q":"ตื่นวันหยุด ห้องเงียบมาก","a":["นอนต่ออีกนิดแล้วฟังเสียงรอบตัว","ดูตารางและเตรียมเริ่มวัน"]},"ar":{"q":"تستيقظ في عطلة الأسبوع والغرفة هادئة.","a":["أبقى قليلًا وأصغي لما حولي","أراجع الجدول وأستعد لليوم"]}},"19":{"ja":{"q":"長く使った物が、うまく働かなくなりました。","a":["一緒に過ごした日々を思い出す","修理と買い替えの費用を比べる"]},"th":{"q":"ของเก่าชิ้นหนึ่งใช้ไม่ค่อยดีแล้ว","a":["นึกถึงวันที่มันอยู่เป็นเพื่อน","เทียบค่าซ่อมกับซื้อใหม่"]},"ar":{"q":"لم يعد غرض قديم يعمل جيدًا.","a":["أتذكر الأيام التي رافقني فيها","أقارن تكلفة الإصلاح والاستبدال"]}},"20":{"ja":{"q":"夕日が部屋を金色に染めています。","a":["手を止めて、しばらく眺める","写真を撮って、作業を続ける"]},"th":{"q":"แสงเย็นย้อมห้องเป็นสีทอง","a":["วางสิ่งที่ทำแล้วมองสักพัก","ถ่ายรูปแล้วทำงานต่อ"]},"ar":{"q":"يملأ الغروب غرفتك بلون ذهبي.","a":["أتوقف وأتأمل قليلًا","ألتقط صورة وأواصل عملي"]}}}};
